/// The full-text field of whichever `Configure*` modal is open, read-only.
/// Only the tests read a configure field without intending to mutate it.
#[cfg(test)]
fn configure_project_text_input(prompt: &PromptState) -> Option<&TextInput> {
    match prompt {
        PromptState::ConfigureStartupCommand { input, .. }
        | PromptState::ConfigureProjectEnv { input, .. }
        | PromptState::ConfigureGlobalEnv { input, .. } => Some(input),
        _ => None,
    }
}

/// Which control has focus in whichever `Configure*` modal is open.
fn configure_focus(prompt: &PromptState) -> Option<ConfigureFieldFocus> {
    match prompt {
        PromptState::ConfigureStartupCommand { focus, .. }
        | PromptState::ConfigureProjectEnv { focus, .. }
        | PromptState::ConfigureGlobalEnv { focus, .. } => Some(*focus),
        _ => None,
    }
}

/// Point focus at one of the configure modal's controls. Focusing anything
/// other than the field leaves edit mode, so focus can never sit on a button
/// while the field still swallows keystrokes.
fn set_configure_focus(prompt: &mut PromptState, next: ConfigureFieldFocus) {
    match prompt {
        PromptState::ConfigureStartupCommand { focus, .. }
        | PromptState::ConfigureProjectEnv { focus, .. }
        | PromptState::ConfigureGlobalEnv { focus, .. } => *focus = next,
        _ => {}
    }
}

fn configure_project_text_input_mut(prompt: &mut PromptState) -> Option<&mut TextInput> {
    match prompt {
        PromptState::ConfigureStartupCommand { input, .. }
        | PromptState::ConfigureProjectEnv { input, .. }
        | PromptState::ConfigureGlobalEnv { input, .. } => Some(input),
        _ => None,
    }
}

/// Maximum size of `loading_input_buf`. During the loading phase we
/// accumulate bytes only to detect a (possibly multi-byte) ToggleFullscreen
/// binding. Since any realistic binding fits in well under this cap, we
/// truncate to the trailing window to bound memory and scan cost even when
/// the user pastes large amounts of text while the agent is starting.
const LOADING_INPUT_BUF_MAX: usize = 64;

/// Append `bytes` to `buf`, keeping at most `max` trailing bytes. Used to
/// bound `loading_input_buf` so it cannot grow without bound when the user
/// pastes large content during the agent loading phase.
fn append_capped(buf: &mut Vec<u8>, bytes: &[u8], max: usize) {
    if bytes.len() >= max {
        // The new chunk alone fills or exceeds the cap: drop prior state
        // and keep only the trailing `max` bytes of the new chunk.
        buf.clear();
        buf.extend_from_slice(&bytes[bytes.len() - max..]);
        return;
    }
    buf.extend_from_slice(bytes);
    if buf.len() > max {
        let drop = buf.len() - max;
        buf.drain(..drop);
    }
}

/// Treat both crossterm's `BackTab` and explicit `Tab + Shift` as reverse-tab.
/// Some terminals deliver one form, some the other.
fn is_reverse_tab(key: KeyEvent) -> bool {
    matches!(key.code, KeyCode::BackTab)
        || (matches!(key.code, KeyCode::Tab) && key.modifiers.contains(KeyModifiers::SHIFT))
}

/// Whether a focus-movement key means "backwards".
///
/// The movement action carries no direction of its own, so the key that
/// triggered it supplies one: `Shift-Tab`/`BackTab` and the two conventional
/// "left" keys walk backwards, and anything else walks forwards. This is a
/// directional hint for the default key set, not a hardcoded binding: a
/// rebound key simply moves forwards.
fn focus_move_is_reverse(key: KeyEvent) -> bool {
    is_reverse_tab(key) || matches!(key.code, KeyCode::Left | KeyCode::Char('h'))
}

