    fn handle_rename_session_prompt_key(&mut self, key: KeyEvent) -> Option<bool> {
        let PromptState::RenameSession { focus, .. } = &self.prompt else {
            return None;
        };
        let checkbox_focused = *focus == RenameSessionFocus::RenameBranchCheckbox;
        let action = if binding_lookup_is_suppressed(key, !checkbox_focused) {
            None
        } else {
            self.bindings.lookup(&key, BindingScope::Dialog)
        };
        match modal_key_step(action, key, !checkbox_focused) {
            ModalKeyStep::Close => self.prompt = PromptState::None,
            ModalKeyStep::Confirm => {
                let PromptState::RenameSession {
                    session_id,
                    input,
                    rename_branch,
                    ..
                } = &self.prompt
                else {
                    unreachable!()
                };
                let id = session_id.clone();
                let new_name = input.text.clone();
                let also_rename_branch = *rename_branch;
                self.prompt = PromptState::None;
                self.apply_rename_session(&id, new_name, also_rename_branch);
            }
            ModalKeyStep::MoveFocus(forward) => self.focus_next_rename_session_control(forward),
            ModalKeyStep::ActivateFocus if checkbox_focused => {
                self.toggle_rename_session_branch();
            }
            ModalKeyStep::ActivateFocus => {}
            ModalKeyStep::FallThroughToField => {
                if !checkbox_focused
                    && let PromptState::RenameSession { input, .. } = &mut self.prompt
                {
                    input.handle_key(key);
                }
            }
        }
        Some(false)
    }

    fn create_agent_request_message(request: &CreateAgentRequest, name: &str) -> String {
        match request {
            CreateAgentRequest::NewProject { project, .. } => format!(
                "Creating a new agent worktree \"{name}\" for project \"{}\" and launching a fresh session...",
                project.name
            ),
            CreateAgentRequest::PullRequest {
                project, number, ..
            } => format!(
                "Creating a new agent worktree \"{name}\" from PR #{number} for project \"{}\" and launching a fresh session...",
                project.name
            ),
            CreateAgentRequest::Standalone { folder, .. } => format!(
                "Creating a standalone agent \"{name}\" in \"{}\"...",
                dux_core::home_path::shorten_home(folder)
            ),
            CreateAgentRequest::ForkSession { source_label, .. } => format!(
                "Forking agent \"{source_label}\" as \"{name}\" by cloning its current worktree contents into a fresh session...",
            ),
            CreateAgentRequest::ExistingManagedWorktree {
                project,
                worktree_path,
                ..
            } => format!(
                "Starting agent \"{name}\" in existing worktree {} for project \"{}\"...",
                worktree_path.display(),
                project.name
            ),
            CreateAgentRequest::ForkExternalWorktree {
                project,
                source_label,
                ..
            } => format!(
                "Copying external worktree \"{source_label}\" into a managed worktree \"{name}\" for project \"{}\"...",
                project.name
            ),
        }
    }

    fn confirm_name_new_agent_prompt(&mut self) -> Result<()> {
        let name = match &self.prompt {
            PromptState::NameNewAgent { input, .. } => input.text.trim().to_string(),
            _ => return Ok(()),
        };
        if name.is_empty() {
            self.set_error("Agent name cannot be empty.");
            self.prompt = PromptState::None;
            return Ok(());
        }
        if !git::is_valid_agent_name(&name) {
            self.set_error(
                "Agent name may only contain letters, digits, dashes, underscores, or slashes. \
                 It cannot start with \"-\" or \"/\", end with \"/\", or contain \"//\".",
            );
            return Ok(());
        }

        let old_prompt = std::mem::replace(&mut self.prompt, PromptState::None);
        let PromptState::NameNewAgent {
            mut request,
            copy_changes,
            ..
        } = old_prompt
        else {
            unreachable!()
        };
        if let CreateAgentRequest::NewProject {
            copy_uncommitted_changes,
            ..
        } = &mut request
        {
            *copy_uncommitted_changes = copy_changes;
        }

        if let CreateAgentRequest::NewProject { project, .. } = &request {
            let repo_path = std::path::PathBuf::from(&project.path);
            if let git::CreateAgentBranchPlan::ExistingBranch { location } =
                git::create_agent_branch_preflight(&repo_path, &name)
            {
                set_create_agent_request_custom_name(&mut request, name.clone());
                self.prompt = PromptState::ConfirmUseExistingBranch {
                    request,
                    branch_name: name,
                    location,
                    focus: ConfirmFocus::Cancel,
                };
                return Ok(());
            }
        }

        let message = Self::create_agent_request_message(&request, &name);
        set_create_agent_request_custom_name(&mut request, name);
        self.dispatch_create_agent_request(request, message)
    }

    fn handle_name_new_agent_prompt_key(&mut self, key: KeyEvent) -> Result<Option<bool>> {
        let PromptState::NameNewAgent { focus, .. } = &self.prompt else {
            return Ok(None);
        };
        let checkbox_focused = matches!(
            focus,
            NameNewAgentFocus::RandomizedNameCheckbox | NameNewAgentFocus::CopyChangesCheckbox
        );
        let action = if !checkbox_focused && text_field_owns_key(key) {
            None
        } else {
            self.bindings.lookup(&key, BindingScope::Dialog)
        };
        match action {
            Some(Action::CloseOverlay) => self.prompt = PromptState::None,
            Some(Action::ToggleSelection) => {
                self.focus_next_name_new_agent_control(!focus_move_is_reverse(key));
            }
            Some(Action::Confirm) => self.confirm_name_new_agent_prompt()?,
            _ if checkbox_focused && key.code == KeyCode::Char(' ') => {
                self.toggle_focused_name_new_agent_checkbox();
            }
            _ if !checkbox_focused => {
                if let PromptState::NameNewAgent { input, .. } = &mut self.prompt {
                    input.handle_key(key);
                }
            }
            _ => {}
        }
        Ok(Some(false))
    }

    fn handle_form_prompt_key(&mut self, key: KeyEvent) -> Result<Option<bool>> {
        if matches!(self.prompt, PromptState::EditMacros { .. }) {
            self.handle_edit_macros_key(key)?;
            return Ok(Some(false));
        }
        if let Some(exit) = self.handle_pull_request_input_prompt_key(key)? {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_attach_pull_request_input_prompt_key(key)? {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_name_new_agent_prompt_key(key)? {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_name_standalone_agent_prompt_key(key) {
            return Ok(Some(exit));
        }
        Ok(self.handle_rename_session_prompt_key(key))
    }

    fn handle_monitoring_prompt_key(&mut self, key: KeyEvent) -> Option<bool> {
        if let Some(exit) = self.handle_resource_monitor_prompt_key(key) {
            return Some(exit);
        }
        self.handle_debug_input_prompt_key(key)
    }

    fn handle_picker_prompt_key(&mut self, key: KeyEvent) -> Result<Option<bool>> {
        if let Some(exit) = self.handle_command_palette_prompt_key(key) {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_kill_running_prompt_key(key)? {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_project_browser_prompt_key(key) {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_pick_editor_prompt_key(key) {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_manage_worktrees_prompt_key(key) {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_pick_project_worktree_prompt_key(key)? {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_pick_project_prompt_key(key)? {
            return Ok(Some(exit));
        }
        if let Some(which) = provider_picker_kind(&self.prompt) {
            return Ok(Some(self.handle_provider_picker_key(key, which)?));
        }
        if let Some(exit) = self.handle_set_tailscale_mode_prompt_key(key) {
            return Ok(Some(exit));
        }
        if let Some(exit) = self.handle_change_theme_prompt_key(key)? {
            return Ok(Some(exit));
        }
        Ok(self.handle_startup_logs_prompt_key(key))
    }

    fn handle_notice_prompt_key(&mut self, key: KeyEvent) -> Option<bool> {
        if let Some(exit) = self.handle_config_reload_failed_prompt_key(key) {
            return Some(exit);
        }
        if let Some(exit) = self.handle_add_project_failed_prompt_key(key) {
            return Some(exit);
        }
        if let Some(exit) = self.handle_first_load_prompt_key(key) {
            return Some(exit);
        }
        self.handle_agent_info_prompt_key(key)
    }

    fn handle_prompt_key(&mut self, key: KeyEvent) -> Result<bool> {
        // Any keystroke cancels a held mouse press, preventing its release from
        // firing an action after the user has switched to the keyboard.
        self.pressed_button = None;

        if let Some(should_exit) = self.handle_monitoring_prompt_key(key) {
            return Ok(should_exit);
        }

        if let Some(should_exit) = self.handle_picker_prompt_key(key)? {
            return Ok(should_exit);
        }

        if let Some(focus) = configure_focus(&self.prompt) {
            return self.handle_configure_modal_key(key, focus);
        }

        if let Some(should_exit) = self.handle_notice_prompt_key(key) {
            return Ok(should_exit);
        }

        if let Some(should_exit) = self.handle_confirmation_prompt_key(key) {
            return Ok(should_exit);
        }

        if let Some(should_exit) = self.handle_form_prompt_key(key)? {
            return Ok(should_exit);
        }

        Ok(false)
    }

    /// Whether the macro editor's multiline body is engaged for typing.
    ///
    /// The engage step exists for exactly one reason: **Enter is content in a
    /// multiline field and is also the confirm key in every modal.** Tab is NOT
    /// content (dux cannot insert a tab character anywhere), so the mode is
    /// deliberately not built around Tab. Mirrors
    /// [`PromptState::ConfigureStartupCommand`]'s contract.
    pub(super) fn macro_text_engaged(&self) -> bool {
        self.input_target == InputTarget::MacroText
    }

    /// The macro editor's current focus, or `None` when the editor is not open.
    fn macro_edit_focus(&self) -> Option<MacroEditFocus> {
        match &self.prompt {
            PromptState::EditMacros {
                editing: Some(state),
                pending_delete: None,
                ..
            } => Some(state.focus),
            _ => None,
        }
    }

    /// The one handler behind all three provider pickers.
    ///
    /// A Picker's vertical keys move a SELECTION (a value), the close key
    /// cancels and the confirm key picks. Only the last of those differs
    /// between the three, and it differs by exactly one call.
    fn handle_provider_picker_key(
        &mut self,
        key: KeyEvent,
        which: ProviderPickerKind,
    ) -> Result<bool> {
        let action = self
            .bindings
            .lookup(&key, BindingScope::Palette)
            .or_else(|| self.bindings.lookup(&key, BindingScope::Dialog));
        match action {
            Some(Action::CloseOverlay) => {
                self.prompt = PromptState::None;
            }
            Some(Action::MoveDown) => self.move_provider_picker_selection(true),
            Some(Action::MoveUp) => self.move_provider_picker_selection(false),
            Some(Action::Confirm) => match which {
                ProviderPickerKind::Agent => self.apply_change_agent_provider()?,
                ProviderPickerKind::GlobalDefault => self.apply_change_default_provider()?,
                ProviderPickerKind::ProjectDefault => {
                    self.apply_change_project_default_provider()?
                }
            },
            _ => {}
        }
        Ok(false)
    }

    /// Step the open provider picker's selection cursor, clamped at both ends.
    fn move_provider_picker_selection(&mut self, forward: bool) {
        let (selected, len) = match &mut self.prompt {
            PromptState::ChangeAgentProvider(prompt) => {
                let len = prompt.options.len();
                (&mut prompt.selected, len)
            }
            PromptState::ChangeDefaultProvider(prompt) => {
                let len = prompt.options.len();
                (&mut prompt.selected, len)
            }
            PromptState::ChangeProjectDefaultProvider(prompt) => {
                let len = prompt.options.len();
                (&mut prompt.selected, len)
            }
            _ => return,
        };
        if forward {
            if *selected + 1 < len {
                *selected += 1;
            }
        } else if *selected > 0 {
            *selected -= 1;
        }
    }

    fn handle_edit_macros_key(&mut self, key: KeyEvent) -> Result<bool> {
        if matches!(
            self.prompt,
            PromptState::EditMacros {
                pending_delete: Some(_),
                ..
            }
        ) {
            return self.handle_confirm_delete_macro_key(key);
        }

        if let Some(focus) = self.macro_edit_focus() {
            return self.handle_macro_editor_key(key, focus);
        }

        let PromptState::EditMacros {
            entries,
            selected,
            editing,
            ..
        } = &mut self.prompt
        else {
            return Ok(false);
        };

        // ── List view: an ordinary Picker ─────────────────────────────────
        //
        // Every key is resolved through the bindings, exactly as the provider
        // and theme pickers resolve theirs. The list used to hardcode `Esc`,
        // `j`/`k`, `Enter`, `n` and `d`, so a user who rebound any of them got
        // a footer naming one key and a modal answering another. The modal's
        // own scope is consulted first (it owns the two macro-specific
        // actions), then the shared picker vocabulary.
        let action = self
            .bindings
            .lookup(&key, BindingScope::MacroList)
            .or_else(|| self.bindings.lookup(&key, BindingScope::Palette))
            .or_else(|| self.bindings.lookup(&key, BindingScope::Dialog));
        match action {
            Some(Action::CloseOverlay) => {
                self.prompt = PromptState::None;
            }
            Some(Action::MoveDown) if !entries.is_empty() && *selected + 1 < entries.len() => {
                *selected += 1;
            }
            Some(Action::MoveUp) if *selected > 0 => {
                *selected -= 1;
            }
            Some(Action::Confirm) => {
                self.open_selected_macro_for_edit();
            }
            Some(Action::NewMacro) => {
                *editing = Some(MacroEditState {
                    id: None,
                    name_input: TextInput::new(),
                    text_input: TextInput::new().with_multiline(8),
                    surface: MacroSurface::default(),
                    focus: MacroEditFocus::Name,
                });
            }
            Some(Action::DeleteMacro) => {
                // Stage confirmation for deleting the selected macro.
                if let Some((name, _, _)) = entries.get(*selected) {
                    let name = name.clone();
                    let PromptState::EditMacros { pending_delete, .. } = &mut self.prompt else {
                        return Ok(false);
                    };
                    *pending_delete = Some(PendingMacroDelete {
                        name,
                        focus: ConfirmFocus::Cancel,
                    });
                }
            }
            _ => {}
        }
        Ok(false)
    }

    /// Open the highlighted macro in the editor. Shared by the confirm key and
    /// by a double click on the row, so the two cannot drift.
    pub(super) fn open_selected_macro_for_edit(&mut self) {
        let PromptState::EditMacros {
            entries,
            selected,
            editing,
            ..
        } = &mut self.prompt
        else {
            return;
        };
        let Some((name, text, surface)) = entries.get(*selected) else {
            return;
        };
        let name = name.clone();
        let text = text.clone();
        let surface = *surface;
        *editing = Some(MacroEditState {
            id: Some(name.clone()),
            name_input: TextInput::with_text(name),
            text_input: TextInput::with_text(text).with_multiline(8),
            surface,
            focus: MacroEditFocus::Name,
        });
    }

    /// Move the macro list's selection cursor, as a click on a row does.
    pub(super) fn set_macro_list_selection(&mut self, index: usize) {
        if let PromptState::EditMacros {
            entries, selected, ..
        } = &mut self.prompt
            && index < entries.len()
        {
            *selected = index;
        }
    }

    /// The macro EDITOR's key handling: an ordinary modal with a focus model.
    ///
    /// Movement keys move focus and change nothing. Space acts on whatever has
    /// focus (types a space in a text field, advances the selector, activates a
    /// button). Escape cancels — except inside the engaged body, where it exits
    /// edit mode and leaves the modal open, the same contract
    /// `configure_startup_command_escape_exits_edit_mode_only` pins.
    fn handle_macro_editor_key(&mut self, key: KeyEvent, focus: MacroEditFocus) -> Result<bool> {
        // ── The engaged body owns every key but the exit binding ──────────
        if focus == MacroEditFocus::Text && self.macro_text_engaged() {
            if let Some(Action::ExitCommitInput) =
                self.bindings.lookup(&key, BindingScope::CommitInput)
            {
                self.input_target = InputTarget::None;
                return Ok(false);
            }
            let clear = matches!(
                self.bindings.lookup(&key, BindingScope::CommitInput),
                Some(Action::ClearTextField)
            );
            if let Some(state) = self.macro_edit_state_mut() {
                if clear {
                    state.text_input.clear();
                } else {
                    state.text_input.handle_key(key);
                }
            }
            return Ok(false);
        }

        // A focused text field owns the plain characters and the horizontal
        // arrows, so those never reach the bindings and can never be read as a
        // movement key. Same predicate the rename/new-agent modals use, and the
        // same one the footer picks its hint keys with.
        //
        // `owns_keys` and not `is_text_field`: the UNENGAGED body takes no
        // keystrokes at all, so it owns none of them, and the movement keys
        // must keep working while focus is parked on it.
        let owned_by_field = focus.owns_keys(self.macro_text_engaged()) && text_field_owns_key(key);
        let action = if owned_by_field {
            None
        } else {
            self.bindings.lookup(&key, BindingScope::Dialog)
        };

        // Space is hardcoded, never a binding: it is the universal "act on the
        // focused control" key.
        let is_space = key.code == KeyCode::Char(' ');

        match action {
            Some(Action::CloseOverlay) => {
                self.cancel_macro_edit();
                return Ok(false);
            }
            Some(Action::ToggleSelection) => {
                self.focus_next_macro_edit_control(!focus_move_is_reverse(key));
                return Ok(false);
            }
            Some(Action::ClearTextField) if focus == MacroEditFocus::Text => {
                // "Empty the FOCUSED full-text field", which the body is
                // whether or not it is engaged. It used to answer only from
                // inside the engaged branch, so the key was dead on exactly the
                // state the modal opens the body in.
                if let Some(state) = self.macro_edit_state_mut() {
                    state.text_input.clear();
                }
                return Ok(false);
            }
            Some(Action::Confirm) => {
                // Enter acts on the focused control. On the unengaged BODY that
                // means ENGAGE, not save: Enter is content once the body is
                // engaged, so it cannot also mean submit, and the Save button
                // is what carries that meaning instead. From the single-line
                // name field, from the selector, and from Save it submits.
                match focus {
                    MacroEditFocus::Cancel => self.cancel_macro_edit(),
                    MacroEditFocus::Text => self.engage_macro_text(),
                    _ => self.save_macro_edit(),
                }
                return Ok(false);
            }
            _ => {}
        }

        match focus {
            MacroEditFocus::Surface if is_space => {
                if let Some(state) = self.macro_edit_state_mut() {
                    state.surface = state.surface.next();
                }
            }
            MacroEditFocus::Cancel if is_space => self.cancel_macro_edit(),
            MacroEditFocus::Save if is_space => self.save_macro_edit(),
            MacroEditFocus::Name => {
                if let Some(state) = self.macro_edit_state_mut() {
                    state.name_input.handle_key(key);
                }
            }
            MacroEditFocus::Text => {
                // Unengaged body: engaging is an explicit act, never a side
                // effect of typing. The vim-style affordance is not hardcoded,
                // `EngageCommitInput` already defaults to `i`, so resolving it
                // through the bindings gives the vim key and honours a rebind.
                if matches!(
                    self.bindings.lookup(&key, BindingScope::Files),
                    Some(Action::EngageCommitInput)
                ) {
                    self.engage_macro_text();
                }
            }
            MacroEditFocus::Surface | MacroEditFocus::Cancel | MacroEditFocus::Save => {}
        }
        Ok(false)
    }

    /// The three `Configure*` modals' key handling: an ordinary modal with a
    /// focus model over one full-text field and a Cancel/Save pair.
    ///
    /// Built to read exactly like [`App::handle_macro_editor_key`], because
    /// they are the same shape: an engaged full-text field owns every key but
    /// the exit binding, movement keys move focus and change nothing, Space
    /// acts on whatever has focus, and Escape abandons (or, inside the engaged
    /// field, only leaves edit mode).
    fn handle_configure_modal_key(
        &mut self,
        key: KeyEvent,
        focus: ConfigureFieldFocus,
    ) -> Result<bool> {
        // ── The engaged field owns every key but the exit binding ─────────
        if self.input_target == InputTarget::StartupCommand {
            self.handle_startup_command_input_key(key)?;
            return Ok(false);
        }

        // "Empty the FOCUSED full-text field": the body has to have focus. It
        // used to answer from every stop, which read as a modal-wide "clear"
        // and disagreed with both the help text and the macro editor, whose
        // body is one focus stop among five.
        if focus == ConfigureFieldFocus::Input
            && matches!(
                self.bindings.lookup(&key, BindingScope::Dialog),
                Some(Action::ClearTextField)
            )
        {
            if let Some(input) = configure_project_text_input_mut(&mut self.prompt) {
                input.clear();
            }
            return Ok(false);
        }

        // An UNENGAGED full-text field takes no keystrokes, so it owns none:
        // the movement keys and plain characters are the modal's while the
        // field is not engaged. (A single-line field would own them, which is
        // why the macro editor's name field is gated the other way.)
        let action = self
            .bindings
            .lookup(&key, BindingScope::Palette)
            .or_else(|| self.bindings.lookup(&key, BindingScope::Dialog));

        // Space is hardcoded, never a binding: it is the universal "act on the
        // focused control" key.
        let is_space = key.code == KeyCode::Char(' ');

        match action {
            Some(Action::CloseOverlay) => {
                self.cancel_configure_modal();
                return Ok(false);
            }
            Some(Action::ToggleSelection) => {
                self.focus_next_configure_control(!focus_move_is_reverse(key));
                return Ok(false);
            }
            Some(Action::Confirm) => {
                // The confirm key acts on the focused control. On the body that
                // means ENGAGE, not save: Enter is content once the field is
                // engaged, so it cannot also mean submit, and the Save button
                // is what carries that meaning instead.
                match focus {
                    ConfigureFieldFocus::Input => self.engage_configure_field(),
                    ConfigureFieldFocus::Cancel => self.cancel_configure_modal(),
                    ConfigureFieldFocus::Save => self.apply_configure_modal()?,
                }
                return Ok(false);
            }
            _ => {}
        }

        match focus {
            ConfigureFieldFocus::Cancel if is_space => self.cancel_configure_modal(),
            ConfigureFieldFocus::Save if is_space => self.apply_configure_modal()?,
            ConfigureFieldFocus::Input => {
                // The vim-style engage affordance. It is not hardcoded here:
                // `EngageCommitInput` already defaults to `i`, so resolving it
                // through the bindings gives the vim key out of the box and
                // still honours a rebind.
                if matches!(
                    self.bindings.lookup(&key, BindingScope::Files),
                    Some(Action::EngageCommitInput)
                ) {
                    self.engage_configure_field();
                }
            }
            ConfigureFieldFocus::Cancel | ConfigureFieldFocus::Save => {}
        }
        Ok(false)
    }

    /// Start editing the configure modal's full-text field, caret at the end.
    fn engage_configure_field(&mut self) {
        self.input_target = InputTarget::StartupCommand;
        set_configure_focus(&mut self.prompt, ConfigureFieldFocus::Input);
        if let Some(input) = configure_project_text_input_mut(&mut self.prompt) {
            input.move_end();
        }
    }

    /// Move focus between the configure modal's controls. Leaving the field
    /// always drops edit mode, so focus can never sit on a button while the
    /// field still swallows keystrokes.
    fn focus_next_configure_control(&mut self, forward: bool) {
        self.input_target = InputTarget::None;
        if let Some(focus) = configure_focus(&self.prompt) {
            set_configure_focus(&mut self.prompt, focus.step(forward));
        }
    }

    /// Point focus at one control, for the mouse. Focusing anything other than
    /// the field leaves edit mode.
    pub(super) fn focus_configure_control(&mut self, focus: ConfigureFieldFocus) {
        if focus != ConfigureFieldFocus::Input {
            self.input_target = InputTarget::None;
        }
        set_configure_focus(&mut self.prompt, focus);
    }

    /// Abandon the configure modal. Writes nothing: Escape never saves.
    pub(super) fn cancel_configure_modal(&mut self) {
        self.prompt = PromptState::None;
        self.input_target = InputTarget::None;
    }

    /// Commit whichever configure modal is open.
    pub(super) fn apply_configure_modal(&mut self) -> Result<()> {
        match self.prompt {
            PromptState::ConfigureGlobalEnv { .. } => self.apply_configure_global_env(),
            PromptState::ConfigureProjectEnv { .. } => self.apply_configure_project_env(),
            PromptState::ConfigureStartupCommand { .. } => self.apply_configure_startup_command(),
            _ => Ok(()),
        }
    }

    fn macro_edit_state_mut(&mut self) -> Option<&mut MacroEditState> {
        match &mut self.prompt {
            PromptState::EditMacros {
                editing: Some(state),
                ..
            } => Some(state),
            _ => None,
        }
    }

    /// Move focus between the macro editor's controls.
    ///
    /// Leaving the body always drops edit mode, so focus can never sit on a
    /// different control while the body still swallows keystrokes.
    pub(super) fn focus_next_macro_edit_control(&mut self, forward: bool) {
        self.input_target = InputTarget::None;
        if let Some(state) = self.macro_edit_state_mut() {
            state.focus = state.focus.step(forward);
        }
    }

    /// Point focus at one control, for the mouse. Focusing anything other than
    /// the body leaves edit mode.
    pub(super) fn focus_macro_edit_control(&mut self, focus: MacroEditFocus) {
        if focus != MacroEditFocus::Text {
            self.input_target = InputTarget::None;
        }
        if let Some(state) = self.macro_edit_state_mut() {
            state.focus = focus;
        }
    }

    /// Start editing the macro body, caret at the end.
    fn engage_macro_text(&mut self) {
        self.input_target = InputTarget::MacroText;
        if let Some(state) = self.macro_edit_state_mut() {
            state.focus = MacroEditFocus::Text;
            state.text_input.move_end();
        }
    }

    /// Abandon the edit and return to the macro list. Writes nothing.
    pub(super) fn cancel_macro_edit(&mut self) {
        if self.macro_text_engaged() {
            self.input_target = InputTarget::None;
        }
        if let PromptState::EditMacros { editing, .. } = &mut self.prompt {
            *editing = None;
        }
    }

    /// Write the edited macro to config and return to the macro list.
    ///
    /// Refuses (and says why, keeping the modal open) on an empty name, an
    /// empty body, or a name already taken by a different macro.
    pub(super) fn save_macro_edit(&mut self) {
        let Some(state) = self.macro_edit_state_mut() else {
            return;
        };
        let name = state.name_input.text.trim().to_string();
        let text = state.text_input.text.clone();
        let surface = state.surface;
        let old_id = state.id.clone();

        if name.is_empty() {
            self.set_warning("A macro needs a name before it can be saved.");
            return;
        }
        if text.is_empty() {
            self.set_warning(format!(
                "Macro \"{name}\" has no text yet, so nothing was saved."
            ));
            return;
        }

        let PromptState::EditMacros { entries, .. } = &self.prompt else {
            return;
        };
        let taken = entries
            .iter()
            .any(|(n, _, _)| *n == name && old_id.as_deref() != Some(n.as_str()));
        if taken {
            self.set_warning(format!(
                "Name \"{name}\" is already in use. Choose another."
            ));
            return;
        }

        // If renaming, drop the old entry so the rename does not duplicate it.
        if let Some(ref old_name) = old_id
            && *old_name != name
        {
            self.engine.config.macros.entries.shift_remove(old_name);
        }
        self.engine.config.macros.entries.insert(
            name.clone(),
            crate::config::MacroEntry {
                text: text.clone(),
                surface,
            },
        );

        if self.macro_text_engaged() {
            self.input_target = InputTarget::None;
        }
        let PromptState::EditMacros {
            entries, editing, ..
        } = &mut self.prompt
        else {
            return;
        };
        *editing = None;
        if let Some(old_name) = old_id {
            if let Some(existing) = entries.iter_mut().find(|(n, _, _)| *n == old_name) {
                existing.0 = name.clone();
                existing.1 = text;
                existing.2 = surface;
            } else {
                entries.push((name.clone(), text, surface));
            }
        } else {
            entries.push((name.clone(), text, surface));
        }
        entries.sort_by(|(a, _, _), (b, _, _)| a.cmp(b));

        if let Err(err) = self
            .engine
            .config_writer
            .save_eager(self.engine.config.clone())
        {
            self.set_error(format!(
                "Macro \"{name}\" is active this session, but saving to config failed: {err}"
            ));
        } else {
            self.set_info(format!("Macro \"{name}\" saved."));
        }
    }

    fn handle_confirm_delete_macro_key(&mut self, key: KeyEvent) -> Result<bool> {
        let action = self.bindings.lookup(&key, BindingScope::Dialog);
        let is_space = key.code == KeyCode::Char(' ');
        let activate = matches!(action, Some(Action::Confirm)) || is_space;

        let confirm = {
            let PromptState::EditMacros { pending_delete, .. } = &mut self.prompt else {
                return Ok(false);
            };
            let Some(pending) = pending_delete else {
                return Ok(false);
            };

            if matches!(action, Some(Action::CloseOverlay)) {
                *pending_delete = None;
                return Ok(false);
            }
            if matches!(action, Some(Action::ToggleSelection)) {
                pending.focus = pending.focus.toggled();
                return Ok(false);
            }
            if !activate {
                return Ok(false);
            }
            pending.focus.is_confirm()
        };

        self.resolve_confirm_delete_macro(confirm);
        Ok(false)
    }

    pub(super) fn resolve_confirm_delete_macro(&mut self, confirm: bool) -> bool {
        let PromptState::EditMacros { pending_delete, .. } = &mut self.prompt else {
            return false;
        };
        let Some(pending) = pending_delete.take() else {
            return false;
        };

        if !confirm {
            return false;
        }

        let name = pending.name;
        self.engine.config.macros.entries.shift_remove(&name);

        let PromptState::EditMacros {
            entries, selected, ..
        } = &mut self.prompt
        else {
            return false;
        };
        entries.retain(|(n, _, _)| n != &name);
        if *selected > 0 && *selected >= entries.len() {
            *selected = entries.len().saturating_sub(1);
        }

        if let Err(err) = self
            .engine
            .config_writer
            .save_eager(self.engine.config.clone())
        {
            self.set_error(format!(
                "Macro \"{name}\" is active this session, but saving to config failed: {err}"
            ));
        } else {
            self.set_info(format!("Macro \"{name}\" deleted."));
        }
        false
    }

    fn handle_resize_key(&mut self, key: KeyEvent) {
        if let Some(action) = self.bindings.lookup(&key, BindingScope::Resize) {
            if self.focus == FocusPane::Files {
                match action {
                    Action::ResizeShrink => self.set_right_width_pct(self.right_width_pct + 2),
                    Action::ResizeGrow => {
                        self.set_right_width_pct(self.right_width_pct.saturating_sub(2))
                    }
                    _ => {}
                }
            } else {
                match action {
                    Action::ResizeShrink => {
                        self.set_left_width_pct(self.left_width_pct.saturating_sub(2))
                    }
                    Action::ResizeGrow => self.set_left_width_pct(self.left_width_pct + 2),
                    _ => {}
                }
            }
        }
    }

    fn set_left_width_pct(&mut self, left_width_pct: u16) {
        self.left_width_pct = clamp_left_width_pct(left_width_pct, self.right_width_pct);
        self.right_width_pct = clamp_right_width_pct(self.right_width_pct, self.left_width_pct);
    }

    fn set_right_width_pct(&mut self, right_width_pct: u16) {
        self.right_width_pct = clamp_right_width_pct(right_width_pct, self.left_width_pct);
        self.left_width_pct = clamp_left_width_pct(self.left_width_pct, self.right_width_pct);
    }

    fn overlay_row_at(
        rect: Rect,
        offset: usize,
        items: usize,
        column: u16,
        row: u16,
    ) -> Option<usize> {
        Self::overlay_row_at_sized(rect, offset, items, 1, column, row)
    }

    /// Map a screen row into a list whose offset counts multi-row items.
    fn overlay_row_at_sized(
        rect: Rect,
        offset: usize,
        items: usize,
        rows_per_item: u16,
        column: u16,
        row: u16,
    ) -> Option<usize> {
        if !contains_point(rect, column, row) {
            return None;
        }
        let relative_row = usize::from(row.saturating_sub(rect.y));
        let index = offset.saturating_add(relative_row / usize::from(rows_per_item.max(1)));
        (index < items).then_some(index)
    }

    #[allow(clippy::too_many_arguments)]
    fn searchable_overlay_target(
        input: Option<Rect>,
        list: Rect,
        items: usize,
        offset: usize,
        input_target: PromptMouseTarget,
        item_target: fn(usize) -> PromptMouseTarget,
        column: u16,
        row: u16,
    ) -> Option<PromptMouseTarget> {
        if input.is_some_and(|rect| contains_point(rect, column, row)) {
            Some(input_target)
        } else {
            Self::overlay_row_at(list, offset, items, column, row).map(item_target)
        }
    }

    fn checkbox_before_buttons_target(
        checkbox: Option<OverlayCheckbox>,
        buttons: &[(Rect, PromptMouseTarget)],
        column: u16,
        row: u16,
    ) -> Option<PromptMouseTarget> {
        if let Some(checkbox) = checkbox
            && contains_point(checkbox.rect, column, row)
        {
            return Some(PromptMouseTarget::Checkbox(checkbox.id));
        }
        click_target(buttons, column, row)
    }

    fn startup_command_logs_target(
        input: Option<Rect>,
        list: Rect,
        items: usize,
        offset: usize,
        close_button: Rect,
        column: u16,
        row: u16,
    ) -> Option<PromptMouseTarget> {
        if input.is_some_and(|rect| contains_point(rect, column, row)) {
            return Some(PromptMouseTarget::StartupCommandLogsInput);
        }
        if contains_point(close_button, column, row) {
            return Some(PromptMouseTarget::StartupCommandLogsClose);
        }
        Self::overlay_row_at_sized(list, offset, items, STARTUP_LOG_ROW_HEIGHT, column, row)
            .map(PromptMouseTarget::StartupCommandLogItem)
    }

    fn macro_editor_target(
        name_input: Rect,
        text_input: Rect,
        surface_options: [Rect; 3],
        cancel_button: Rect,
        save_button: Rect,
        column: u16,
        row: u16,
    ) -> Option<PromptMouseTarget> {
        click_target(
            &[
                (name_input, PromptMouseTarget::MacroNameInput),
                (text_input, PromptMouseTarget::MacroTextInput),
                (cancel_button, PromptMouseTarget::MacroCancel),
                (save_button, PromptMouseTarget::MacroSave),
            ],
            column,
            row,
        )
        .or_else(|| {
            surface_options
                .iter()
                .position(|rect| contains_point(*rect, column, row))
                .map(PromptMouseTarget::MacroSurfaceOption)
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn kill_running_target(
        input: Option<Rect>,
        list: Rect,
        items: usize,
        offset: usize,
        cancel_button: Rect,
        hovered_button: Rect,
        selected_button: Rect,
        visible_button: Rect,
        column: u16,
        row: u16,
    ) -> Option<PromptMouseTarget> {
        if let Some(target) = Self::searchable_overlay_target(
            input,
            list,
            items,
            offset,
            PromptMouseTarget::RuntimeKillInput,
            PromptMouseTarget::RuntimeKillItem,
            column,
            row,
        ) {
            return Some(target);
        }
        click_target(
            &[
                (cancel_button, PromptMouseTarget::RuntimeKillCancel),
                (hovered_button, PromptMouseTarget::RuntimeKillHovered),
                (selected_button, PromptMouseTarget::RuntimeKillSelected),
                (visible_button, PromptMouseTarget::RuntimeKillVisible),
            ],
            column,
            row,
        )
    }

    fn name_new_agent_target(
        input: Rect,
        checkbox: Option<OverlayCheckbox>,
        copy_checkbox: Option<OverlayCheckbox>,
        column: u16,
        row: u16,
    ) -> Option<PromptMouseTarget> {
        for checkbox in [checkbox, copy_checkbox].into_iter().flatten() {
            if contains_point(checkbox.rect, column, row) {
                return Some(PromptMouseTarget::Checkbox(checkbox.id));
            }
        }
        contains_point(input, column, row).then_some(PromptMouseTarget::NameNewAgentInput)
    }

    fn pull_request_input_target(
        input: Rect,
        choose_project: Option<Rect>,
        column: u16,
        row: u16,
    ) -> Option<PromptMouseTarget> {
        if choose_project.is_some_and(|button| contains_point(button, column, row)) {
            Some(PromptMouseTarget::PullRequestChooseProject)
        } else {
            contains_point(input, column, row).then_some(PromptMouseTarget::PullRequestInput)
        }
    }

