    fn fullscreen_mouse_target(&self, column: u16, row: u16) -> Option<MouseTarget> {
        self.mouse_layout
            .agent_term
            .filter(|rect| contains_point(*rect, column, row))
            .map(|_| MouseTarget::Center)
    }

    fn left_list_mouse_target(&self, column: u16, row: u16) -> Option<MouseTarget> {
        if !contains_point(self.mouse_layout.left_list, column, row) {
            return None;
        }
        if self.left_items().is_empty() {
            return Some(MouseTarget::LeftPane);
        }

        let relative_row = usize::from(row.saturating_sub(self.mouse_layout.left_list.y));
        let Some(&index) = self.mouse_layout.left_row_to_item.get(relative_row) else {
            return Some(MouseTarget::LeftPane);
        };
        if index >= self.left_items().len() || !self.is_selectable_left_item(index) {
            return Some(MouseTarget::LeftPane);
        }
        Some(MouseTarget::LeftRow(index))
    }

    fn terminal_list_mouse_target(&self, column: u16, row: u16) -> Option<MouseTarget> {
        let list = self.mouse_layout.terminal_list;
        if list.width == 0 || list.height == 0 || !contains_point(list, column, row) {
            return None;
        }

        let screen_row = usize::from(row.saturating_sub(list.y));
        let terminal_count = self.terminal_items().len();
        if let Some(&index) = self.mouse_layout.terminal_row_to_item.get(screen_row)
            && index < terminal_count
        {
            return Some(MouseTarget::TerminalRow(index));
        }
        Some(MouseTarget::TerminalPane)
    }

    fn files_mouse_target(&self, column: u16, row: u16) -> Option<MouseTarget> {
        if let Some(area) = self.mouse_layout.unstaged_list
            && contains_point(area, column, row)
        {
            let index = usize::from(row.saturating_sub(area.y));
            let file_index = (index < self.engine.unstaged_files.len()).then_some(index);
            return Some(MouseTarget::UnstagedFile(file_index));
        }
        if let Some(area) = self.mouse_layout.staged_list
            && contains_point(area, column, row)
        {
            let index = usize::from(row.saturating_sub(area.y));
            let file_index = (index < self.engine.staged_files.len()).then_some(index);
            return Some(MouseTarget::StagedFile(file_index));
        }
        if let Some(area) = self.mouse_layout.commit_area
            && contains_point(area, column, row)
        {
            let target = if self
                .mouse_layout
                .commit_text_area
                .is_some_and(|text_area| contains_point(text_area, column, row))
            {
                MouseTarget::CommitText
            } else {
                MouseTarget::CommitChrome
            };
            return Some(target);
        }
        contains_point(self.mouse_layout.right, column, row).then_some(MouseTarget::FilesPane)
    }

    fn mouse_target(&self, column: u16, row: u16) -> Option<MouseTarget> {
        if !matches!(self.fullscreen_overlay, FullscreenOverlay::None) {
            return self.fullscreen_mouse_target(column, row);
        }

        if let Some(target) = self.left_list_mouse_target(column, row) {
            return Some(target);
        }
        if let Some(target) = self.terminal_list_mouse_target(column, row) {
            return Some(target);
        }
        if contains_point(self.mouse_layout.left, column, row) {
            return Some(MouseTarget::LeftPane);
        }
        if let Some(target) = self.files_mouse_target(column, row) {
            return Some(target);
        }
        contains_point(self.mouse_layout.center, column, row).then_some(MouseTarget::Center)
    }

    fn resize_drag_at_mouse(&self, column: u16, row: u16) -> Option<ResizeDragState> {
        let body = self.mouse_layout.body;
        if !contains_point(body, column, row) {
            return None;
        }

        let left_edge = self.mouse_layout.left.x + self.mouse_layout.left.width.saturating_sub(1);
        let center_left = self.mouse_layout.center.x;
        let center_right =
            self.mouse_layout.center.x + self.mouse_layout.center.width.saturating_sub(1);
        let right_left = self.mouse_layout.right.x;

        if !self.left_collapsed && (column == left_edge || column == center_left) {
            return Some(ResizeDragState::LeftDivider);
        }

        if !self.right_hidden && (column == center_right || column == right_left) {
            return Some(ResizeDragState::RightDivider);
        }

        // Horizontal divider between Projects and Terminals sections.
        let tl = self.mouse_layout.terminal_list;
        if tl.width > 0 && tl.height > 0 {
            let left = self.mouse_layout.left;
            let divider_row = tl.y.saturating_sub(1);
            if row == divider_row && column >= left.x && column < left.x + left.width {
                return Some(ResizeDragState::TerminalDivider);
            }
        }

        // Horizontal dividers inside the right pane.
        //
        // The inner content rects (unstaged_list, staged_list) exclude the
        // surrounding block borders, so the gap between two adjacent rects is
        // typically only 1-2 rows of border chrome.  We extend the hit zone
        // outward from each content rect by 1 row to cover the border that
        // belongs to each block, making the target at least 3 rows wide
        // (bottom border + gap + top border) without overlapping the content.

        // Between Unstaged and Staged.
        if let (Some(unstaged), Some(staged)) = (
            self.mouse_layout.unstaged_list,
            self.mouse_layout.staged_list,
        ) {
            let right = self.mouse_layout.right;
            // The content rects don't include their enclosing block borders.
            // Extend one row past each content edge to cover the border row.
            let hit_top = unstaged.y + unstaged.height; // first row after unstaged content (border)
            let hit_bottom = staged.y.saturating_sub(1); // last row before staged content (border)
            if row >= hit_top
                && row <= hit_bottom
                && column >= right.x
                && column < right.x + right.width
            {
                return Some(ResizeDragState::StagedDivider);
            }
        }

        // Between Staged Changes and Commit Message.
        // staged_list is an inner rect; commit_area is an outer rect (includes border).
        if let (Some(staged), Some(commit)) =
            (self.mouse_layout.staged_list, self.mouse_layout.commit_area)
        {
            let right = self.mouse_layout.right;
            let hit_top = staged.y + staged.height; // first row after staged content (border)
            let hit_bottom = commit.y; // top border row of commit block
            if row >= hit_top
                && row <= hit_bottom
                && column >= right.x
                && column < right.x + right.width
            {
                return Some(ResizeDragState::CommitDivider);
            }
        }

        None
    }

    fn set_left_selection(&mut self, index: usize) {
        if !self.is_selectable_left_item(index) {
            return;
        }
        self.focus = FocusPane::Left;
        self.input_target = InputTarget::None;
        self.fullscreen_overlay = FullscreenOverlay::None;
        if self.selected_left != index {
            self.selected_left = index;
            self.project_chooser_context = None;
            self.close_diff_view();
            self.reload_changed_files();
        }
    }

    fn register_mouse_click(
        &mut self,
        target: MouseClickTarget,
        item_index: Option<usize>,
    ) -> bool {
        let now = Instant::now();
        if let Some(last) = self.last_mouse_click
            && last.target == target
            && last.item_index == item_index
            && now.duration_since(last.at) <= DOUBLE_CLICK_THRESHOLD
        {
            self.last_mouse_click = None;
            return true;
        }

        self.last_mouse_click = Some(RecentMouseClick {
            target,
            item_index,
            at: now,
        });
        false
    }

    /// The command the palette's cursor is actually ON, which is the row the
    /// renderer highlights.
    ///
    /// `selected` is stored state and the match list is recomputed on every
    /// read, so availability can shrink the list out from under it: a pull
    /// request that closes, a terminal that exits. The renderer clamps the
    /// highlight, so resolving the raw index here instead would run (or fail
    /// to find) a different command than the one the user can see selected.
    fn palette_command_at(
        &self,
        input: &str,
        selected: usize,
    ) -> Option<&crate::keybindings::RuntimeBinding> {
        let commands = self.filtered_palette_commands(input);
        let index = selected.min(commands.len().saturating_sub(1));
        commands.get(index).copied()
    }

    /// Pull a stale `selected` back onto the list as it stands now, so the
    /// stored cursor and the drawn highlight cannot disagree.
    fn clamp_command_palette_selection(&mut self) {
        let count = match &self.prompt {
            PromptState::Command { input, .. } => self.filtered_palette_commands(&input.text).len(),
            _ => return,
        };
        if let PromptState::Command { selected, .. } = &mut self.prompt {
            *selected = (*selected).min(count.saturating_sub(1));
        }
    }

    fn set_command_palette_selection(&mut self, index: usize) {
        let count = match &self.prompt {
            PromptState::Command { input, .. } => self.filtered_palette_commands(&input.text).len(),
            _ => 0,
        };
        if count == 0 {
            return;
        }
        if let PromptState::Command { selected, .. } = &mut self.prompt {
            *selected = index.min(count.saturating_sub(1));
        }
    }

    fn set_command_palette_cursor_from_mouse(&mut self, column: u16) {
        let input_area = match self.overlay_layout.active {
            OverlayMouseLayout::Command { input, .. } => input,
            _ => return,
        };
        if let PromptState::Command { input, .. } = &mut self.prompt {
            let prefix_width = 2; // "> "
            input.cursor =
                cursor_from_single_line_position(&input.text, input_area, prefix_width, column);
        }
    }

    fn execute_selected_command_palette(&mut self) {
        let command = if let PromptState::Command {
            input, selected, ..
        } = &self.prompt
        {
            if let Some(binding) = self.palette_command_at(&input.text, *selected) {
                binding.palette_name.unwrap().to_string()
            } else {
                input.text.trim().to_string()
            }
        } else {
            String::new()
        };
        self.prompt = PromptState::None;
        if let Err(e) = self.execute_command(command) {
            self.set_error(format!("{e:#}"));
        }
    }

    fn visible_browser_entries(&self) -> Vec<BrowserEntry> {
        if let PromptState::BrowseProjects {
            entries, filter, ..
        } = &self.prompt
        {
            if filter.is_empty() {
                entries.clone()
            } else {
                let needle = filter.text.to_lowercase();
                entries
                    .iter()
                    .filter(|entry| entry.label.to_lowercase().contains(&needle))
                    .cloned()
                    .collect()
            }
        } else {
            Vec::new()
        }
    }

    fn set_browser_selection(&mut self, index: usize) {
        let count = self.visible_browser_entries().len();
        if count == 0 {
            return;
        }
        if let PromptState::BrowseProjects { selected, .. } = &mut self.prompt {
            *selected = index.min(count.saturating_sub(1));
        }
    }

    fn set_browser_input_cursor_from_mouse(&mut self, column: u16) {
        let input_area = match self.overlay_layout.active {
            OverlayMouseLayout::BrowseProjects {
                input: Some(input), ..
            } => input,
            _ => return,
        };
        if let PromptState::BrowseProjects {
            filter,
            searching,
            editing_path,
            path_input,
            ..
        } = &mut self.prompt
        {
            if *editing_path {
                path_input.cursor =
                    cursor_from_single_line_position(&path_input.text, input_area, 4, column);
            } else {
                filter.cursor =
                    cursor_from_single_line_position(&filter.text, input_area, 2, column);
                *searching = true;
            }
        }
    }

    /// Land the caret in the project chooser's `/`-search field. The renderer
    /// pads it with the two-cell `"/ "` prefix.
    fn set_pick_project_filter_cursor_from_mouse(&mut self, column: u16) {
        let input_area = match self.overlay_layout.active {
            OverlayMouseLayout::PickProject {
                input: Some(input), ..
            } => input,
            _ => return,
        };
        if let PromptState::PickProject { list, .. } = &mut self.prompt {
            list.filter.cursor =
                cursor_from_single_line_position(&list.filter.text, input_area, 2, column);
            list.searching = true;
        }
    }

    /// Land the caret in the startup-log filter. Its field carries no prefix.
    fn set_startup_command_logs_filter_cursor_from_mouse(&mut self, column: u16) {
        let input_area = match self.overlay_layout.active {
            OverlayMouseLayout::StartupCommandLogs {
                input: Some(input), ..
            } => input,
            _ => return,
        };
        if let PromptState::StartupCommandLogs(prompt) = &mut self.prompt {
            prompt.filter.cursor =
                cursor_from_single_line_position(&prompt.filter.text, input_area, 0, column);
            prompt.searching = true;
            // Search is a mode over the list, not a stop of its own, so a
            // click into the filter leaves focus where the mode belongs. Same
            // as `set_kill_running_search_cursor_from_mouse`.
            prompt.focus = StartupCommandLogFocus::List;
        }
    }

    fn set_kill_running_hovered(&mut self, visible_index: usize) {
        if let PromptState::KillRunning(prompt) = &mut self.prompt {
            let count = Self::visible_kill_running_indices(prompt).len();
            if count == 0 {
                prompt.list.selected = 0;
                return;
            }
            prompt.list.selected = visible_index.min(count.saturating_sub(1));
            prompt.focus = KillRunningFocus::List;
        }
    }

    fn set_kill_running_search_cursor_from_mouse(&mut self, column: u16) {
        let input_area = match self.overlay_layout.active {
            OverlayMouseLayout::KillRunning {
                input: Some(input), ..
            } => input,
            _ => return,
        };
        if let PromptState::KillRunning(prompt) = &mut self.prompt {
            prompt.list.filter.cursor =
                cursor_from_single_line_position(&prompt.list.filter.text, input_area, 2, column);
            prompt.list.searching = true;
            prompt.focus = KillRunningFocus::List;
        }
    }

    fn toggle_hovered_kill_running_selection(&mut self) {
        let target_id = match &self.prompt {
            PromptState::KillRunning(prompt) => {
                let visible = Self::visible_kill_running_indices(prompt);
                visible
                    .get(prompt.list.selected)
                    .and_then(|&index| prompt.runtimes.get(index))
                    .map(|runtime| runtime.id.clone())
            }
            _ => None,
        };

        let Some(target_id) = target_id else {
            self.set_error(
                "No running agent or terminal is highlighted. Move to a visible row first.",
            );
            return;
        };

        if let PromptState::KillRunning(prompt) = &mut self.prompt
            && !prompt.selected_ids.insert(target_id.clone())
        {
            prompt.selected_ids.remove(&target_id);
        }
    }

    fn execute_kill_running_footer_action(
        &mut self,
        action: KillRunningFooterAction,
    ) -> Result<()> {
        let enabled = match &self.prompt {
            PromptState::KillRunning(prompt) => Self::kill_running_footer_enabled(prompt, action),
            _ => true,
        };
        if !enabled {
            if matches!(action, KillRunningFooterAction::Selected) {
                self.set_info(
                    "Select one or more runtimes before using Kill Selected. Press Space to mark the highlighted row.",
                );
            }
            return Ok(());
        }
        match action {
            KillRunningFooterAction::Cancel => {
                self.prompt = PromptState::None;
                self.set_info("Closed Kill Running. No agents or terminals were killed.");
            }
            _ => {
                if let Some(action) = action.action() {
                    self.open_confirm_kill_running_action(action)?;
                }
            }
        }
        Ok(())
    }

    pub(crate) fn kill_running_footer_enabled(
        prompt: &KillRunningPrompt,
        action: KillRunningFooterAction,
    ) -> bool {
        match action {
            KillRunningFooterAction::Cancel => true,
            KillRunningFooterAction::Selected => !prompt.selected_ids.is_empty(),
            KillRunningFooterAction::Hovered | KillRunningFooterAction::Visible => {
                !Self::visible_kill_running_indices(prompt).is_empty()
            }
        }
    }

    fn next_kill_running_footer_action(
        prompt: &KillRunningPrompt,
        current: Option<KillRunningFooterAction>,
        forward: bool,
    ) -> KillRunningFocus {
        const ACTIONS: [KillRunningFooterAction; 4] = [
            KillRunningFooterAction::Cancel,
            KillRunningFooterAction::Hovered,
            KillRunningFooterAction::Selected,
            KillRunningFooterAction::Visible,
        ];

        let enabled: Vec<KillRunningFooterAction> = ACTIONS
            .into_iter()
            .filter(|action| Self::kill_running_footer_enabled(prompt, *action))
            .collect();

        if enabled.is_empty() {
            return KillRunningFocus::List;
        }

        match current {
            None => {
                if forward {
                    KillRunningFocus::Footer(enabled[0])
                } else {
                    KillRunningFocus::Footer(*enabled.last().unwrap())
                }
            }
            Some(current) => {
                let Some(index) = enabled.iter().position(|action| *action == current) else {
                    return if forward {
                        KillRunningFocus::Footer(enabled[0])
                    } else {
                        KillRunningFocus::Footer(*enabled.last().unwrap())
                    };
                };
                if forward {
                    if index + 1 < enabled.len() {
                        KillRunningFocus::Footer(enabled[index + 1])
                    } else {
                        KillRunningFocus::List
                    }
                } else if index > 0 {
                    KillRunningFocus::Footer(enabled[index - 1])
                } else {
                    KillRunningFocus::List
                }
            }
        }
    }

    fn open_selected_browser_entry(&mut self) {
        let visible = self.visible_browser_entries();
        let mut browse_to: Option<PathBuf> = None;
        if let PromptState::BrowseProjects {
            current_dir,
            entries,
            loading,
            selected,
            filter,
            ..
        } = &mut self.prompt
            && let Some(entry) = visible.get(*selected)
        {
            let new_dir = entry.path.clone();
            *current_dir = new_dir.clone();
            entries.clear();
            *loading = true;
            *selected = 0;
            filter.clear();
            browse_to = Some(new_dir);
        }
        if let Some(dir) = browse_to {
            self.engine.spawn_browser_entries(&dir);
        }
    }

    fn path_editor_completion_candidates(input: &str) -> Vec<String> {
        let input_path = PathBuf::from(input);
        let (search_dir, prefix) = if input_path.is_dir() && input.ends_with('/') {
            (input_path, String::new())
        } else {
            let parent = input_path
                .parent()
                .unwrap_or_else(|| std::path::Path::new("/"));
            let file_name = input_path
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_default();
            (parent.to_path_buf(), file_name)
        };

        let Ok(read) = std::fs::read_dir(search_dir.clone()) else {
            return Vec::new();
        };
        let prefix_lower = prefix.to_lowercase();
        let mut candidates: Vec<String> = read
            .filter_map(|entry| entry.ok())
            .filter(|entry| entry.file_type().map(|ft| ft.is_dir()).unwrap_or(false))
            .filter(|entry| {
                let name = entry.file_name().to_string_lossy().to_lowercase();
                !name.starts_with('.') && name.starts_with(&prefix_lower)
            })
            .map(|entry| {
                let mut full = search_dir
                    .join(entry.file_name())
                    .to_string_lossy()
                    .to_string();
                full.push('/');
                full
            })
            .collect();
        candidates.sort();
        candidates
    }

    fn refresh_path_editor_completions(&mut self) {
        let input = match &self.prompt {
            PromptState::BrowseProjects {
                editing_path: true,
                path_input,
                ..
            } => path_input.text.clone(),
            _ => return,
        };
        let candidates = Self::path_editor_completion_candidates(&input);
        if let PromptState::BrowseProjects {
            tab_completions,
            tab_index,
            ..
        } = &mut self.prompt
        {
            *tab_completions = candidates;
            *tab_index = 0;
        }
    }

    fn add_project_from_browser_path(&mut self, path: String) {
        let return_prompt = self.prompt.clone();
        if let Err(message) = self.engine.validate_project_add_path(&path) {
            // Not addable as-is. A plain folder gets the adopt-a-folder prompt
            // (git init + seed + initial commit); anything else (a subfolder,
            // a .git dir, an already-registered path) keeps the failure modal
            // with the ORIGINAL add error, which now names the enclosing root.
            if let Ok(canonical) = self.engine.validate_project_init_path(&path) {
                let candidates = dux_core::gitignore_seed::matched_candidates(&canonical)
                    .iter()
                    .map(|c| c.dir.to_string())
                    .collect();
                self.prompt = PromptState::ConfirmInitRepo {
                    path: canonical.to_string_lossy().to_string(),
                    name: String::new(),
                    candidates,
                    focus: ConfirmFocus::Cancel,
                    return_prompt: Box::new(return_prompt),
                };
                return;
            }
            self.open_add_project_failed_modal(message, return_prompt);
            return;
        }
        self.prompt = PromptState::None;
        if let Err(error) = self.add_project(path, String::new()) {
            self.open_add_project_failed_modal(format!("{error:#}"), return_prompt);
        }
    }

    fn open_add_project_failed_modal(&mut self, message: String, return_prompt: PromptState) {
        self.prompt = PromptState::AddProjectFailed {
            message,
            return_prompt: Box::new(return_prompt),
            scroll: 0,
        };
    }

    /// Apply `key` to the open error dialog's message scroll, reporting whether
    /// it was a scroll key (and so must not fall through to the dialog's buttons).
    ///
    /// The two error dialogs (`ConfigReloadFailed`, `AddProjectFailed`) share
    /// this: both carry a message that can outgrow the screen, and both are how a
    /// user learns something is broken, so every line has to be reachable. The
    /// vocabulary is the Help scope's, the same one the first-load screens reuse,
    /// so it stays rebindable and consistent.
    pub(crate) fn scroll_error_dialog_for(&mut self, key: &KeyEvent) -> bool {
        let Some(action) = self.bindings.lookup(key, BindingScope::Help) else {
            return false;
        };
        let page = i32::from(self.last_error_dialog_height.max(1));
        match action {
            Action::MoveDown => self.scroll_error_dialog(1),
            Action::MoveUp => self.scroll_error_dialog(-1),
            Action::ScrollPageDown => self.scroll_error_dialog(page),
            Action::ScrollPageUp => self.scroll_error_dialog(-page),
            Action::ScrollToBottom => self.scroll_error_dialog(i32::from(u16::MAX)),
            Action::ScrollToTop => self.scroll_error_dialog(-i32::from(u16::MAX)),
            _ => return false,
        }
        true
    }

    /// Scroll the open error dialog's message by `delta` rows, clamped to the
    /// extent the renderer last recorded.
    pub(crate) fn scroll_error_dialog(&mut self, delta: i32) {
        let max = self
            .last_error_dialog_lines
            .saturating_sub(self.last_error_dialog_height.max(1));
        let scroll = match &mut self.prompt {
            PromptState::ConfigReloadFailed { scroll, .. }
            | PromptState::AddProjectFailed { scroll, .. } => scroll,
            _ => return,
        };
        let next = if delta >= 0 {
            scroll.saturating_add(delta as u16)
        } else {
            scroll.saturating_sub(delta.unsigned_abs() as u16)
        };
        *scroll = next.min(max);
    }

    pub(super) fn resolve_add_project_failed(&mut self) -> bool {
        let return_prompt = match std::mem::replace(&mut self.prompt, PromptState::None) {
            PromptState::AddProjectFailed { return_prompt, .. } => *return_prompt,
            other => {
                self.prompt = other;
                return false;
            }
        };
        self.prompt = return_prompt;
        false
    }

    fn set_pick_editor_selection(&mut self, index: usize) {
        let count = match &self.prompt {
            PromptState::PickEditor { editors, .. } => editors.len(),
            _ => 0,
        };
        if count == 0 {
            return;
        }
        if let PromptState::PickEditor { selected, .. } = &mut self.prompt {
            *selected = index.min(count.saturating_sub(1));
        }
    }

    fn open_selected_pick_editor(&mut self) {
        let (editor, worktree, label) = if let PromptState::PickEditor {
            session_label,
            worktree_path,
            editors,
            selected,
        } = &self.prompt
        {
            (
                editors.get(*selected).cloned(),
                worktree_path.clone(),
                session_label.clone(),
            )
        } else {
            return;
        };
        self.prompt = PromptState::None;
        if let Some(editor) = editor
            && let Err(e) = self.open_worktree_in_editor(&worktree, &label, &editor)
        {
            self.set_error(format!("{e:#}"));
        }
    }

    /// Land the manager's cursor on a clicked row, ignoring headers, empty
    /// rows, and rows an agent holds (the cursor never rests on one).
    ///
    /// Returns whether the click actually landed on a selectable row, because
    /// the double-click path needs to know: a second click on a row this
    /// refuses must do nothing at all, not confirm whatever was selected
    /// before it.
    fn set_manage_worktree_selection_from_visual_row(&mut self, visual_index: usize) -> bool {
        let entry_index = match &self.prompt {
            PromptState::ManageWorktrees(prompt) => {
                let rows = manage_worktree_visual_rows(
                    &prompt.entries,
                    prompt.loading,
                    prompt.error.as_deref(),
                );
                rows.get(visual_index).and_then(|row| match row {
                    ManageWorktreeVisualRow::Entry(index)
                        if prompt
                            .entries
                            .get(*index)
                            .is_some_and(|entry| entry.is_removable()) =>
                    {
                        Some(*index)
                    }
                    _ => None,
                })
            }
            _ => None,
        };
        let Some(entry_index) = entry_index else {
            return false;
        };
        if let PromptState::ManageWorktrees(prompt) = &mut self.prompt {
            prompt.selected = Some(entry_index);
        }
        true
    }

    fn set_project_worktree_selection_from_visual_row(&mut self, visual_index: usize) {
        let entry_index = match &self.prompt {
            PromptState::PickProjectWorktree(prompt) => {
                let rows = project_worktree_visual_rows(
                    &prompt.entries,
                    prompt.loading,
                    prompt.error.as_deref(),
                );
                rows.get(visual_index).and_then(|row| match row {
                    ProjectWorktreeVisualRow::Entry(index)
                        if prompt
                            .entries
                            .get(*index)
                            .is_some_and(|entry| entry.is_selectable) =>
                    {
                        Some(*index)
                    }
                    _ => None,
                })
            }
            _ => None,
        };
        let Some(entry_index) = entry_index else {
            return;
        };
        if let PromptState::PickProjectWorktree(prompt) = &mut self.prompt {
            prompt.selected = Some(entry_index);
        }
    }

    fn open_selected_project_worktree_agent_prompt(&mut self) -> Result<()> {
        let (project, entry) = match &self.prompt {
            PromptState::PickProjectWorktree(prompt) => {
                let Some(selected) = prompt.selected else {
                    self.set_error("No available worktree is selected.");
                    return Ok(());
                };
                let Some(entry) = prompt.entries.get(selected).cloned() else {
                    self.set_error("No available worktree is selected.");
                    return Ok(());
                };
                if !entry.is_selectable {
                    self.set_error("That worktree already has an agent.");
                    return Ok(());
                }
                (prompt.project.clone(), entry)
            }
            _ => return Ok(()),
        };

        let request = if entry.is_external {
            CreateAgentRequest::ForkExternalWorktree {
                project,
                source_worktree_path: entry.path.clone(),
                source_label: entry.display_name(),
                source_branch: entry.branch_name.clone(),
                custom_name: Some(entry.display_name()),
            }
        } else {
            let managed_root = self.engine.paths.worktrees_root.join(&project.name);
            let default_name = entry
                .path
                .strip_prefix(&managed_root)
                .ok()
                .map(|relative| relative.to_string_lossy().to_string())
                .filter(|name| !name.is_empty())
                .unwrap_or_else(|| entry.display_name());
            CreateAgentRequest::ExistingManagedWorktree {
                project,
                worktree_path: entry.path.clone(),
                branch_name: entry.branch_name.clone(),
                custom_name: Some(default_name),
            }
        };
        self.open_name_new_agent_prompt_for_request(request)
    }

