    #[test]
    fn should_forward_wheel_matrix() {
        use super::should_forward_wheel;
        // None = auto: mouse reporting alone decides. An app that asks for
        // the mouse owns the wheel whether or not it took the alt screen.
        assert!(should_forward_wheel(None, true, true));
        assert!(!should_forward_wheel(None, true, false));
        assert!(should_forward_wheel(None, false, true));
        assert!(!should_forward_wheel(None, false, false));
        // Some(true) = always forward, regardless of live signals.
        assert!(should_forward_wheel(Some(true), false, false));
        assert!(should_forward_wheel(Some(true), true, true));
        assert!(should_forward_wheel(Some(true), false, true));
        // Some(false) = never forward, even in the alt screen with mouse.
        assert!(!should_forward_wheel(Some(false), true, true));
        assert!(!should_forward_wheel(Some(false), false, false));
    }

    #[test]
    fn should_forward_page_matrix() {
        use super::should_forward_page;
        // None = auto: page keys forward in the alt screen (no mouse needed).
        assert!(should_forward_page(None, true));
        assert!(!should_forward_page(None, false));
        // Some(true) = always forward.
        assert!(should_forward_page(Some(true), false));
        assert!(should_forward_page(Some(true), true));
        // Some(false) = never forward, even in the alt screen.
        assert!(!should_forward_page(Some(false), true));
        assert!(!should_forward_page(Some(false), false));
    }

    fn bindings_with_overrides(overrides: &[(Action, &[&str])]) -> RuntimeBindings {
        RuntimeBindings::new(
            |action| {
                if let Some((_, keys)) =
                    overrides.iter().find(|(candidate, _)| *candidate == action)
                {
                    return keys
                        .iter()
                        .map(|key| crokey::parse(key).expect("valid test binding"))
                        .collect();
                }
                BINDING_DEFS
                    .iter()
                    .find(|d| d.action == action)
                    .map(|d| d.default_keys.to_vec())
                    .unwrap_or_default()
            },
            true,
        )
    }

    fn set_remote_default(path: &std::path::Path, branch: &str) {
        run_git(
            path,
            &[
                "update-ref",
                &format!("refs/remotes/origin/{branch}"),
                "HEAD",
            ],
        );
        run_git(
            path,
            &[
                "symbolic-ref",
                "refs/remotes/origin/HEAD",
                &format!("refs/remotes/origin/{branch}"),
            ],
        );
    }

    fn complete_create_agent_branch_inspection(app: &mut App, branch: &str, leading_branch: &str) {
        let project = app.engine.projects[0].clone();
        app.engine
            .worker_tx
            .send(WorkerEvent::CreateAgentBranchInspected {
                project,
                result: Ok(CreateAgentBranchInspection {
                    current_branch: branch.to_string(),
                    leading_branch: leading_branch.to_string(),
                }),
                status_op_id: None,
            })
            .unwrap();
        app.drain_events();
    }

    fn mouse(kind: MouseEventKind, column: u16, row: u16) -> MouseEvent {
        MouseEvent {
            kind,
            column,
            row,
            modifiers: KeyModifiers::NONE,
        }
    }

    fn install_mouse_layout(app: &mut App) {
        app.mouse_layout = MouseLayoutState {
            body: Rect::new(0, 0, 100, 20),
            left: Rect::new(0, 0, 20, 20),
            center: Rect::new(20, 0, 57, 20),
            right: Rect::new(77, 0, 23, 20),
            left_list: Rect::new(1, 1, 18, 10),
            // Synthetic identity map (one row per item) so these plumbing tests
            // keep their 1:1 row->item expectations; the real two-line mapping is
            // covered by `left_row_to_item`'s own unit tests and a render test.
            left_row_to_item: (0..10usize).collect(),
            terminal_list: Rect::default(),
            terminal_row_to_item: Vec::new(),
            agent_term: Some(Rect::new(21, 1, 55, 16)),
            takeover_button: None,
            pr_banner: None,
            unstaged_list: Some(Rect::new(78, 1, 21, 8)),
            staged_list: Some(Rect::new(78, 9, 21, 5)),
            commit_area: Some(Rect::new(77, 14, 23, 6)),
            commit_text_area: Some(Rect::new(78, 15, 21, 4)),
        };
    }

    /// Three active agents and one detached one, so the agent list is three
    /// reorderable rows followed by the Inactive toggle. With the synthetic
    /// identity mouse map installed, row `y = left_list.y + i` is item `i`.
    fn drag_test_app() -> App {
        let mut app = test_app(default_bindings());
        let now = Utc::now();
        app.engine.sessions.clear();
        for id in ["s1", "s2", "s3"] {
            app.engine
                .sessions
                .push(filter_test_session(id, id, "p1", now));
        }
        let mut quiet = filter_test_session("s4", "s4", "p1", now);
        quiet.status = crate::model::SessionStatus::Detached;
        app.engine.sessions.push(quiet);
        app.rebuild_left_items();
        install_mouse_layout(&mut app);
        app
    }

    /// The screen row carrying agent-list item `index` under the identity map.
    fn left_row_y(app: &App, index: usize) -> u16 {
        app.mouse_layout.left_list.y + index as u16
    }

    #[test]
    fn a_press_that_releases_where_it_landed_stays_a_plain_click() {
        let mut app = drag_test_app();
        let x = app.mouse_layout.left_list.x;
        let y = left_row_y(&app, 1);

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), x, y));
        assert!(app.row_drag.is_some(), "the press arms a gesture");
        assert_eq!(app.selected_left, 1, "the press still selects the row");
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), x, y));

        assert!(app.row_drag.is_none(), "the release retires the gesture");
        let order: Vec<&str> = app.engine.sessions.iter().map(|s| s.id.as_str()).collect();
        assert_eq!(
            order,
            vec!["s1", "s2", "s3", "s4"],
            "a click reorders nothing"
        );
    }

