    fn drain_until(app: &mut App, mut done: impl FnMut(&App) -> bool) {
        for _ in 0..50 {
            app.drain_events();
            if done(app) {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        app.drain_events();
    }

    #[test]
    fn reload_config_command_applies_valid_config_immediately_after_worker_completes() {
        let mut app = test_app(default_bindings());
        let mut config = Config::default();
        config.ui.right_width_pct = 37;
        config.ui.show_diff_line_numbers = true;
        let bindings = RuntimeBindings::from_keys_config(&config.keys);
        std::fs::write(
            &app.engine.paths.config_path,
            crate::config::render_config_with(&config, &bindings),
        )
        .expect("write valid config");

        app.execute_command("reload-config".to_string())
            .expect("start reload config");
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Busy);
        assert_eq!(app.status.message(), "Reloading config.toml.");

        drain_until(&mut app, |app| app.engine.config.ui.right_width_pct == 37);

        assert_eq!(app.right_width_pct, 37);
        assert!(app.show_diff_line_numbers);
        assert!(matches!(app.prompt, PromptState::None));
        assert_eq!(
            app.status.message(),
            "Configuration reloaded. New settings are active now."
        );
    }

    #[test]
    fn reload_config_command_keeps_current_config_and_opens_modal_on_validation_error() {
        let mut app = test_app(default_bindings());
        app.engine.config.ui.right_width_pct = 41;
        std::fs::write(
            &app.engine.paths.config_path,
            r#"
[keys]
show_terminal_keys = true
not_a_real_action = ["x"]
"#,
        )
        .expect("write invalid config");

        app.execute_command("reload-config".to_string())
            .expect("start reload config");
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Busy);

        drain_until(&mut app, |app| {
            matches!(app.prompt, PromptState::ConfigReloadFailed { .. })
        });

        assert_eq!(app.engine.config.ui.right_width_pct, 41);
        assert_eq!(
            app.status.message(),
            "Config reload failed. Review the modal before retrying."
        );
        match &app.prompt {
            PromptState::ConfigReloadFailed {
                error,
                recover_old_config,
                focus,
                scroll,
            } => {
                assert!(error.contains("unknown action"));
                assert_eq!(*scroll, 0, "a freshly opened dialog starts at the top");
                assert!(!recover_old_config);
                assert_eq!(*focus, ConfigReloadFailedFocus::Close);
            }
            other => panic!("expected config reload failure prompt, got {other:?}"),
        }
    }

    #[test]
    fn reload_config_failure_can_recover_last_working_config_file() {
        let mut app = test_app(default_bindings());
        app.engine.config.ui.right_width_pct = 42;
        std::fs::write(&app.engine.paths.config_path, "this is not valid toml")
            .expect("write broken config");
        app.prompt = PromptState::ConfigReloadFailed {
            error: "broken".to_string(),
            recover_old_config: true,
            focus: ConfigReloadFailedFocus::Apply,
            scroll: 0,
        };

        app.resolve_config_reload_failed(true);
        // RecoverConfig is synchronous: it writes through the engine while
        // holding the quiesce barrier and returns the FINAL status directly.
        // There is no trailing Busy (which would never clear) and nothing to drain.
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Info);
        assert_eq!(
            app.status.message(),
            "Restored the last working configuration to config.toml."
        );

        assert!(matches!(app.prompt, PromptState::None));
        let recovered =
            std::fs::read_to_string(&app.engine.paths.config_path).expect("read recovered");
        let parsed: Config = toml::from_str(&recovered).expect("parse recovered config");
        assert_eq!(parsed.ui.right_width_pct, 42);
    }

    /// A long, multi-line error must be reachable with the keyboard, and the
    /// scroll keys must not fire the dialog's buttons on the way. Both error
    /// dialogs share the handler, so both are checked.
    #[test]
    fn the_error_dialogs_scroll_their_message_without_dismissing_themselves() {
        let long = (0..40)
            .map(|i| format!("error detail line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        for which in 0..2 {
            let mut app = test_app(default_bindings());
            app.prompt = if which == 0 {
                PromptState::ConfigReloadFailed {
                    error: long.clone(),
                    recover_old_config: false,
                    focus: ConfigReloadFailedFocus::Close,
                    scroll: 0,
                }
            } else {
                PromptState::AddProjectFailed {
                    message: long.clone(),
                    return_prompt: Box::new(PromptState::None),
                    scroll: 0,
                }
            };
            // What the renderer would have recorded for a 40-line message in a
            // 12-row pane.
            app.last_error_dialog_lines = 44;
            app.last_error_dialog_height = 12;

            let scroll_of = |app: &App| match &app.prompt {
                PromptState::ConfigReloadFailed { scroll, .. }
                | PromptState::AddProjectFailed { scroll, .. } => *scroll,
                other => panic!("the dialog dismissed itself: {other:?}"),
            };

            app.handle_key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE))
                .expect("scroll down one line");
            assert_eq!(scroll_of(&app), 1);
            app.handle_key(KeyEvent::new(KeyCode::PageDown, KeyModifiers::NONE))
                .expect("scroll down a page");
            assert_eq!(scroll_of(&app), 13);
            app.handle_key(KeyEvent::new(KeyCode::End, KeyModifiers::NONE))
                .expect("scroll to the bottom");
            assert_eq!(
                scroll_of(&app),
                32,
                "End must reach the last row of the message, not overshoot it"
            );
            app.handle_key(KeyEvent::new(KeyCode::Home, KeyModifiers::NONE))
                .expect("scroll back to the top");
            assert_eq!(scroll_of(&app), 0);

            // The checkbox (config reload) and the buttons still work: a scroll
            // key must not have consumed Space or Enter.
            if which == 0 {
                app.handle_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
                    .expect("move focus");
                assert!(matches!(app.prompt, PromptState::ConfigReloadFailed { .. }));
            }
            app.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
                .expect("dismiss");
            assert!(
                matches!(app.prompt, PromptState::None),
                "Esc must still dismiss the dialog"
            );
        }
    }

