    /// The `refresh-changes` palette command has to be listed by the palette and
    /// has to leave the status line on a FINAL state. A `Busy` that nothing
    /// replaces would sit there as a spinner forever.
    #[test]
    fn refresh_changes_command_is_listed_and_resolves_its_busy() {
        let mut app = test_app(default_bindings());
        assert!(
            app.filtered_palette_commands("refresh-changes")
                .iter()
                .any(|b| b.action == dux_core::action::Action::RefreshChanges),
            "the palette must offer refresh-changes"
        );

        app.execute_command("refresh-changes".to_string())
            .expect("refresh changes");
        // The read runs on a worker, so the final lands on a later drain.
        drain_until(&mut app, |app| {
            app.status.tone() != crate::statusline::StatusTone::Busy
        });

        assert_ne!(
            app.status.tone(),
            crate::statusline::StatusTone::Busy,
            "the busy must be replaced by a final, got: {}",
            app.status.message()
        );
        assert!(
            app.status
                .snapshot()
                .iter()
                .all(|s| s.tone != crate::statusline::StatusTone::Busy.as_wire()),
            "no keyed busy may be left open"
        );
        assert!(
            app.status.message().contains("Changed files"),
            "the final must say what happened, got: {}",
            app.status.message()
        );
    }

    /// The `refresh-changes` palette command has to actually ASK GIT AGAIN. The
    /// test seeds a bogus changed file that only a real recompute can dislodge,
    /// and pins the counts the final status reports, so deleting the refresh
    /// leaves the ghost in place and the message wrong.
    #[test]
    fn refresh_changes_command_recomputes_the_lists_and_reports_the_counts() {
        let mut app = test_app(default_bindings());
        init_git_repo_with_modified_file(&app, "tracked.txt", "before\n", "after\n");
        let ghost = dux_core::model::ChangedFile {
            status: " M".to_string(),
            path: "ghost.txt".to_string(),
            additions: 0,
            deletions: 0,
            binary: false,
        };
        app.engine.staged_files = vec![ghost.clone()];
        app.engine.unstaged_files = vec![ghost];

        app.execute_command("refresh-changes".to_string())
            .expect("refresh changes");
        drain_until(&mut app, |app| {
            app.status.tone() != crate::statusline::StatusTone::Busy
        });

        assert!(
            app.engine.staged_files.is_empty(),
            "the seeded staged ghost must be gone, got: {:?}",
            app.engine.staged_files
        );
        assert_eq!(
            app.engine
                .unstaged_files
                .iter()
                .map(|f| f.path.as_str())
                .collect::<Vec<_>>(),
            vec!["tracked.txt"],
            "the recompute must report what git actually says"
        );
        assert!(
            app.status.message().contains("0 staged, 1 unstaged"),
            "the final must report the counts it just computed, got: {}",
            app.status.message()
        );
    }

    /// The git read must happen on a worker, never on the interface thread: a
    /// repository another process has locked would otherwise freeze the whole
    /// TUI, and this command exists precisely for "I just did something in a
    /// shell", which is when a lock is most likely. The observable contract is
    /// that the call RETURNS with its busy still open and the lists untouched;
    /// only a later drain carries the answer.
    #[test]
    fn refresh_changes_command_reads_git_on_a_worker_not_on_the_ui_thread() {
        let mut app = test_app(default_bindings());
        init_git_repo_with_modified_file(&app, "tracked.txt", "before\n", "after\n");

        app.execute_command("refresh-changes".to_string())
            .expect("refresh changes");

        assert_eq!(
            app.status.tone(),
            crate::statusline::StatusTone::Busy,
            "the command must return while the read is still in flight, got: {}",
            app.status.message()
        );
        assert!(
            app.engine.unstaged_files.is_empty(),
            "nothing may be computed inline, got: {:?}",
            app.engine.unstaged_files
        );

        drain_until(&mut app, |app| {
            app.status.tone() != crate::statusline::StatusTone::Busy
        });
        assert_eq!(
            app.engine
                .unstaged_files
                .iter()
                .map(|f| f.path.as_str())
                .collect::<Vec<_>>(),
            vec!["tracked.txt"],
            "the worker's answer must land on the drain"
        );
    }

    /// A refresh whose watch moved while git was reading has nothing to report:
    /// the engine drops that answer as stale, so the lists never took it, and
    /// counting them would report the previous agent's numbers under this
    /// agent's name. The busy still has to go.
    #[test]
    fn refresh_changes_that_lost_its_watch_retires_the_busy_without_reporting() {
        let mut app = test_app(default_bindings());
        init_git_repo_with_modified_file(&app, "tracked.txt", "before\n", "after\n");

        app.execute_command("refresh-changes".to_string())
            .expect("refresh changes");
        // The user moves on before the answer lands.
        *app.engine.watched_worktree.lock().expect("watch lock") =
            Some(std::path::PathBuf::from("/tmp/dux-some-other-worktree"));
        drain_until(&mut app, |app| app.pending_changed_files_refresh.is_none());

        assert!(
            !app.status.message().contains("refreshed"),
            "a dropped answer must not be reported, got: {}",
            app.status.message()
        );
        assert!(
            app.status
                .snapshot()
                .iter()
                .all(|s| s.tone != crate::statusline::StatusTone::Busy.as_wire()),
            "no keyed busy may be left open"
        );
    }

    /// A git that could not answer is not an empty answer. Swallowing the error
    /// reports "0 staged, 0 unstaged", which tells the user their worktree is
    /// clean when dux has no idea what is in it.
    #[test]
    fn refresh_changes_command_reports_a_git_failure_as_a_failure() {
        let mut app = test_app(default_bindings());
        let missing = app
            .engine
            .paths
            .root
            .join("no-such-worktree")
            .to_string_lossy()
            .into_owned();
        app.engine.sessions[0]
            .workspace
            .as_managed_mut()
            .expect("managed test session")
            .worktree_path = missing;

        app.execute_command("refresh-changes".to_string())
            .expect("refresh changes");
        drain_until(&mut app, |app| {
            app.status.tone() != crate::statusline::StatusTone::Busy
        });

        assert_eq!(
            app.status.tone(),
            crate::statusline::StatusTone::Error,
            "a git failure must read as a failure, got: {}",
            app.status.message()
        );
        assert!(
            !app.status.message().contains("0 staged, 0 unstaged"),
            "a failure must never be reported as a clean worktree, got: {}",
            app.status.message()
        );
        assert!(
            app.status
                .snapshot()
                .iter()
                .all(|s| s.tone != crate::statusline::StatusTone::Busy.as_wire()),
            "no keyed busy may be left open"
        );
    }

