    #[test]
    fn inactive_rule_shows_only_when_the_toggle_is_unselected() {
        use crate::model::SessionStatus;
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;

        fn toggle_row_has_rule(app: &mut App) -> bool {
            let backend = TestBackend::new(120, 30);
            let mut terminal = Terminal::new(backend).expect("terminal");
            terminal
                .draw(|frame| app.render(frame))
                .expect("render frame");
            let toggle_idx = app
                .left_items()
                .iter()
                .position(|i| matches!(i, LeftItem::InactiveToggle))
                .expect("toggle");
            let rel = app
                .mouse_layout
                .left_row_to_item
                .iter()
                .rposition(|&i| i == toggle_idx)
                .expect("toggle row");
            // The toggle ends with a trailing spacer; its label is one row up.
            let y = app.mouse_layout.left_list.y + rel.saturating_sub(1) as u16;
            let lx = app.mouse_layout.left_list.x;
            let lw = app.mouse_layout.left_list.width;
            let buf = terminal.backend().buffer();
            (lx..lx + lw).any(|x| buf[(x, y)].symbol() == "─")
        }

        let mut app = test_app(default_bindings());
        // One active agent + one Exited agent, so the list has an Inactive toggle.
        let mut inactive = app.engine.sessions[0].clone();
        inactive.id = "inactive-1".to_string();
        app.engine.sessions.push(inactive);
        let active_id = app.engine.sessions[0].id.clone();
        app.engine
            .mark_session_status(&active_id, SessionStatus::Active);
        app.engine
            .mark_session_status("inactive-1", SessionStatus::Exited);
        app.focus = FocusPane::Left;
        app.left_section = LeftSection::Projects;
        app.rebuild_left_items();
        let toggle_idx = app
            .left_items()
            .iter()
            .position(|i| matches!(i, LeftItem::InactiveToggle))
            .expect("toggle");

        // The rule keeps the right padding: its last column stops a gutter short
        // of the pane edge, so the rightmost cell of the label row stays blank.
        fn toggle_rule_right_pad_is_blank(app: &mut App) -> bool {
            let backend = TestBackend::new(120, 30);
            let mut terminal = Terminal::new(backend).expect("terminal");
            terminal
                .draw(|frame| app.render(frame))
                .expect("render frame");
            let toggle_idx = app
                .left_items()
                .iter()
                .position(|i| matches!(i, LeftItem::InactiveToggle))
                .expect("toggle");
            let rel = app
                .mouse_layout
                .left_row_to_item
                .iter()
                .rposition(|&i| i == toggle_idx)
                .expect("toggle row");
            let y = app.mouse_layout.left_list.y + rel.saturating_sub(1) as u16;
            let lx = app.mouse_layout.left_list.x;
            let lw = app.mouse_layout.left_list.width;
            let buf = terminal.backend().buffer();
            buf[(lx + lw - 1, y)].symbol() == " "
        }

        // Selection on the active agent (not the toggle): the rule shows.
        app.selected_left = app
            .left_items()
            .iter()
            .position(|i| matches!(i, LeftItem::Session(_)))
            .expect("agent row");
        assert!(
            toggle_row_has_rule(&mut app),
            "the rule shows while the toggle is unselected",
        );
        assert!(
            toggle_rule_right_pad_is_blank(&mut app),
            "the rule stops a gutter short of the right edge",
        );

        // Selecting the toggle hides the rule (it takes the full-width highlight).
        app.selected_left = toggle_idx;
        assert!(
            !toggle_row_has_rule(&mut app),
            "no rule while the toggle is selected",
        );
    }

    #[test]
    fn first_inactive_agent_gets_tinted_frame() {
        use crate::model::SessionStatus;
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;

        let mut app = test_app(default_bindings());
        let mut inactive = app.engine.sessions[0].clone();
        inactive.id = "inactive-1".to_string();
        app.engine.sessions.push(inactive);
        let active_id = app.engine.sessions[0].id.clone();
        app.engine
            .mark_session_status(&active_id, SessionStatus::Active);
        app.engine
            .mark_session_status("inactive-1", SessionStatus::Exited);
        app.focus = FocusPane::Left;
        app.left_section = LeftSection::Projects;
        // Expand the Inactive section by hand so the inactive agent renders.
        app.inactive_collapsed = false;
        app.inactive_collapse_overridden = true;
        app.rebuild_left_items();
        // Select the inactive agent (the Session that sorts after the toggle).
        let sel = app
            .left_items()
            .iter()
            .enumerate()
            .filter(|(_, i)| matches!(i, LeftItem::Session(_)))
            .map(|(idx, _)| idx)
            .next_back()
            .expect("inactive agent row");
        app.selected_left = sel;

        let backend = TestBackend::new(120, 30);
        let mut terminal = Terminal::new(backend).expect("terminal");
        terminal
            .draw(|frame| app.render(frame))
            .expect("render frame");

        let rel_start = app
            .mouse_layout
            .left_row_to_item
            .iter()
            .position(|&i| i == sel)
            .expect("inactive agent visible");
        assert!(rel_start > 0, "inactive agent is not the first row");
        // The selected inactive agent gets the tinted selection band on its name
        // row like any other agent, with no accent bar.
        let y = app.mouse_layout.left_list.y + rel_start as u16;
        let buf = terminal.backend().buffer();
        let gx = app.mouse_layout.left_list.x;
        assert_ne!(
            buf[(gx, y)].symbol(),
            "▌",
            "no accent bar on the inactive agent"
        );
        assert_eq!(
            buf[(gx, y)].bg,
            app.theme.selection_bar_tint(),
            "the first inactive agent's name row is tinted",
        );
    }

