    /// A double click never steals clicks from a mouse-aware child: with
    /// mouse tracking on, both clicks are forwarded to the child and the
    /// pane stays minimized.
    #[test]
    fn mouse_double_click_does_not_maximize_a_mouse_mode_child() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        app.selected_left = 1;
        app.center_mode = CenterMode::Agent;
        app.focus = FocusPane::Center;
        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &[
                    "-c".to_string(),
                    "printf '\\033[?1000h'; sleep 5".to_string(),
                ],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );
        // Wait for the child's mouse-tracking DECSET to be parsed.
        let mut mouse_mode = false;
        for _ in 0..200 {
            if app
                .selected_terminal_surface_client()
                .is_some_and(|p| p.has_mouse_mode())
            {
                mouse_mode = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            mouse_mode,
            "test setup: the child must have mouse tracking on"
        );

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert_eq!(
            app.focus,
            FocusPane::Center,
            "the clicks still focus the pane"
        );
        assert_eq!(
            app.fullscreen_overlay,
            FullscreenOverlay::None,
            "a mouse-aware child owns its clicks, so a double click must not maximize"
        );
        assert_eq!(app.input_target, InputTarget::None);
    }

    // -- Windowed click forwarding to a mouse-aware child --

    /// Wire a `cat -v` child that first enables the given DECSET modes as the
    /// selected session's provider, install the synthetic layout, and wait
    /// until the embedded terminal has parsed the mode sets. `cat -v` echoes
    /// every byte the child receives in caret notation, so the child's own
    /// grid is the proof of what was forwarded.
    fn install_mouse_forward_child(app: &mut App, decsets: &str) {
        let session_id = app.engine.sessions[0].id.clone();
        let cmd = format!("stty raw -echo; printf '{decsets}'; exec cat -v");
        let client = PtyClient::spawn(
            "/bin/sh",
            &["-c".to_string(), cmd],
            std::path::Path::new("."),
            24,
            80,
            100,
        )
        .expect("spawn pty");
        app.engine.providers.insert(session_id, client);
        app.selected_left = 1;
        app.session_surface = SessionSurface::Agent;
        app.center_mode = CenterMode::Agent;
        install_mouse_layout(app);
        if decsets.is_empty() {
            // No modes to wait for; give the shell a moment to exec cat.
            std::thread::sleep(std::time::Duration::from_millis(250));
            return;
        }
        for _ in 0..400 {
            if app
                .selected_terminal_surface_client()
                .is_some_and(|p| p.has_mouse_mode())
            {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        panic!("the child never enabled mouse tracking");
    }

    fn forwarded_echo(app: &App) -> String {
        app.selected_terminal_surface_client()
            .expect("provider")
            .snapshot()
            .cells
            .iter()
            .map(|cell| cell.symbol.as_str())
            .collect()
    }

    /// Poll until the child has echoed `needle`, returning the rendered grid.
    fn wait_for_forwarded_echo(app: &App, needle: &str) -> String {
        let mut rendered = String::new();
        for _ in 0..400 {
            rendered = forwarded_echo(app);
            if rendered.contains(needle) {
                return rendered;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        panic!("the child never echoed {needle:?}; grid was: {rendered:?}");
    }

    /// A plain left click inside the windowed pane of a `?1000h` child is
    /// focused AND forwarded as a translated SGR press, stamped as a pointer
    /// report — and a rapid second click is just a second forwarded click,
    /// never a maximize.
    #[test]
    fn windowed_click_on_a_mouse_mode_child_forwards_the_translated_press() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        app.focus = FocusPane::Left;

        // agent_term is (21,1,55,16); a click at screen (30,5) translates to
        // child cell (10,5) in 1-based SGR coordinates.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert_eq!(app.focus, FocusPane::Center, "the click still focuses");
        assert_eq!(
            app.center_mouse_forward,
            Some(0),
            "the press must arm the forwarding drag state"
        );
        let session_id = app.engine.sessions[0].id.clone();
        assert!(
            app.engine.pty_pointer.contains_key(&session_id),
            "a forwarded press must stamp the pointer window, not typing"
        );
        wait_for_forwarded_echo(&app, "[<0;10;5M");

        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        assert_eq!(app.center_mouse_forward, None);
        wait_for_forwarded_echo(&app, "[<0;10;5m");

        // The rapid second click: forwarded again, no maximize.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        let rendered = wait_for_forwarded_echo(&app, "[<0;10;5m^[[<0;10;5M");
        assert_eq!(
            app.fullscreen_overlay,
            FullscreenOverlay::None,
            "a double click on a mouse-mode child is two forwarded clicks, not a maximize; got {rendered:?}"
        );
        assert_eq!(app.input_target, InputTarget::None);
    }

    /// With button-drag tracking (`?1002h`) on, dragging a held button sends
    /// motion reports (button + 32), clamped to the pane edge mid-drag.
    #[test]
    fn windowed_drag_sends_motion_reports_to_a_drag_tracking_child() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1002h");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Drag(MouseButton::Left), 35, 6));
        wait_for_forwarded_echo(&app, "[<32;15;6M");

        // A drag that leaves the pane is clamped to the edge, like xterm.
        app.handle_mouse(mouse(MouseEventKind::Drag(MouseButton::Left), 0, 0));
        wait_for_forwarded_echo(&app, "[<32;1;1M");

        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 35, 6));
        wait_for_forwarded_echo(&app, "[<0;15;6m");
    }

    /// A click-only (`?1000h`) child gets presses and releases but NO motion
    /// reports: a real emulator would never send it any.
    #[test]
    fn windowed_drag_sends_no_motion_to_a_click_only_child() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Drag(MouseButton::Left), 35, 6));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 35, 6));

        let rendered = wait_for_forwarded_echo(&app, "[<0;15;6m");
        assert!(
            !rendered.contains("[<32;"),
            "a 1000-only child must receive no motion reports; got {rendered:?}"
        );
    }

    /// The RELEASE must always be delivered, even when the pointer left the
    /// pane: its coordinates clamp to the pane edge. (Deleting the clamp
    /// makes the translation reject the out-of-pane coordinates and drop the
    /// release, leaving the child with a stuck button — this test fails.)
    #[test]
    fn windowed_release_outside_the_pane_is_clamped_and_delivered() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        wait_for_forwarded_echo(&app, "[<0;10;5M");

        // (0,0) is far outside agent_term (21,1,55,16): clamped to the pane's
        // top-left content cell, which is (1,1) in child coordinates.
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 0, 0));

        assert_eq!(
            app.center_mouse_forward, None,
            "the release must disarm the forwarding state"
        );
        wait_for_forwarded_echo(&app, "[<0;1;1m");
    }

    /// A modified click (Shift/Alt/Ctrl held) is NOT forwarded: it stays
    /// dux's host-selection story, exactly as in a real emulator.
    #[test]
    fn windowed_modified_click_is_not_forwarded() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        app.focus = FocusPane::Left;

        app.handle_mouse(MouseEvent {
            kind: MouseEventKind::Down(MouseButton::Left),
            column: 30,
            row: 5,
            modifiers: KeyModifiers::SHIFT,
        });

        assert_eq!(app.focus, FocusPane::Center, "the click still focuses");
        assert_eq!(app.center_mouse_forward, None);
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "a modified click must not reach the child; got {rendered:?}"
        );
    }

    /// A child without mouse tracking keeps today's behavior: the click only
    /// focuses the pane and nothing reaches the PTY.
    #[test]
    fn windowed_click_on_a_child_without_mouse_mode_only_focuses() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "");
        app.focus = FocusPane::Left;

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert_eq!(app.focus, FocusPane::Center);
        assert_eq!(app.center_mouse_forward, None);
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "no mouse mode means no forwarded reports; got {rendered:?}"
        );
    }

    /// While scrolled back the scroll vocabulary owns the pane, so a click is
    /// not forwarded (it would land on cells the child is not showing).
    #[test]
    fn windowed_click_is_not_forwarded_while_scrolled_back() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let session_id = app.engine.sessions[0].id.clone();
        app.scroll_mode.insert(session_id);

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert_eq!(app.center_mouse_forward, None);
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "a scrolled-back pane must not forward clicks; got {rendered:?}"
        );
    }

    // -- A click on a linked cell opens the link --

    /// Swap in an opener that records the addresses it is asked for instead of
    /// launching a browser, and hand back the receiving end.
    fn recording_opener(app: &mut App) -> std::sync::mpsc::Receiver<String> {
        let (tx, rx) = std::sync::mpsc::channel();
        let tx = std::sync::Mutex::new(tx);
        app.url_opener = std::sync::Arc::new(move |url: &str| {
            let _ = tx
                .lock()
                .expect("the recording opener's channel")
                .send(url.to_string());
            Ok(())
        });
        rx
    }

    /// Paint cells of the rendered snapshot with an OSC 8 address on them, as
    /// the emulator would after the child emitted a link, and stamp the buffer
    /// as belonging to the surface on screen (which is what the hit test
    /// requires before it will read a cell at all).
    fn install_linked_cells(app: &mut App, uri: &str, cells: &[(u16, u16, &str)]) {
        app.snapshot_buf.rows = 16;
        app.snapshot_buf.cols = 55;
        app.snapshot_buf.links = vec![uri.to_string()];
        app.snapshot_buf.cells = cells
            .iter()
            .map(|(row, col, symbol)| crate::pty::SnapshotCell {
                row: *row,
                col: *col,
                symbol: (*symbol).into(),
                fg: crate::pty::CellColor::Reset,
                bg: crate::pty::CellColor::Reset,
                modifier: crate::pty::CellModifier::default(),
                link: Some(0),
            })
            .collect();
        app.last_snapshot_id = app.selected_terminal_surface_id();
    }

    /// The common case: one linked cell at grid (4, 9), which the synthetic
    /// layout puts under screen point (30, 5).
    fn install_linked_cell(app: &mut App, row: u16, col: u16, symbol: &str, uri: &str) {
        install_linked_cells(app, uri, &[(row, col, symbol)]);
    }

    /// Wait for the opener to be asked for one address, or say what happened.
    fn opened_url(rx: &std::sync::mpsc::Receiver<String>) -> String {
        rx.recv_timeout(std::time::Duration::from_secs(10))
            .expect("the opener must be asked for the address the gesture landed on")
    }

    fn nothing_opened(rx: &std::sync::mpsc::Receiver<String>) {
        match rx.recv_timeout(std::time::Duration::from_millis(300)) {
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {}
            other => panic!("nothing should have been opened, got {other:?}"),
        }
    }

    /// A plain click on a linked cell is dux's: the address opens on the
    /// machine running dux, and NEITHER the press nor its release reaches the
    /// child, even though the child has mouse reporting on and would otherwise
    /// have been handed both. The open happens on the RELEASE, matching the
    /// web: a press alone is not yet a click.
    #[test]
    fn windowed_click_on_a_linked_cell_opens_it_and_the_child_sees_nothing() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        // agent_term is (21,1,55,16), so screen (30,5) is grid cell (9,4).
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        assert!(
            app.pending_link_click.is_some(),
            "the press decides; the record is what carries that decision"
        );
        nothing_opened(&rx);
        assert_eq!(
            app.center_mouse_forward, None,
            "a withheld press arms no forwarding drag"
        );

        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        assert_eq!(opened_url(&rx), "https://example.com/pr/1");

        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "neither half of a withheld link click may reach the child; got {rendered:?}"
        );
        assert!(
            app.pending_link_click.is_none(),
            "the release spends the record"
        );
    }

    /// A press on a link and a release somewhere else is a drag, not a click,
    /// and opens nothing. Both halves are still withheld from the child: the
    /// press already decided that.
    #[test]
    fn a_press_on_a_link_released_elsewhere_opens_nothing() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Drag(MouseButton::Left), 40, 8));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 40, 8));

        nothing_opened(&rx);
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "the whole withheld gesture stays away from the child; got {rendered:?}"
        );
    }

    /// A gesture that travelled but stayed on the same link is still a click:
    /// a long URL wraps across cells, and a few cells of drift along it must
    /// not cost the user the open.
    #[test]
    fn a_gesture_that_stays_on_the_same_link_still_opens_it() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cells(
            &mut app,
            "https://example.com/a/very/long/address",
            &[(4, 9, "P"), (4, 10, "R"), (4, 11, "1")],
        );

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 32, 5));

        assert_eq!(opened_url(&rx), "https://example.com/a/very/long/address");
    }

    /// With no child tracking the mouse there is nothing to withhold, so the
    /// press keeps its ordinary meaning and a drag that starts on a link
    /// becomes dux's own text selection. That is how a user still selects a URL
    /// to copy, and the gesture opens nothing.
    #[test]
    fn a_drag_from_a_link_selects_and_opens_nothing_without_mouse_tracking() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "");
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.process_raw_input_bytes(b"\x1b[<0;31;6M")
            .expect("the press is handled");
        assert!(
            app.pending_link_click
                .as_ref()
                .is_some_and(|pending| !pending.suppress),
            "with tracking off the press is noted but never withheld"
        );
        assert!(
            app.terminal_selection.is_some(),
            "the press must still start dux's own selection"
        );

        app.process_raw_input_bytes(b"\x1b[<32;41;9M")
            .expect("the drag is handled");
        let dragged = app
            .terminal_selection
            .clone()
            .expect("the drag must extend dux's own selection");
        assert_ne!(
            dragged.anchor, dragged.end,
            "a drag that reached the selection covers more than the cell it started on"
        );

        app.process_raw_input_bytes(b"\x1b[<0;41;9m")
            .expect("the release is handled");

        nothing_opened(&rx);
    }

    /// The cell beside the link is an ordinary cell, and an ordinary click on a
    /// mouse-tracking child is still the child's.
    #[test]
    fn windowed_click_on_an_unlinked_cell_is_forwarded_as_before() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        // One column to the right of the linked cell.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 31, 5));

        assert_eq!(app.center_mouse_forward, Some(0));
        wait_for_forwarded_echo(&app, "[<0;11;5M");
        nothing_opened(&rx);
    }

    /// THE HATCH. Ctrl+click on a linked cell gives the click to a
    /// mouse-tracking app and opens nothing, and the child sees a PLAIN press:
    /// the modifier is how the user reached the app, not something the app
    /// asked about.
    #[test]
    fn windowed_ctrl_click_on_a_linked_cell_forwards_a_plain_press_and_opens_nothing() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.handle_mouse(MouseEvent {
            kind: MouseEventKind::Down(MouseButton::Left),
            column: 30,
            row: 5,
            modifiers: KeyModifiers::CONTROL,
        });

        let rendered = wait_for_forwarded_echo(&app, "[<0;10;5M");
        assert!(
            !rendered.contains("[<16;"),
            "the hatch must not leak its own modifier bit to the child; got {rendered:?}"
        );
        nothing_opened(&rx);
        assert!(app.pending_link_click.is_none());
    }

    /// With no app tracking the mouse the hatch chord has nothing to hand the
    /// click to, so it keeps its plain meaning and opens, exactly as the web's
    /// `linkActivateAction` refuses the open only while tracking is on.
    #[test]
    fn ctrl_click_still_opens_when_no_child_is_tracking_the_mouse() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        let ctrl = |kind| MouseEvent {
            kind,
            column: 30,
            row: 5,
            modifiers: KeyModifiers::CONTROL,
        };
        app.handle_mouse(ctrl(MouseEventKind::Down(MouseButton::Left)));
        app.handle_mouse(ctrl(MouseEventKind::Up(MouseButton::Left)));

        assert_eq!(opened_url(&rx), "https://example.com/pr/1");
    }

    /// The hatch on a scrolled-back pane forwards nothing (the scroll
    /// vocabulary owns the pane), and it must not fall back to focusing the
    /// pane either: two of them in a row would then read as a double click and
    /// maximize the surface, which the fullscreen path never did.
    #[test]
    fn a_hatch_click_while_scrolled_back_does_nothing_at_all() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");
        let session_id = app.engine.sessions[0].id.clone();
        app.scroll_mode.insert(session_id);
        app.focus = FocusPane::Left;

        let ctrl = MouseEvent {
            kind: MouseEventKind::Down(MouseButton::Left),
            column: 30,
            row: 5,
            modifiers: KeyModifiers::CONTROL,
        };
        app.handle_mouse(ctrl);
        app.handle_mouse(ctrl);

        assert_eq!(app.center_mouse_forward, None);
        assert_eq!(
            app.focus,
            FocusPane::Left,
            "a refused hatch press does not fall back to focusing the pane"
        );
        assert!(
            app.last_mouse_click.is_none(),
            "and it records no click, so a second one cannot pair with it"
        );
        assert_eq!(
            app.fullscreen_overlay,
            FullscreenOverlay::None,
            "a refused hatch press is not half of a double click"
        );
        nothing_opened(&rx);
        std::thread::sleep(std::time::Duration::from_millis(200));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "and nothing reaches the child either; got {rendered:?}"
        );
    }

    /// Shift is the selection modifier here and the host terminal's own link
    /// modifier while dux holds the mouse, so dux neither opens nor forwards.
    #[test]
    fn windowed_shift_click_on_a_linked_cell_opens_nothing_and_forwards_nothing() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        let shift = |kind| MouseEvent {
            kind,
            column: 30,
            row: 5,
            modifiers: KeyModifiers::SHIFT,
        };
        app.handle_mouse(shift(MouseEventKind::Down(MouseButton::Left)));
        app.handle_mouse(shift(MouseEventKind::Up(MouseButton::Left)));

        nothing_opened(&rx);
        assert_eq!(app.center_mouse_forward, None);
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "a Shift press stays dux's selection story; got {rendered:?}"
        );
    }

    /// The emulator drops the spacer cell after a wide glyph, so a press on the
    /// SECOND column of a two-column linked glyph has no cell of its own to
    /// find. The hit test is span-aware and resolves it to the glyph that
    /// starts one column to its left.
    #[test]
    fn a_press_on_the_second_column_of_a_wide_linked_glyph_still_opens_it() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "漢", "https://example.com/wide");

        // Screen column 31 is grid column 10: the spacer half of the glyph.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 31, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 31, 5));

        assert_eq!(opened_url(&rx), "https://example.com/wide");
    }

    /// Scrolled back, the snapshot IS the scrolled view and its cells are
    /// viewport-relative, so the link the user can see is the link that opens
    /// and no scrollback offset is ever added to the lookup.
    #[test]
    fn a_link_in_scrollback_opens_from_the_row_the_user_can_see() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        let session_id = app.engine.sessions[0].id.clone();
        app.scroll_mode.insert(session_id);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/history");
        // A snapshot taken well above the live edge resolves the same point to
        // the same cell: adding the offset anywhere in the lookup moves it.
        app.snapshot_buf.scrollback_offset = 120;
        app.snapshot_buf.scrollback_total = 400;

        assert_eq!(
            app.link_at_screen_point(30, 5),
            Some("https://example.com/history"),
            "the row the user is looking at is the row that answers"
        );

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));

        assert_eq!(opened_url(&rx), "https://example.com/history");
    }

    /// A spent click is not half of a double click: the next press must not
    /// pair with it and maximize the pane.
    #[test]
    fn a_withheld_link_click_cannot_become_half_of_a_double_click() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        assert_eq!(opened_url(&rx), "https://example.com/pr/1");

        // Two ordinary presses on an unlinked cell: those two are the only pair
        // on screen, and the first of them is a FIRST click.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 31, 5));
        assert_eq!(
            app.fullscreen_overlay,
            FullscreenOverlay::None,
            "the press after a spent link click is a first click, not a second"
        );
    }

    /// Double-clicking a URL is how a terminal selects a word, not a request
    /// for two browser tabs. The second click of the pair opens nothing.
    #[test]
    fn a_double_click_on_a_link_opens_it_once() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        for _ in 0..2 {
            app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
            app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        }

        assert_eq!(opened_url(&rx), "https://example.com/pr/1");
        nothing_opened(&rx);
    }

    /// The same guard, cleared by the other retirements: a trip to another
    /// window and back is not a double click, so the same link clicked again on
    /// the user's return opens again.
    #[test]
    fn a_focus_trip_makes_the_same_cell_a_first_click_again() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        assert_eq!(opened_url(&rx), "https://example.com/pr/1");

        app.handle_terminal_event(ratatui::crossterm::event::Event::FocusLost);
        assert!(app.last_link_open.is_none());
        app.handle_terminal_event(ratatui::crossterm::event::Event::FocusGained);

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));

        assert_eq!(
            opened_url(&rx),
            "https://example.com/pr/1",
            "clicking the link again after leaving the window is a first click"
        );
    }

    /// The repeat-open guard is a screen cell, so it only means "the same link
    /// twice" while the same picture is on screen. Switching surface retires it
    /// with everything else stamped against that picture: the same coordinates
    /// on the next agent are a different link, and a first click on it opens.
    #[test]
    fn the_same_cell_on_another_surface_is_a_first_click_again() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/first");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        assert_eq!(opened_url(&rx), "https://example.com/first");
        assert!(
            app.last_link_open.is_some(),
            "test setup: the guard is armed on that cell"
        );

        // Another surface, with a link of its own under the very same point,
        // clicked well inside the double-click window.
        let terminal_id = "terminal-1".to_string();
        app.engine.companion_terminals.insert(
            terminal_id.clone(),
            dux_core::model::CompanionTerminal {
                owner: dux_core::model::TerminalOwner::Standalone,
                label: "shell".to_string(),
                foreground_cmd: None,
                client: PtyClient::spawn(
                    "sh",
                    &["-c".to_string(), "sleep 5".to_string()],
                    std::path::Path::new("."),
                    16,
                    55,
                    100,
                )
                .expect("spawn pty"),
                sort_order: 0,
                created_at: chrono::Utc::now(),
            },
        );
        app.session_surface = SessionSurface::Terminal;
        app.active_terminal_id = Some(terminal_id);
        app.refresh_snapshot_buf();
        assert!(
            app.last_link_open.is_none(),
            "the guard belongs to the picture that just left the screen"
        );
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/second");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));

        assert_eq!(
            opened_url(&rx),
            "https://example.com/second",
            "a first click on another agent's link must not be refused as a repeat"
        );
    }

    /// Opening a link is not a selection gesture: a highlight the user already
    /// completed is left exactly as it was.
    #[test]
    fn opening_a_link_leaves_a_completed_selection_alone() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");
        app.terminal_selection = Some(TerminalSelection {
            anchor: TermGridPos { row: 0, col: 0 },
            end: TermGridPos { row: 0, col: 4 },
            dragging: false,
            origin: app.snapshot_selection_origin(),
        });

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        assert_eq!(opened_url(&rx), "https://example.com/pr/1");

        assert!(
            app.terminal_selection.is_some(),
            "opening a link must not clear what the user had selected"
        );
    }

    /// The buffer the hit test reads is a REUSED one: it holds whatever was
    /// last painted into it. A pane with no live child of its own is showing
    /// nothing of its own, so a click on it must find no link rather than the
    /// previous agent's.
    #[test]
    fn a_pane_with_no_live_child_of_its_own_finds_no_link() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");
        assert!(
            app.link_at_screen_point(30, 5).is_some(),
            "test setup: the agent on screen does carry the link"
        );

        // A dormant surface: selected, with nothing running behind it, while
        // the buffer still holds the previous agent's cells.
        app.session_surface = SessionSurface::Terminal;
        app.active_terminal_id = Some("terminal-dormant".to_string());

        assert_eq!(
            app.link_at_screen_point(30, 5),
            None,
            "the cells belong to a pane that is not the one being clicked"
        );
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        nothing_opened(&rx);
    }

    // -- The pending-press lifecycle --

    /// A release that never arrives (the pointer left the window, the host ate
    /// it) must not strand the next click: a NEW press retires the record and
    /// is handled normally.
    #[test]
    fn a_missed_release_is_retired_by_the_next_press() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        assert!(app.pending_link_click.is_some());

        // No Up at all; the user presses again, on an ordinary cell.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 31, 5));

        assert!(
            app.pending_link_click.is_none(),
            "the stale record must be retired by the new press"
        );
        assert_eq!(
            app.center_mouse_forward,
            Some(0),
            "and the new press must be handled normally"
        );
        wait_for_forwarded_echo(&app, "[<0;11;5M");
        nothing_opened(&rx);
    }

    /// The host lost focus between press and release, so the release is
    /// somebody else's window's. Driven through the real crossterm event the
    /// run loop hands over, not through the retirement helper.
    #[test]
    fn a_host_focus_loss_retires_a_pending_press() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        assert!(app.pending_link_click.is_some());

        app.handle_terminal_event(ratatui::crossterm::event::Event::FocusLost);

        assert!(app.pending_link_click.is_none());
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        nothing_opened(&rx);
    }

    /// The same through the raw focus-out report, which is the only focus
    /// notice the interactive path ever sees.
    #[test]
    fn a_raw_focus_out_report_retires_a_pending_press() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        app.process_raw_input_bytes(b"\x1b[<0;31;6M")
            .expect("the press is handled");
        assert!(app.pending_link_click.is_some());

        app.process_raw_input_bytes(b"\x1b[O")
            .expect("the focus report is handled");

        assert!(app.pending_link_click.is_none());
        app.process_raw_input_bytes(b"\x1b[<0;31;6m")
            .expect("the release is handled");
        nothing_opened(&rx);
    }

    /// The host window resized under the press: the grid reflowed and the cell
    /// the press was aimed at moved with it.
    #[test]
    fn a_host_resize_retires_a_pending_press() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");

        // One completed click first, so the repeat-open guard is armed and the
        // resize has both records to clear.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        assert_eq!(opened_url(&rx), "https://example.com/pr/1");
        assert!(
            app.last_link_open.is_some(),
            "test setup: the guard is armed"
        );

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        assert!(app.pending_link_click.is_some());

        app.handle_terminal_event(ratatui::crossterm::event::Event::Resize(120, 40));

        assert!(app.pending_link_click.is_none());
        assert!(
            app.last_link_open.is_none(),
            "the repeat-open guard names a cell, which the reflow moved too"
        );
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        nothing_opened(&rx);
    }

    /// Switching surface retires the record where the SELECTION is retired,
    /// eagerly: coming back to the original surface must not resurrect a press
    /// that belongs to a view the user has since left and returned to.
    #[test]
    fn switching_surface_away_and_back_retires_a_pending_press() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");
        let session_id = app.engine.sessions[0].id.clone();

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        assert!(app.pending_link_click.is_some());

        // Away to a companion terminal with a child of its own, and back.
        let terminal_id = "terminal-1".to_string();
        app.engine.companion_terminals.insert(
            terminal_id.clone(),
            dux_core::model::CompanionTerminal {
                owner: dux_core::model::TerminalOwner::Session(session_id.clone()),
                label: "shell".to_string(),
                foreground_cmd: None,
                client: PtyClient::spawn(
                    "sh",
                    &["-c".to_string(), "sleep 5".to_string()],
                    std::path::Path::new("."),
                    16,
                    55,
                    100,
                )
                .expect("spawn pty"),
                sort_order: 0,
                created_at: chrono::Utc::now(),
            },
        );
        app.session_surface = SessionSurface::Terminal;
        app.active_terminal_id = Some(terminal_id);
        app.refresh_snapshot_buf();
        app.session_surface = SessionSurface::Agent;
        app.refresh_snapshot_buf();

        assert_eq!(
            app.selected_terminal_surface_id().as_deref(),
            Some(session_id.as_str()),
            "test setup: the original surface is back on screen"
        );
        assert!(
            app.pending_link_click.is_none(),
            "the record went with the surface it was stamped against"
        );
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        nothing_opened(&rx);
    }

    // -- The opener seam --

    /// A launcher that cannot start says so, keyed, naming the address so the
    /// user can copy it by hand.
    #[test]
    fn a_failed_open_reports_the_address_and_what_to_do() {
        let mut app = test_app(default_bindings());
        app.url_opener =
            std::sync::Arc::new(|_url: &str| Err(anyhow::anyhow!("no such file or directory")));

        app.open_url_in_browser("https://example.com/pr/1", "Opened it.");
        assert!(
            app.status.message().contains("Opening"),
            "the busy must show while the launcher runs; got {:?}",
            app.status.message()
        );

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while std::time::Instant::now() < deadline {
            app.drain_events();
            if app.status.message().contains("Could not open") {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let message = app.status.message().to_string();
        assert!(
            message.contains("https://example.com/pr/1")
                && message.contains("no such file or directory")
                && message.contains("open it by hand"),
            "the failure must name the address, the error and the way out; got {message:?}"
        );
    }

    // -- The PR banner is a click target --

    /// Give the selected agent a known pull request and put the banner's band
    /// where the render pass would: the bottom lane of the center pane, one row
    /// tall, spanning its width.
    fn install_pr_banner(app: &mut App) -> String {
        use crate::model::{PrInfo, PrState};

        let session_id = app.engine.sessions[0].id.clone();
        let url = "https://github.com/owner/repo/pull/42".to_string();
        app.engine.pr_statuses.insert(
            session_id,
            PrInfo {
                number: 42,
                state: PrState::Open,
                title: "Teach the banner to open its pull request".to_string(),
                host: "github.com".to_string(),
                owner_repo: "owner/repo".to_string(),
                url: url.clone(),
            },
        );
        app.mouse_layout.pr_banner = Some(Rect::new(20, 19, 57, 1));
        url
    }

    /// Pump the engine until the status line says `needle`, or say what it said
    /// instead. The open is a keyed busy answered by a worker, so the final
    /// arrives on a later drain.
    fn wait_for_status(app: &mut App, needle: &str) -> String {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while std::time::Instant::now() < deadline {
            app.drain_events();
            if app.status.message().contains(needle) {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let message = app.status.message().to_string();
        assert!(
            message.contains(needle),
            "expected a status containing {needle:?}, got {message:?}"
        );
        message
    }

    /// Press and release on the band, the gesture that opens it.
    fn click_band(app: &mut App, column: u16, row: u16) {
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), column, row));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), column, row));
    }

    /// A left click anywhere on the coloured band opens the pull request, the
    /// way the web banner is one link across the whole strip. The gesture is
    /// dux's own chrome: no focus moves, and a mouse-tracking child sees
    /// nothing of it.
    #[test]
    fn a_left_click_on_the_pr_banner_opens_the_pull_request() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        let rx = recording_opener(&mut app);
        let url = install_pr_banner(&mut app);
        app.focus = FocusPane::Left;

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 19));
        nothing_opened(&rx);
        assert!(
            app.pending_pr_banner_press.is_some(),
            "the press arms the gesture; the release is what opens"
        );
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 19));

        assert_eq!(opened_url(&rx), url);
        assert_eq!(app.focus, FocusPane::Left, "the press moves no focus");
        assert_eq!(
            app.center_mouse_forward, None,
            "the band is not the child's grid"
        );
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "nothing about the banner reaches the child; got {rendered:?}"
        );
        let message = wait_for_status(&mut app, "Opened PR");
        assert!(
            message.contains("owner/repo#42"),
            "the outcome names the pull request; got {message:?}"
        );
    }

    /// A launcher that cannot start is reported on the same keyed status the
    /// palette command uses, naming the address so it can be copied by hand.
    #[test]
    fn a_banner_press_reports_a_launcher_that_will_not_start() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        let url = install_pr_banner(&mut app);
        app.url_opener = Arc::new(|_url: &str| Err(anyhow::anyhow!("no such file or directory")));

        click_band(&mut app, 30, 19);

        let message = wait_for_status(&mut app, "Could not open");
        assert!(
            message.contains(&url) && message.contains("no such file or directory"),
            "the failure names the address and the error; got {message:?}"
        );
    }

    /// A consumed banner press is not half of a double click. Without dropping
    /// the record, a click in the pane, a click on the banner and a click back
    /// in the pane would read as a pair and maximize the surface.
    #[test]
    fn a_banner_press_cannot_become_half_of_a_double_click() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        let rx = recording_opener(&mut app);
        install_pr_banner(&mut app);

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        click_band(&mut app, 30, 19);
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert!(
            matches!(app.fullscreen_overlay, FullscreenOverlay::None),
            "two pane clicks either side of a banner click are not a double click"
        );
        assert_eq!(opened_url(&rx), "https://github.com/owner/repo/pull/42");
        nothing_opened(&rx);
    }

    /// With no banner drawn there is no rect, and the row belongs to the pane
    /// exactly as it did before any of this.
    #[test]
    fn without_a_banner_the_row_still_belongs_to_the_center_pane() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        let rx = recording_opener(&mut app);
        app.focus = FocusPane::Left;

        click_band(&mut app, 30, 19);

        assert_eq!(app.focus, FocusPane::Center, "the pane took the press");
        nothing_opened(&rx);
    }

    /// A press that slides off the band before the button comes up opens
    /// nothing, the way letting go beside a link in a browser does.
    #[test]
    fn a_press_that_slides_off_the_band_opens_nothing() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        let rx = recording_opener(&mut app);
        install_pr_banner(&mut app);

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 19));
        app.handle_mouse(mouse(MouseEventKind::Drag(MouseButton::Left), 30, 12));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 12));

        nothing_opened(&rx);
        assert!(app.pending_pr_banner_press.is_none(), "the record is spent");
    }

    // -- The pure decisions --

    #[test]
    fn the_press_decision_covers_every_case_the_two_paths_ask_about() {
        let link = Some("https://example.com");
        let withheld = TerminalPressAction::Link(LinkPressDecision {
            uri: "https://example.com".to_string(),
            suppress: true,
            open: true,
        });
        let passed_through = TerminalPressAction::Link(LinkPressDecision {
            uri: "https://example.com".to_string(),
            suppress: false,
            open: true,
        });

        assert_eq!(
            decide_terminal_press(
                MouseEventKind::Down(MouseButton::Left),
                KeyModifiers::empty(),
                link,
                true
            ),
            withheld,
            "a plain press on a link is dux's, and a tracking child sees none of it"
        );
        assert_eq!(
            decide_terminal_press(
                MouseEventKind::Down(MouseButton::Left),
                KeyModifiers::empty(),
                link,
                false
            ),
            passed_through,
            "with tracking off there is nothing to withhold"
        );
        assert_eq!(
            decide_terminal_press(
                MouseEventKind::Down(MouseButton::Left),
                KeyModifiers::CONTROL,
                link,
                true
            ),
            TerminalPressAction::ForwardPlainClick,
        );
        assert_eq!(
            decide_terminal_press(
                MouseEventKind::Down(MouseButton::Left),
                KeyModifiers::CONTROL,
                link,
                false
            ),
            passed_through,
            "with no app to hand the click to, the hatch chord opens like a plain click"
        );
        assert_eq!(
            decide_terminal_press(
                MouseEventKind::Down(MouseButton::Left),
                KeyModifiers::SHIFT,
                link,
                true
            ),
            TerminalPressAction::Unclaimed,
            "Shift is the selection modifier and the host's own link gesture"
        );
        assert_eq!(
            decide_terminal_press(
                MouseEventKind::Down(MouseButton::Left),
                KeyModifiers::SHIFT,
                link,
                false
            ),
            TerminalPressAction::Unclaimed,
            "and it stays a selection with tracking off, where dux parts company with the web"
        );
        assert_eq!(
            decide_terminal_press(
                MouseEventKind::Down(MouseButton::Left),
                KeyModifiers::empty(),
                None,
                true
            ),
            TerminalPressAction::Unclaimed,
        );
        for kind in [
            MouseEventKind::Up(MouseButton::Left),
            MouseEventKind::Down(MouseButton::Right),
            MouseEventKind::Down(MouseButton::Middle),
            MouseEventKind::Drag(MouseButton::Left),
            MouseEventKind::ScrollUp,
        ] {
            assert_eq!(
                decide_terminal_press(kind, KeyModifiers::empty(), link, true),
                TerminalPressAction::Unclaimed,
                "only a left PRESS can start a link gesture; {kind:?} must not"
            );
        }
    }

    #[test]
    fn the_release_decision_is_a_click_or_a_drag_that_stayed_on_the_link() {
        assert!(
            link_release_opens(0, Some("https://example.com"), "https://example.com"),
            "press and release in the same cell is a click"
        );
        assert!(
            link_release_opens(0, None, "https://example.com"),
            "a cell the pointer never left is a click even where the lookup answers nothing"
        );
        assert!(
            link_release_opens(4, Some("https://example.com"), "https://example.com"),
            "a gesture along the same link is still that link's click"
        );
        assert!(
            !link_release_opens(4, Some("https://example.com/other"), "https://example.com"),
            "a gesture that ended on a different link opens neither"
        );
        assert!(
            !link_release_opens(1, None, "https://example.com"),
            "a gesture that ended off the link is a drag"
        );
    }

    /// The lookup reads the snapshot's own interned table, so a cell pointing
    /// past its end (the emulator's 256-URI cap leaves later links unrecorded)
    /// resolves to nothing rather than to somebody else's address, and a
    /// rebuilt table is read fresh.
    #[test]
    fn the_link_lookup_follows_the_snapshots_own_table() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "");
        app.snapshot_buf.rows = 16;
        app.snapshot_buf.cols = 55;
        app.snapshot_buf.links = (0..256)
            .map(|i| format!("https://example.com/{i}"))
            .collect();
        app.last_snapshot_id = app.selected_terminal_surface_id();
        let cell = |col: u16, link: u16| crate::pty::SnapshotCell {
            row: 0,
            col,
            symbol: "x".into(),
            fg: crate::pty::CellColor::Reset,
            bg: crate::pty::CellColor::Reset,
            modifier: crate::pty::CellModifier::default(),
            link: Some(link),
        };
        // The 256th interned URI is index 255; index 256 is one past the end.
        app.snapshot_buf.cells = vec![cell(0, 255), cell(1, 256)];

        assert_eq!(
            app.link_at_screen_point(21, 1),
            Some("https://example.com/255")
        );
        assert_eq!(
            app.link_at_screen_point(22, 1),
            None,
            "a cell pointing past the table must resolve to nothing"
        );

        // A rebuild replaces the table; the same cell now names the new address.
        app.snapshot_buf.links = vec!["https://example.com/rebuilt".to_string()];
        app.snapshot_buf.cells = vec![cell(0, 0)];
        assert_eq!(
            app.link_at_screen_point(21, 1),
            Some("https://example.com/rebuilt")
        );
    }

    // -- The fullscreen raw-input path --

    /// Build an SGR press with modifier bits, 1-based like the wire.
    fn sgr_press(cb: u16, cx: u16, cy: u16) -> Vec<u8> {
        format!("\x1b[<{cb};{cx};{cy}M").into_bytes()
    }

    fn interactive_link_app() -> (App, std::sync::mpsc::Receiver<String>) {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;
        app.last_pty_size = (16, 55);
        let rx = recording_opener(&mut app);
        install_linked_cell(&mut app, 4, 9, "P", "https://example.com/pr/1");
        (app, rx)
    }

    /// In fullscreen the same rule applies through the raw mouse path: the
    /// press withholds, the release opens, and the child sees neither half.
    #[test]
    fn fullscreen_click_on_a_linked_cell_opens_it_and_the_child_sees_nothing() {
        let (mut app, rx) = interactive_link_app();

        app.process_raw_input_bytes(&sgr_press(0, 31, 6))
            .expect("the press is handled");
        nothing_opened(&rx);
        app.process_raw_input_bytes(b"\x1b[<0;31;6m")
            .expect("the release is handled");
        assert_eq!(opened_url(&rx), "https://example.com/pr/1");

        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "neither half of a withheld link click may reach the child; got {rendered:?}"
        );
    }

    /// The hatch works in fullscreen too, and the raw bytes carry the Ctrl bit
    /// on every report of the gesture, so the press, the drag and the release
    /// are all rebuilt rather than passed through.
    #[test]
    fn fullscreen_ctrl_click_forwards_a_plain_press_drag_and_release() {
        let (mut app, rx) = interactive_link_app();

        // cb 16 is a left press with Ctrl held; cb 48 the drag that follows it.
        app.process_raw_input_bytes(&sgr_press(16, 31, 6))
            .expect("the press is handled");
        wait_for_forwarded_echo(&app, "[<0;10;5M");
        app.process_raw_input_bytes(&sgr_press(48, 33, 6))
            .expect("the drag is handled");
        app.process_raw_input_bytes(b"\x1b[<16;33;6m")
            .expect("the release is handled");

        let rendered = wait_for_forwarded_echo(&app, "[<0;12;5m");
        assert!(
            !rendered.contains("[<16;") && !rendered.contains("[<48;"),
            "no part of the hatch gesture may carry its modifier bit to the child; got {rendered:?}"
        );
        assert_eq!(
            app.center_mouse_forward, None,
            "the release must disarm the forwarding record"
        );
        nothing_opened(&rx);
    }

    /// Shift in fullscreen keeps meaning dux's own selection, and never opens.
    #[test]
    fn fullscreen_shift_click_on_a_linked_cell_opens_nothing() {
        let (mut app, rx) = interactive_link_app();

        // cb 4 is a left press with Shift held.
        app.process_raw_input_bytes(&sgr_press(4, 31, 6))
            .expect("the press is handled");
        app.process_raw_input_bytes(b"\x1b[<4;31;6m")
            .expect("the release is handled");

        nothing_opened(&rx);
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "a Shift press selects locally; got {rendered:?}"
        );
    }

    /// The divider grip is dux's (the mouse "dux wins" rule): when a divider
    /// column overlaps the terminal rect, the resize drag wins over click
    /// forwarding.
    #[test]
    fn windowed_divider_drag_wins_over_click_forwarding() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        // Stretch the recorded terminal rect over the left divider column
        // (center.x == 20 in the synthetic layout) so the two claims overlap.
        app.mouse_layout.agent_term = Some(Rect::new(20, 1, 56, 16));

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 20, 5));

        assert_eq!(
            app.mouse_drag,
            Some(ResizeDragState::LeftDivider),
            "the divider grab must win"
        );
        assert_eq!(app.center_mouse_forward, None);
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "a divider grab must not also forward a click; got {rendered:?}"
        );
        // Clean up the drag so the Up arm does not persist pane widths.
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 20, 5));
    }

    /// Middle and right buttons forward with their SGR codes (1 and 2).
    #[test]
    fn windowed_middle_and_right_clicks_forward_their_button_codes() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Right), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Right), 30, 5));
        wait_for_forwarded_echo(&app, "[<2;10;5M");
        wait_for_forwarded_echo(&app, "[<2;10;5m");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Middle), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Middle), 30, 5));
        wait_for_forwarded_echo(&app, "[<1;10;5M");
        wait_for_forwarded_echo(&app, "[<1;10;5m");
    }

    /// The macro bar suspends the pane for the mouse exactly as it does for
    /// keys (`center_typeable()` excludes it): a click inside the agent area
    /// with the bar open is NOT forwarded.
    #[test]
    fn windowed_click_is_not_forwarded_while_the_macro_bar_is_open() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        app.macro_bar = Some(crate::app::MacroBarState {
            input: TextInput::new(),
            selected: 0,
            previous_input_target: InputTarget::None,
        });

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert_eq!(app.center_mouse_forward, None);
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "a click while the macro bar is open must not reach the child; got {rendered:?}"
        );
    }

    /// Resize mode suspends the pane for the mouse exactly as it does for
    /// keys: a click inside the agent area in resize mode is NOT forwarded.
    #[test]
    fn windowed_click_is_not_forwarded_in_resize_mode() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");
        app.resize_mode = true;

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert_eq!(app.center_mouse_forward, None);
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<"),
            "a click in resize mode must not reach the child; got {rendered:?}"
        );
    }

    /// A SECOND button pressed mid-drag releases the in-flight button before
    /// arming the new one: the single-slot forward state can carry one
    /// lifecycle, and silently overwriting it stranded the first button as
    /// held forever on the child.
    #[test]
    fn a_second_button_pressed_mid_drag_releases_the_first() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        wait_for_forwarded_echo(&app, "[<0;10;5M");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Right), 31, 5));

        assert_eq!(
            app.center_mouse_forward,
            Some(2),
            "the new press must own the forward slot"
        );
        // The left button's release lands at the new press's position,
        // BEFORE the right button's press.
        wait_for_forwarded_echo(&app, "[<0;11;5m^[[<2;11;5M");
    }

    /// A child that dropped mouse tracking MID-DRAG no longer wants any
    /// report: the release writes nothing and the state just clears
    /// (writing it anyway would type raw SGR bytes at the replacement app).
    #[test]
    fn release_is_not_written_when_the_child_dropped_mouse_mode_mid_drag() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        // Enable tracking, swallow the 10-byte press report, then DISABLE
        // tracking, then echo everything else: the release (if wrongly
        // written) would render as visible `^[[<0;10;5m` text.
        let cmd = "stty raw -echo; printf '\\033[?1000h'; head -c 10 >/dev/null; \
                   printf '\\033[?1000l'; exec cat -v"
            .to_string();
        let client = PtyClient::spawn(
            "/bin/sh",
            &["-c".to_string(), cmd],
            std::path::Path::new("."),
            24,
            80,
            100,
        )
        .expect("spawn pty");
        app.engine.providers.insert(session_id, client);
        app.selected_left = 1;
        app.session_surface = SessionSurface::Agent;
        app.center_mode = CenterMode::Agent;
        install_mouse_layout(&mut app);
        for _ in 0..400 {
            if app
                .selected_terminal_surface_client()
                .is_some_and(|p| p.has_mouse_mode())
            {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            app.selected_terminal_surface_client()
                .is_some_and(|p| p.has_mouse_mode()),
            "the child never enabled mouse tracking"
        );

        // The press ("\\x1b[<0;10;5M", 10 bytes) is swallowed by `head`,
        // after which the child turns tracking off.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        for _ in 0..400 {
            if app
                .selected_terminal_surface_client()
                .is_some_and(|p| !p.has_mouse_mode())
            {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            app.selected_terminal_surface_client()
                .is_some_and(|p| !p.has_mouse_mode()),
            "the child never dropped mouse tracking"
        );

        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));

        assert_eq!(
            app.center_mouse_forward, None,
            "the release must still disarm the forwarding state"
        );
        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = forwarded_echo(&app);
        assert!(
            !rendered.contains("[<0;10;5m"),
            "no release report may reach a child that dropped tracking; got {rendered:?}"
        );
    }

    /// A prompt that opens MID-DRAG must not swallow the release: the
    /// clamped release is delivered to the child first, then the prompt
    /// handles the event as usual.
    #[test]
    fn a_prompt_opened_mid_drag_still_delivers_the_release() {
        let mut app = test_app(default_bindings());
        install_mouse_forward_child(&mut app, "\\033[?1000h");

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        wait_for_forwarded_echo(&app, "[<0;10;5M");

        // Something opens a modal mid-drag (a worker event, a key path).
        app.prompt = PromptState::Command {
            input: TextInput::new(),
            selected: 0,
        };

        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));

        assert_eq!(
            app.center_mouse_forward, None,
            "the release must disarm the forward even with a prompt up"
        );
        wait_for_forwarded_echo(&app, "[<0;10;5m");
        assert!(
            matches!(app.prompt, PromptState::Command { .. }),
            "the prompt stays open; only the stuck-button hazard is resolved"
        );
    }

    #[test]
    fn mouse_double_click_center_from_left_pane_opens_fullscreen() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        app.selected_left = 1;
        app.center_mode = CenterMode::Agent;
        app.focus = FocusPane::Left;
        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "printf ready; sleep 0.2".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );

        // First click focuses the center pane (from Left).
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        assert_eq!(app.focus, FocusPane::Center);
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::None);

        // Second click completes the double-click and activates fullscreen.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        assert_eq!(app.input_target, InputTarget::Agent);
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Agent);
    }

    #[test]
    fn mouse_up_between_clicks_does_not_break_double_click() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        app.selected_left = 1;
        app.center_mode = CenterMode::Agent;
        app.focus = FocusPane::Center;
        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "printf ready; sleep 0.2".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );

        // Down → Up → Down mirrors what the event loop sees for a real
        // double-click.  The Up must not interfere with detection.
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), 30, 5));
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 30, 5));

        assert_eq!(app.input_target, InputTarget::Agent);
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Agent);
    }

    #[test]
    fn mouse_wheel_left_pane_advances_selection_under_cursor() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        app.focus = FocusPane::Center;
        app.selected_left = 0;

        app.handle_mouse(mouse(MouseEventKind::ScrollDown, 2, 1));

        assert_eq!(app.focus, FocusPane::Left);
        assert_eq!(app.selected_left, 1);
    }

    /// Spawn a real child that prints enough lines to build alacritty history,
    /// wait until the child has printed EVERYTHING, and only then seed the
    /// scrollback offset to `lines`.
    ///
    /// Waiting is the whole point. `seq` is line buffered on a terminal, so its
    /// 200 lines arrive as many small writes, and both `set_scrollback` and
    /// `scroll` CLAMP to the history that exists at the instant they run: a seed
    /// taken mid-stream and the wheel step the caller makes right after it clamp
    /// against different, still-growing histories and disagree. Seeding after
    /// the stream is over means both calls clamp against the same, final
    /// history.
    ///
    /// The child therefore prints a sentinel with NO trailing newline after the
    /// numbers, so its cursor parks at a position no earlier write can produce
    /// (every `seq` line ends in a newline and leaves the cursor at column 0).
    /// `wait_for_agent_cursor` blocking on that position proves the whole
    /// stream ahead of it was ingested, and `sleep` then keeps the PTY silent,
    /// so 200 lines of history are all present before anything is seeded.
    /// That guarantee rests on the tail of the command staying SILENT: anything
    /// printed after the sentinel would move the cursor off the awaited
    /// position, and the failure would surface as a confusing
    /// `wait_for_agent_cursor` timeout rather than as "the sentinel is no longer
    /// the last thing written".
    fn install_scrolled_pty(app: &mut App, lines: usize) {
        let session_id = app.engine.sessions[0].id.clone();
        let args = vec![
            "-c".to_string(),
            "seq 1 200; printf READY; sleep 30".to_string(),
        ];
        let client = PtyClient::spawn("/bin/sh", &args, std::path::Path::new("."), 24, 80, 1000)
            .expect("spawn pty");
        app.engine.providers.insert(session_id, client);
        app.session_surface = SessionSurface::Agent;

        // Last row of the 24-row grid, just past the 5-character sentinel.
        crate::app::test_support::wait_for_agent_cursor(app, 23, 5);

        let provider = app
            .selected_terminal_surface_client()
            .expect("provider for selected session");
        provider.set_scrollback(lines);
        assert_eq!(
            provider.scrollback_offset(),
            lines,
            "the seed itself failed: the PTY did not have {lines} rows of \
             history to scroll back into, so any assertion about the wheel \
             step past this point would be measuring the clamp instead"
        );
    }

    // -- A selection must follow its TEXT, not its screen row --

    /// Spawn a child that prints exactly what the test feeds it and nothing
    /// else, so output arrives ON DEMAND instead of on the child's own
    /// schedule. `stty -echo` is what makes it exact: with echo left on, the
    /// line driver prints each fed line once and `cat` prints it again, and the
    /// row arithmetic these tests assert measures the double. That is not
    /// hypothetical: feeding 40 lines without waiting for the `stty` produced
    /// 57 lines of history instead of 16, because the write beat the shell to
    /// it. The `READY` sentinel is printed AFTER the `stty`, so blocking on it
    /// proves echo is off before anything is fed.
    fn install_feedable_pty(app: &mut App) {
        install_feedable_pty_with_scrollback(app, 1000);
    }

    /// The same fixture with an explicit scrollback capacity, so a test can
    /// SATURATE the history ring without feeding ten thousand lines. The
    /// capacity is also written into config, because that is where the App
    /// reads it from (see `App::snapshot_selection_origin`); leaving the two
    /// out of step would make the fixture lie about which regime it is in.
    fn install_feedable_pty_with_scrollback(app: &mut App, scrollback: usize) {
        app.engine.config.ui.agent_scrollback_lines = scrollback;
        let session_id = app.engine.sessions[0].id.clone();
        let args = vec![
            "-c".to_string(),
            "stty -echo; printf 'READY\\n'; cat".to_string(),
        ];
        let client = PtyClient::spawn(
            "/bin/sh",
            &args,
            std::path::Path::new("."),
            24,
            80,
            scrollback,
        )
        .expect("spawn pty");
        app.engine.providers.insert(session_id, client);
        app.session_surface = SessionSurface::Agent;
        for _ in 0..200 {
            app.refresh_snapshot_buf();
            if app
                .snapshot_buf
                .cells
                .iter()
                .any(|c| c.row == 0 && c.col == 0 && c.symbol == "R")
            {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        panic!("PTY child never reached its READY sentinel within 2s");
    }

    /// Feed `text` to the child and block until the grid has exactly `total`
    /// lines of scrollback. Waiting on the history depth rather than on a sleep
    /// means the test waits for the fact it depends on: history only grows when
    /// alacritty actually scrolls a line off the top, which is precisely the
    /// event these tests are about.
    fn feed_until_history(app: &mut App, text: &str, total: usize) {
        if let Some(provider) = app.selected_terminal_surface_client() {
            let _ = provider.write_bytes(text.as_bytes());
        }
        for _ in 0..200 {
            app.refresh_snapshot_buf();
            if app.snapshot_buf.scrollback_total == total {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        panic!(
            "PTY reached {} lines of scrollback, expected {total}",
            app.snapshot_buf.scrollback_total
        );
    }

    /// The viewport row whose text starts with `needle`, read from the live
    /// snapshot. Scanned rather than hardcoded so the tests assert the
    /// translation, not a hand-computed grid layout.
    fn snapshot_row_of(app: &mut App, needle: &str) -> u16 {
        app.refresh_snapshot_buf();
        let mut rows: std::collections::BTreeMap<u16, String> = std::collections::BTreeMap::new();
        for cell in &app.snapshot_buf.cells {
            rows.entry(cell.row).or_default().push_str(&cell.symbol);
        }
        rows.into_iter()
            .find(|(_, line)| line.trim().starts_with(needle))
            .map(|(row, _)| row)
            .unwrap_or_else(|| panic!("no viewport row holds {needle}"))
    }

    /// Select one row's text and stamp the frame it was read in, exactly as a
    /// mouse drag does.
    fn select_row(app: &mut App, row: u16, last_col: u16) {
        app.terminal_selection = Some(TerminalSelection {
            anchor: TermGridPos { row, col: 0 },
            end: TermGridPos { row, col: last_col },
            dragging: false,
            origin: app.snapshot_selection_origin(),
        });
    }

    /// Fill the grid and park 16 lines in history, then hand back the viewport
    /// row holding `L30`.
    fn fill_and_select_l30(app: &mut App) -> u16 {
        install_feedable_pty(app);
        let mut fill = String::new();
        for n in 0..40 {
            fill.push_str(&format!("L{n:02}\n"));
        }
        // 41 lines (40 fed plus the READY sentinel) through a 24-row grid,
        // with the trailing newline pushing the cursor onto a 42nd row, leaves
        // 18 lines in history. MEASURED, not derived: the first version of this
        // said 17 and the helper reported 18.
        feed_until_history(app, &fill, 18);
        let row = snapshot_row_of(app, "L30");
        select_row(app, row, 2);
        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "the fixture must start by selecting the text it names"
        );
        row
    }

    #[test]
    fn a_cells_column_count_comes_from_its_base_character() {
        // The snapshot folds combining marks into the cell they modify and drops
        // the spacer that follows a wide glyph, so the base character alone
        // decides how many columns the cell spans.
        assert_eq!(snapshot_cell_columns("a"), 1);
        assert_eq!(snapshot_cell_columns("日"), 2);
        assert_eq!(snapshot_cell_columns("e\u{301}"), 1);
        assert_eq!(
            snapshot_cell_columns("\u{301}"),
            1,
            "a bare mark still owns a cell"
        );
        assert_eq!(snapshot_cell_columns(""), 1);
    }

    #[test]
    fn copied_wide_glyphs_carry_no_invented_spaces() {
        // The wide glyph's spacer cell is absent from the snapshot, so the run is
        // at columns 0, 2, 4. Counting chars read that as a gap and padded it.
        let cells = [(0u16, 0u16, "日"), (0, 2, "本"), (0, 4, "語")];
        assert_eq!(assemble_selection_text(&cells, 0, 0, 0), "日本語");
    }

    #[test]
    fn copied_combining_marks_do_not_eat_the_next_column() {
        // "e" plus a combining acute is ONE cell, so the next cell is at column 1
        // and nothing is padded. Measuring by chars made the cell look two wide
        // and swallowed the following character's column.
        let cells = [(0u16, 0u16, "e\u{301}"), (0, 1, "x")];
        assert_eq!(assemble_selection_text(&cells, 0, 0, 0), "e\u{301}x");
    }

    #[test]
    fn a_genuine_column_gap_is_still_padded() {
        // Nothing about the wide-glyph fix may lose a real hole: a run that skips
        // columns keeps its spacing, and a run indented past the selection start
        // keeps that indent.
        let cells = [(0u16, 0u16, "a"), (0, 4, "b")];
        assert_eq!(assemble_selection_text(&cells, 0, 0, 0), "a   b");

        let indented = [(0u16, 3u16, "a")];
        assert_eq!(assemble_selection_text(&indented, 0, 0, 0), "   a");

        // A wide glyph followed by a real hole pads from the column AFTER the
        // glyph's two cells, not from the column after its one char.
        let mixed = [(0u16, 0u16, "日"), (0, 5, "z")];
        assert_eq!(assemble_selection_text(&mixed, 0, 0, 0), "日   z");
    }

    #[test]
    fn a_multi_row_selection_keeps_its_blank_rows() {
        let cells = [(1u16, 0u16, "a"), (3, 0, "b")];
        assert_eq!(assemble_selection_text(&cells, 0, 0, 4), "\na\n\nb\n");
        assert!(assemble_selection_text(&[], 0, 0, 4).is_empty());
    }

    /// Output arriving after the drag must not change what the copy yields.
    /// This is the live-edge race: the rows slide up under the recorded
    /// coordinates, so without translating them the copy takes whatever text
    /// landed on those screen rows instead.
    #[test]
    fn copy_follows_its_text_when_output_arrives() {
        let mut app = test_app(default_bindings());
        fill_and_select_l30(&mut app);

        feed_until_history(&mut app, "M00\nM01\nM02\n", 21);

        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "the copy must yield the highlighted text, not the text that \
             scrolled into its screen rows"
        );
    }

    /// Scrolling back must move the highlight WITH its text. The selection is
    /// no longer cleared on a local scroll, so the render predicate has to
    /// answer for the row the text moved to and stop answering for the row it
    /// left.
    #[test]
    fn highlight_follows_its_text_when_the_view_scrolls() {
        let mut app = test_app(default_bindings());
        let row = fill_and_select_l30(&mut app);

        app.selected_terminal_surface_client()
            .expect("provider")
            .scroll(true, 5);
        app.refresh_snapshot_buf();
        let now = app.snapshot_selection_origin();
        let sel = app.terminal_selection.clone().expect("selection survives");

        assert_eq!(
            snapshot_row_of(&mut app, "L30"),
            row + 5,
            "scrolling back 5 lines must carry the text 5 rows down the screen"
        );
        assert!(
            sel.contains_live(row + 5, 0, now),
            "the highlight must cover the row the text moved to"
        );
        assert!(
            !sel.contains_live(row, 0, now),
            "the highlight must leave the row the text vacated"
        );
        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "and the copy must still yield that text"
        );
    }

    /// Feed `text` and block until `needle` has appeared in the viewport. The
    /// sibling `feed_until_history` cannot be used once the ring is SATURATED:
    /// history stops moving there, so a wait on its depth returns before the
    /// child has finished writing.
    fn feed_until_row_present(app: &mut App, text: &str, needle: &str) {
        if let Some(provider) = app.selected_terminal_surface_client() {
            let _ = provider.write_bytes(text.as_bytes());
        }
        for _ in 0..200 {
            app.refresh_snapshot_buf();
            let mut rows: std::collections::BTreeMap<u16, String> =
                std::collections::BTreeMap::new();
            for cell in &app.snapshot_buf.cells {
                rows.entry(cell.row).or_default().push_str(&cell.symbol);
            }
            if rows.values().any(|line| line.trim().starts_with(needle)) {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        panic!("PTY never showed {needle} within 2s");
    }

    /// A grid whose scrollback ring is FULL, holding L00..L39 with L30 selected.
    fn app_with_saturated_scrollback() -> App {
        let mut app = test_app(default_bindings());
        install_feedable_pty_with_scrollback(&mut app, 5);
        let mut fill = String::new();
        for n in 0..40 {
            fill.push_str(&format!("L{n:02}\n"));
        }
        feed_until_row_present(&mut app, &fill, "L39");
        app.refresh_snapshot_buf();
        assert_eq!(
            app.snapshot_buf.scrollback_total, 5,
            "test premise: the ring must be at capacity, not merely deep"
        );
        let row = snapshot_row_of(&mut app, "L30");
        select_row(&mut app, row, 2);
        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "the fixture must start by selecting the text it names"
        );
        app
    }

    /// Once the scrollback ring is FULL, `to_origin_row`'s correction stops
    /// working. It uses history GROWTH to stand in for the grid's advancing
    /// bottom, and that equivalence holds only while history is growing: at
    /// capacity the ring stops growing while the bottom keeps moving, so the
    /// correction under-counts by exactly the number of lines produced.
    ///
    /// This is not an edge case. With the default 10,000-line scrollback,
    /// saturation is the STEADY STATE of any long session, so silently pointing
    /// the highlight and the copy at different text would be the normal
    /// behaviour rather than a corner. Measured on this 5-line ring before the
    /// fix: select L30, feed three lines, and the copy yields "L33". A
    /// selection that vanishes is honest; one that quietly names other text is
    /// not, so the selection is dropped instead.
    #[test]
    fn a_saturated_scrollback_drops_the_selection_rather_than_naming_other_text() {
        let mut app = app_with_saturated_scrollback();

        feed_until_row_present(&mut app, "M00\nM01\nM02\n", "M02");
        app.refresh_snapshot_buf();
        app.drop_drifted_selection();

        assert!(
            app.terminal_selection.is_none(),
            "the selection must be dropped, not silently re-pointed; it still \
             named {:?}",
            app.terminal_selection_text()
        );
    }

    /// The guard is keyed on SATURATION, not on "output arrived". Below
    /// capacity the correction is exact, and a selection that follows its text
    /// through arriving output is the behaviour the translation exists for.
    #[test]
    fn an_unsaturated_scrollback_still_follows_its_text_through_output() {
        let mut app = test_app(default_bindings());
        fill_and_select_l30(&mut app);

        feed_until_history(&mut app, "M00\nM01\nM02\n", 21);
        app.refresh_snapshot_buf();
        app.drop_drifted_selection();

        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "a selection below capacity must survive and keep naming its text"
        );
    }

    /// A user scroll is not drift, even at capacity: its arithmetic is exact
    /// (the offset moves, the text moves with it). Only the grid moving under
    /// dux counts, so dux re-stamps the selection against the frame produced by
    /// its OWN scrolls. Without that, "scroll back, select, scroll a bit more"
    /// would lose the selection on every long-running agent.
    #[test]
    fn a_users_own_scroll_does_not_count_as_drift_at_capacity() {
        let mut app = app_with_saturated_scrollback();

        app.scroll_pty(crate::app::ScrollDirection::Up, 2);
        app.refresh_snapshot_buf();
        app.drop_drifted_selection();

        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "the user's own scroll must keep the selection on its text"
        );
    }

    /// The drag endpoint is written while the button is still DOWN, so output
    /// that arrives mid-drag slides the grid under it. `anchor` and `origin`
    /// are stamped in the frame the mouse went down in, and the endpoint has to
    /// be recorded in that same frame or the selection's EXTENT is wrong by the
    /// drift, in the highlight and in the copy alike.
    ///
    /// Translation was implemented at both READ sites and omitted at the one
    /// WRITE site. Nothing caught it because every other selection fixture in
    /// this file builds its selection with the drag already finished, so the
    /// endpoint is never written against a frame that has since moved.
    #[test]
    fn a_drag_that_races_output_selects_the_rows_the_user_dragged_over() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        let term = app.mouse_layout.agent_term.expect("agent term rect");
        fill_and_select_l30(&mut app);
        // Start from no selection: this test builds one with the mouse.
        app.terminal_selection = None;

        // Button down on L30, in the frame the user is looking at.
        let anchor_row = snapshot_row_of(&mut app, "L30");
        app.handle_terminal_selection_mouse(mouse(
            MouseEventKind::Down(MouseButton::Left),
            term.x,
            term.y + anchor_row,
        ));

        // Three lines arrive while the button is still held. The grid slides up
        // by three; the user's finger has not moved.
        feed_until_history(&mut app, "M00\nM01\nM02\n", 21);

        // Now they drag down to L32, wherever it has ended up on screen.
        let end_row = snapshot_row_of(&mut app, "L32");
        assert_eq!(
            end_row,
            anchor_row - 1,
            "test premise: the output moved the text under the drag (L32 is now \
             ABOVE where L30 was), so an untranslated endpoint cannot be right \
             by accident"
        );
        app.handle_terminal_selection_mouse(mouse(
            MouseEventKind::Drag(MouseButton::Left),
            term.x + 2,
            term.y + end_row,
        ));

        assert_eq!(
            app.terminal_selection_text(),
            "L30\nL31\nL32",
            "the selection must cover the text the user dragged over"
        );
    }

    /// Point the selected agent's provider at a fixed `forward_scroll`, so a
    /// wheel test picks its branch instead of depending on whether the child
    /// happens to have raised the alt screen.
    fn set_forward_scroll(app: &mut App, forward: bool) {
        let provider = app.engine.sessions[0].provider.as_str().to_string();
        let entry = app
            .engine
            .config
            .providers
            .commands
            .entry(provider.clone())
            .or_insert_with(|| dux_core::config::ProviderCommandConfig {
                command: provider,
                ..Default::default()
            });
        entry.forward_scroll = Some(forward);
    }

    /// Wheel-up over the PTY pane in interactive mode, as the host sends it
    /// (SGR button 64), landing inside the installed `agent_term` rect.
    const WHEEL_UP_IN_PANE: &[u8] = b"\x1b[<64;30;5M";

    /// A wheel that scrolls dux's OWN scrollback keeps the selection: the text
    /// is still on screen and `to_origin_row` follows it there. This is the
    /// behaviour the old unconditional clear made impossible, which is what
    /// made "scroll back, then select" the only reliable way to copy.
    #[test]
    fn local_wheel_scroll_keeps_the_selection() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        fill_and_select_l30(&mut app);
        set_forward_scroll(&mut app, false);
        app.input_target = InputTarget::Agent;

        app.process_raw_input_bytes(WHEEL_UP_IN_PANE)
            .expect("raw input");

        assert!(
            app.terminal_selection.is_some(),
            "a local scroll must not drop the selection"
        );
        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "and it must still name the same text"
        );
    }

    /// A WIDTH change reflows the grid under the recorded rows at ANY history
    /// depth, so the selection has to be retired on a column change and not
    /// only at saturation. Before this, a selection quietly survived a resize
    /// and named whatever text landed on its rows.
    #[test]
    fn a_selection_is_retired_when_the_grid_is_narrowed_under_it() {
        let mut app = test_app(default_bindings());
        fill_and_select_l30(&mut app);
        let stamped = app
            .terminal_selection
            .as_ref()
            .expect("selection")
            .origin
            .grid_size;
        assert!(
            !app.terminal_selection
                .as_ref()
                .expect("selection")
                .origin
                .history_saturated,
            "test premise: this must be the BELOW-saturation regime, where the \
             generation check does not fire"
        );

        app.selected_terminal_surface_client()
            .expect("provider")
            .resize(stamped.0, stamped.1 - 10)
            .expect("resize");
        app.refresh_snapshot_buf();
        app.drop_drifted_selection();

        assert!(
            app.terminal_selection.is_none(),
            "a narrowed grid must retire the selection rather than translate it \
             onto arbitrary rows"
        );
    }

    /// The paired half of the width rule: a HEIGHT-only change is not a
    /// reflow. Alacritty moves whole lines between history and the viewport
    /// without rewrapping them, the offset/total arithmetic translates that
    /// exactly, and the selection keeps naming its text. Retiring on any
    /// dimension change threw away a selection every time the user resized the
    /// terminal vertically, which the arithmetic never needed.
    #[test]
    fn a_selection_survives_a_rows_only_resize_and_keeps_naming_its_text() {
        let mut app = test_app(default_bindings());
        fill_and_select_l30(&mut app);
        let stamped = app
            .terminal_selection
            .as_ref()
            .expect("selection")
            .origin
            .grid_size;

        app.selected_terminal_surface_client()
            .expect("provider")
            .resize(stamped.0 - 4, stamped.1)
            .expect("resize");
        app.refresh_snapshot_buf();
        app.drop_drifted_selection();

        assert_eq!(
            app.terminal_selection_text(),
            "L30",
            "a rows-only resize must keep the selection on the text it named"
        );
    }

    /// The paired half: the ring capacity a selection is judged against is the
    /// one the PTY was SPAWNED with. Capacity is fixed when the emulator is
    /// built, so reading live config made a full ring read as unsaturated the
    /// moment someone raised the setting through a reload.
    #[test]
    fn saturation_is_judged_against_the_ptys_own_capacity_not_live_config() {
        let mut app = app_with_saturated_scrollback();
        assert!(
            app.snapshot_selection_origin().history_saturated,
            "test premise: the 5-line ring must be full"
        );

        // A live reload raises the setting. No running PTY hears about it, so
        // the ring is still full and the selection must still be retired.
        app.engine.config.ui.agent_scrollback_lines = 10_000;
        assert_eq!(
            app.selected_terminal_surface_client()
                .expect("provider")
                .scrollback_capacity(),
            5,
            "capacity is fixed at spawn; a config reload cannot move it"
        );
        assert!(
            app.snapshot_selection_origin().history_saturated,
            "the reload must not make a saturated ring read as unsaturated"
        );
    }

    /// A wheel that is FORWARDED to the child does drop it. The child repaints
    /// the grid however it likes, and nothing in the snapshot's scroll numbers
    /// describes that, so there is no text left to follow.
    #[test]
    fn forwarded_wheel_scroll_drops_the_selection() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        fill_and_select_l30(&mut app);
        set_forward_scroll(&mut app, true);
        app.input_target = InputTarget::Agent;

        app.process_raw_input_bytes(WHEEL_UP_IN_PANE)
            .expect("raw input");

        assert!(
            app.terminal_selection.is_none(),
            "a forwarded scroll must drop the selection"
        );
    }

    /// The RENDERER half of the same guarantee. The test above pins the
    /// predicate; this one draws a real frame and reads the styles back, so the
    /// agent pane cannot quietly go back to testing raw screen rows.
    #[test]
    fn rendered_highlight_follows_its_text_when_the_view_scrolls() {
        let mut app = test_app(default_bindings());
        app.center_mode = CenterMode::Agent;
        fill_and_select_l30(&mut app);

        let mut terminal = test_terminal();
        // The first frame resizes the PTY from its spawn geometry to the pane's,
        // and a selection stamped against a geometry that was never drawn is
        // retired by design (see `SelectionOrigin::grid_size`). A real drag
        // happens on a drawn grid, so settle the geometry and stamp there.
        draw_frame(&mut app, &mut terminal);
        let row = snapshot_row_of(&mut app, "L30");
        select_row(&mut app, row, 2);

        draw_frame(&mut app, &mut terminal);
        let before = highlighted_rows(&terminal);
        assert_eq!(
            before.len(),
            1,
            "the fixture must draw exactly one highlighted row or this test \
             proves nothing"
        );
        // Naming the TEXT, not just the row.
        assert_eq!(
            highlighted_text(&terminal, before[0]),
            "L30",
            "the highlight must sit on the text that was selected"
        );

        app.selected_terminal_surface_client()
            .expect("provider")
            .scroll(true, 5);
        draw_frame(&mut app, &mut terminal);
        let after = highlighted_rows(&terminal);

        assert_eq!(
            highlighted_text(&terminal, after.first().copied().unwrap_or(0)),
            "L30",
            "and must still sit on it after the scroll"
        );
        assert_eq!(
            after,
            before.iter().map(|r| r + 5).collect::<Vec<_>>(),
            "scrolling back 5 lines must carry the painted highlight 5 screen \
             rows down with its text, not leave it where it was (selection \
             recorded at PTY row {row})"
        );
    }

    /// The drawn text of the highlighted cells on one screen row.
    fn highlighted_text(terminal: &ratatui::Terminal<TestBackend>, y: u16) -> String {
        let buffer = terminal.backend().buffer();
        let bg = Theme::default_dark().selection_bg;
        (buffer.area.left()..buffer.area.right())
            .filter(|x| buffer[(*x, y)].style().bg == Some(bg))
            .map(|x| buffer[(x, y)].symbol().to_string())
            .collect()
    }

    /// Screen rows carrying at least one cell painted with the theme's
    /// selection background. Read from the drawn buffer, so it answers what the
    /// user sees. Matching on the BACKGROUND rather than on the whole style is
    /// deliberate: `Cell::set_style` PATCHES, so a highlighted PTY cell keeps
    /// whatever the snapshot gave it and never compares equal to
    /// `selection_style()` outright.
    fn highlighted_rows(terminal: &ratatui::Terminal<TestBackend>) -> Vec<u16> {
        let buffer = terminal.backend().buffer();
        let bg = Theme::default_dark().selection_bg;
        let mut rows: Vec<u16> = Vec::new();
        for y in buffer.area.top()..buffer.area.bottom() {
            for x in buffer.area.left()..buffer.area.right() {
                if buffer[(x, y)].style().bg == Some(bg) {
                    rows.push(y);
                    break;
                }
            }
        }
        rows
    }

    /// One wheel tick over the inline PTY pane scrolls the LOCAL scrollback by
    /// exactly `MOUSE_WHEEL_LINES` (3), not 1. The child (`sh`) has no mouse
    /// tracking and no alt screen, so the wheel takes the local-scroll branch.
    #[test]
    fn mouse_wheel_over_pty_pane_scrolls_three_lines_per_tick() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        install_scrolled_pty(&mut app, 10);

        // (30, 5) is inside the center pane / agent terminal area.
        app.handle_mouse(mouse(MouseEventKind::ScrollUp, 30, 5));

        let offset = app
            .selected_terminal_surface_client()
            .expect("provider")
            .scrollback_offset();
        // LITERAL 13, not `10 + MOUSE_WHEEL_LINES`: asserting against the
        // constant would track any change to it and never fail, pinning
        // nothing. Three lines per tick is the contract.
        assert_eq!(
            offset, 13,
            "a wheel tick must scroll exactly 3 lines further back"
        );
    }

    /// The same 3-line wheel step must hold on the (non-interactive) fullscreen
    /// PTY surface, which routes through the same `handle_center_mouse_wheel`
    /// via `mouse_target`'s fullscreen branch.
    #[test]
    fn mouse_wheel_in_fullscreen_pty_scrolls_three_lines_per_tick() {
        let mut app = test_app(default_bindings());
        install_mouse_layout(&mut app);
        install_scrolled_pty(&mut app, 10);
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        app.handle_mouse(mouse(MouseEventKind::ScrollUp, 30, 5));

        let offset = app
            .selected_terminal_surface_client()
            .expect("provider")
            .scrollback_offset();
        // Literal 13 for the same reason as the inline-pane test above.
        assert_eq!(
            offset, 13,
            "the fullscreen surface shares the 3-line wheel step"
        );
    }

    // -- Maximized (fullscreen) surfaces must not answer windowed geometry --
    //
    // These tests deliberately RENDER into a `TestBackend` instead of using
    // `install_mouse_layout`. The synthetic fixture records no tab regions at
    // all and hand-picks divider columns, so it cannot reproduce the bug:
    // the stale rects only exist because a real frame recorded them.

    /// Draw the whole widget tree so every mouse-geometry registry
    /// (`mouse_layout`, `agent_tab_regions`) holds the rects a real frame
    /// recorded.
    fn draw_frame(app: &mut App, terminal: &mut ratatui::Terminal<TestBackend>) {
        terminal
            .draw(|frame| app.render(frame))
            .expect("render frame");
    }

    fn test_terminal() -> ratatui::Terminal<TestBackend> {
        ratatui::Terminal::new(TestBackend::new(100, 30)).expect("terminal")
    }

    fn seed_input_tab(app: &mut App, session_id: &str, tab_id: &str, provider: &str, order: i64) {
        app.engine.agent_tabs.insert(
            tab_id.to_string(),
            crate::model::AgentTab {
                id: tab_id.to_string(),
                session_id: session_id.to_string(),
                provider: ProviderKind::from_str(provider),
                sort_order: order,
                created_at: Utc::now(),
            },
        );
    }

    /// A maximized agent draws no pane dividers, but the windowed layout's
    /// divider columns are still recorded. A click inside the maximized
    /// surface that happens to land on one of those columns must not start a
    /// resize drag on an invisible divider.
    #[test]
    fn click_inside_maximized_agent_starts_no_resize_drag() {
        let mut app = test_app(default_bindings());
        let mut terminal = test_terminal();
        draw_frame(&mut app, &mut terminal);

        // The windowed left divider column, as the real layout recorded it.
        let divider = app.mouse_layout.left.x + app.mouse_layout.left.width.saturating_sub(1);

        app.fullscreen_overlay = FullscreenOverlay::Agent;
        draw_frame(&mut app, &mut terminal);

        let term = app
            .mouse_layout
            .agent_term
            .expect("the maximized surface records its terminal area");
        assert!(
            divider >= term.x && divider < term.x + term.width,
            "the divider column must fall INSIDE the maximized surface or this test proves nothing"
        );
        let row = term.y + term.height / 2;

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), divider, row));

        assert!(
            app.mouse_drag.is_none(),
            "a click inside the maximized agent must not grab an invisible pane divider"
        );
        assert_eq!(
            app.fullscreen_overlay,
            FullscreenOverlay::Agent,
            "the click was inside, so the surface stays maximized"
        );
    }

    /// A plain horizontal arrow no longer switches tabs. It used to be a
    /// default alongside the Ctrl arrow, justified by Center scope being
    /// unreachable while keys flowed to a PTY; minimized typing killed that
    /// premise, so the plain arrows now belong to the agent (they type a
    /// caret move into a live one) and must never move the tab focus, live or
    /// dormant.
    #[test]
    fn a_plain_horizontal_arrow_no_longer_switches_tabs() {
        for key in [KeyCode::Right, KeyCode::Left] {
            let mut app = test_app(default_bindings());
            let session_id = app.engine.sessions[0].id.clone();
            seed_input_tab(&mut app, &session_id, "tab-2", "claude", 1);
            app.center_mode = CenterMode::Agent;
            app.focus = FocusPane::Center;

            assert_eq!(
                app.focused_tab_id(&session_id),
                session_id,
                "the fixture must start on the session-slot tab or this proves nothing"
            );

            app.handle_key(KeyEvent::new(key, KeyModifiers::NONE))
                .expect("handle arrow");

            assert_eq!(
                app.focused_tab_id(&session_id),
                session_id,
                "{key:?} must stay on the same tab: the plain arrows belong to the agent now"
            );
        }
    }

    /// The Ctrl arrows are the tab keys.
    #[test]
    fn the_ctrl_arrows_still_switch_tabs() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        seed_input_tab(&mut app, &session_id, "tab-2", "claude", 1);
        app.center_mode = CenterMode::Agent;
        app.focus = FocusPane::Center;

        app.handle_key(KeyEvent::new(KeyCode::Right, KeyModifiers::CONTROL))
            .expect("handle ctrl-right");

        assert_eq!(
            app.focused_tab_id(&session_id),
            "tab-2",
            "Ctrl-Right must still switch tabs"
        );
    }

    /// The maximized agent renders no tab strip, so a frame drawn while it is
    /// up must leave no clickable tab rects behind. This is the RENDERER half
    /// of the defence (`render_overlay` clears the registry).
    #[test]
    fn maximized_agent_frame_leaves_no_clickable_tab_rects() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        seed_input_tab(&mut app, &session_id, "tab-2", "claude", 1);
        app.center_mode = CenterMode::Agent;

        let mut terminal = test_terminal();
        draw_frame(&mut app, &mut terminal);
        assert!(
            !app.agent_tab_regions.is_empty(),
            "the windowed frame must record tab rects or this test proves nothing"
        );

        app.fullscreen_overlay = FullscreenOverlay::Agent;
        draw_frame(&mut app, &mut terminal);

        assert!(
            app.agent_tab_regions.is_empty(),
            "a maximized frame draws no tabs, so it must leave no clickable tab rects behind"
        );
    }

    /// The INPUT half of the same defence: the `windowed` gate on the tab
    /// hit-test.
    ///
    /// The renderer clearing the registry is what makes this unreachable
    /// today, which is exactly why a test that lets the clear happen proves
    /// nothing about the gate: with the registry empty the hit-test returns
    /// `false` whatever the gate says, and the previous version of this test
    /// passed with `windowed &&` deleted. So the rects are deliberately put
    /// BACK after the maximized frame, standing in for "some future path
    /// reaches the tab hit-test" that the guard's own comment names.
    #[test]
    fn click_inside_maximized_agent_switches_no_tab() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        seed_input_tab(&mut app, &session_id, "tab-2", "claude", 1);
        app.center_mode = CenterMode::Agent;

        let mut terminal = test_terminal();
        // The WINDOWED frame is what records the clickable tab rects.
        draw_frame(&mut app, &mut terminal);
        let focused_before = app.focused_tab_id(&session_id);
        let stale_regions = app.agent_tab_regions.clone();
        let (other_tab, rect) = stale_regions
            .iter()
            .find(|(id, _)| *id != focused_before)
            .cloned()
            .expect("the windowed frame records a rect for the unfocused tab");

        app.fullscreen_overlay = FullscreenOverlay::Agent;
        draw_frame(&mut app, &mut terminal);
        // Put the stale geometry back, so the click really does reach the
        // hit-test and the `windowed` gate is the only thing standing in
        // front of it.
        app.agent_tab_regions = stale_regions;

        let term = app
            .mouse_layout
            .agent_term
            .expect("the maximized surface records its terminal area");
        let row = (rect.y..rect.y + rect.height)
            .find(|r| *r >= term.y && *r < term.y + term.height)
            .expect("the stale tab rect must overlap the maximized surface");
        let col = rect.x + rect.width / 2;
        assert!(
            col >= term.x && col < term.x + term.width,
            "the stale tab rect must overlap the maximized surface"
        );

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), col, row));

        assert_eq!(
            app.focused_tab_id(&session_id),
            focused_before,
            "clicking inside the maximized agent must not switch to {other_tab} through a stale tab rect"
        );
    }

    /// The click-outside dismiss must keep working: it is the only way out of
    /// the maximized surface with the mouse.
    #[test]
    fn click_outside_maximized_agent_still_minimizes() {
        let mut app = test_app(default_bindings());
        app.fullscreen_overlay = FullscreenOverlay::Agent;
        let mut terminal = test_terminal();
        draw_frame(&mut app, &mut terminal);

        let term = app
            .mouse_layout
            .agent_term
            .expect("the maximized surface records its terminal area");
        assert!(
            term.x > 0,
            "the maximized surface must leave a margin to click in"
        );

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), 0, term.y));

        assert_eq!(
            app.fullscreen_overlay,
            FullscreenOverlay::None,
            "a click outside the maximized agent still minimizes it"
        );
    }

    /// The maximized TERMINAL surface falls through the same arm, so it shares
    /// the invisible-divider bug.
    #[test]
    fn click_inside_maximized_terminal_starts_no_resize_drag() {
        let mut app = test_app(default_bindings());
        let mut terminal = test_terminal();
        draw_frame(&mut app, &mut terminal);
        let divider = app.mouse_layout.left.x + app.mouse_layout.left.width.saturating_sub(1);

        app.fullscreen_overlay = FullscreenOverlay::Terminal;
        draw_frame(&mut app, &mut terminal);

        let term = app
            .mouse_layout
            .agent_term
            .expect("the maximized terminal records its terminal area");
        let row = term.y + term.height / 2;

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), divider, row));

        assert!(
            app.mouse_drag.is_none(),
            "a click inside the maximized terminal must not grab an invisible pane divider"
        );
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Terminal);
    }

    /// The startup-log viewer handles its own mouse events and returns before
    /// the windowed arm, so it never had the bug. Pin that.
    #[test]
    fn click_inside_maximized_startup_log_starts_no_resize_drag() {
        let mut app = test_app(default_bindings());
        let mut terminal = test_terminal();
        draw_frame(&mut app, &mut terminal);
        let divider = app.mouse_layout.left.x + app.mouse_layout.left.width.saturating_sub(1);

        app.fullscreen_overlay = FullscreenOverlay::StartupLog;
        draw_frame(&mut app, &mut terminal);

        let term = app
            .mouse_layout
            .agent_term
            .expect("the maximized startup log records its body area");
        let row = term.y + term.height / 2;

        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), divider, row));

        assert!(
            app.mouse_drag.is_none(),
            "a click inside the maximized startup log must not grab an invisible pane divider"
        );
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::StartupLog);
    }

    /// The maximized-surface guard must not turn dux into a client that
    /// swallows the events the agent was meant to receive. With the child in
    /// the alt screen with mouse reporting on, a wheel tick over the MAXIMIZED
    /// agent is still forwarded to it as an SGR report. `cat -v` echoes what it
    /// receives, so the child's own grid is the proof.
    #[test]
    fn wheel_over_maximized_agent_still_forwards_to_the_child() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let args = vec![
            "-c".to_string(),
            "stty raw -echo; printf '\\033[?1049h\\033[?1000h'; exec cat -v".to_string(),
        ];
        let client = PtyClient::spawn("/bin/sh", &args, std::path::Path::new("."), 24, 80, 100)
            .expect("spawn pty");
        app.engine.providers.insert(session_id, client);
        app.session_surface = SessionSurface::Agent;

        // Poll until the child's own escape sequences have been parsed, rather
        // than guessing a sleep.
        let mut ready = false;
        for _ in 0..400 {
            let provider = app
                .selected_terminal_surface_client()
                .expect("provider for selected session");
            if provider.is_alt_screen() && provider.has_mouse_mode() {
                ready = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            ready,
            "the child never entered the alt screen with mouse reporting"
        );

        app.fullscreen_overlay = FullscreenOverlay::Agent;
        let mut terminal = test_terminal();
        draw_frame(&mut app, &mut terminal);
        let term = app
            .mouse_layout
            .agent_term
            .expect("the maximized surface records its terminal area");

        app.handle_mouse(mouse(MouseEventKind::ScrollUp, term.x + 5, term.y + 3));

        let mut echoed = false;
        for _ in 0..400 {
            let rendered: String = app
                .selected_terminal_surface_client()
                .expect("provider for selected session")
                .snapshot()
                .cells
                .iter()
                .map(|cell| cell.symbol.as_str())
                .collect();
            // `cat -v` renders ESC as `^[`, so the SGR wheel report reads
            // `^[[<64;col;rowM` once the child has it.
            if rendered.contains("[<64;") {
                echoed = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            echoed,
            "a wheel tick over the maximized agent must still reach the child as an SGR report"
        );
        assert_eq!(
            app.selected_terminal_surface_client()
                .expect("provider for selected session")
                .scrollback_offset(),
            0,
            "a forwarded wheel must not also scroll dux's own scrollback"
        );
    }

