    fn pinned_stored_pr(session_id: &str) -> dux_core::storage::StoredPr {
        dux_core::storage::StoredPr {
            session_id: session_id.to_string(),
            pr_number: 7,
            host: "github.com".to_string(),
            owner_repo: "o/r".to_string(),
            state: "OPEN".to_string(),
            title: "Pinned".to_string(),
            url: "https://github.com/o/r/pull/7".to_string(),
        }
    }

    #[test]
    fn command_palette_gates_the_pull_request_commands_on_gh_and_the_association() {
        let mut app = test_app(default_bindings());

        // gh unavailable: attach (which needs gh to resolve) is not offered.
        assert!(
            app.filtered_palette_commands("attach-pull-request")
                .is_empty()
        );
        // Detach is NOT gh-gated: it touches no network, and an association
        // must never outlive the ability to remove it. With no PR at all it
        // stays hidden; with a pin it appears even while gh is unavailable.
        assert!(
            app.filtered_palette_commands("detach-pull-request")
                .is_empty()
        );
        app.engine
            .pr_overrides
            .insert("session-1".to_string(), pinned_stored_pr("session-1"));
        assert!(
            !app.filtered_palette_commands("detach-pull-request")
                .is_empty(),
            "a pin must be removable without gh"
        );
        app.engine.pr_overrides.clear();

        // An AUTODETECTED badge is detachable too: it is the case the user
        // wants gone, and the old pin-only gate hid the command from them.
        app.engine.pr_statuses.insert(
            "session-1".to_string(),
            dux_core::model::PrInfo {
                number: 7,
                state: dux_core::model::PrState::Open,
                title: "Autodetected".to_string(),
                host: "github.com".to_string(),
                owner_repo: "o/r".to_string(),
                url: "https://github.com/o/r/pull/7".to_string(),
            },
        );
        assert!(
            !app.filtered_palette_commands("detach-pull-request")
                .is_empty(),
            "an autodetected association is detachable"
        );
        app.engine.pr_statuses.clear();

        // gh available, selected session has no PR at all: attach only.
        app.engine.github_integration_enabled = true;
        app.engine.gh_status = dux_core::model::GhStatus::Available;
        assert_eq!(
            app.selected_session().map(|s| s.id.clone()),
            Some("session-1".to_string()),
            "the fixture session must be selected for the detach gate to apply"
        );
        assert!(
            !app.filtered_palette_commands("attach-pull-request")
                .is_empty()
        );
        assert!(
            app.filtered_palette_commands("detach-pull-request")
                .is_empty(),
            "detach must not be offered while the selected agent has no PR"
        );

        // Pin the selected session: detach appears alongside attach.
        app.engine
            .pr_overrides
            .insert("session-1".to_string(), pinned_stored_pr("session-1"));
        assert!(
            !app.filtered_palette_commands("attach-pull-request")
                .is_empty()
        );
        assert!(
            !app.filtered_palette_commands("detach-pull-request")
                .is_empty()
        );
    }

    /// While an attach is resolving for the selected agent, the engine refuses
    /// every one of that agent's pull-request operations, so the palette stops
    /// offering them. A background PR check (`PrCheck`) is not the same thing
    /// and takes nothing away.
    #[test]
    fn command_palette_hides_the_pull_request_commands_while_an_attach_is_resolving() {
        let mut app = test_app(default_bindings());
        app.engine.github_integration_enabled = true;
        app.engine.gh_status = dux_core::model::GhStatus::Available;
        app.engine
            .pr_overrides
            .insert("session-1".to_string(), pinned_stored_pr("session-1"));
        app.engine.pr_suppressions.insert("session-1".to_string());
        for name in [
            "attach-pull-request",
            "detach-pull-request",
            "resume-pull-request-autodetection",
        ] {
            assert!(
                !app.filtered_palette_commands(name).is_empty(),
                "{name} is offered before the attach starts"
            );
        }

        app.engine
            .mark_in_flight(dux_core::engine::InFlightKey::PrAttach(
                "session-1".to_string(),
            ));
        for name in [
            "attach-pull-request",
            "detach-pull-request",
            "resume-pull-request-autodetection",
        ] {
            assert!(
                app.filtered_palette_commands(name).is_empty(),
                "{name} must be hidden while an attach is resolving for this agent"
            );
        }

        // Another agent's attach is not this agent's business.
        app.engine
            .clear_in_flight(&dux_core::engine::InFlightKey::PrAttach(
                "session-1".to_string(),
            ));
        app.engine
            .mark_in_flight(dux_core::engine::InFlightKey::PrAttach(
                "session-2".to_string(),
            ));
        // A background check for this very agent blocks nothing either.
        app.engine
            .mark_in_flight(dux_core::engine::InFlightKey::PrCheck(
                "session-1".to_string(),
            ));
        for name in [
            "attach-pull-request",
            "detach-pull-request",
            "resume-pull-request-autodetection",
        ] {
            assert!(
                !app.filtered_palette_commands(name).is_empty(),
                "{name} comes back once this agent's attach is done"
            );
        }
    }

    /// The way back is offered only where it means something: while the
    /// selected agent is actually detached. Like detach, it is not gh-gated.
    #[test]
    fn command_palette_offers_resume_only_while_the_selected_agent_is_detached() {
        let mut app = test_app(default_bindings());

        assert!(
            app.filtered_palette_commands("resume-pull-request-autodetection")
                .is_empty(),
            "nothing to resume on an agent nobody detached"
        );

        app.engine.pr_suppressions.insert("session-1".to_string());
        assert!(
            !app.filtered_palette_commands("resume-pull-request-autodetection")
                .is_empty(),
            "a detach must be undoable without gh"
        );

        // Scoped to the SELECTED agent: another agent's detach is not this
        // agent's way back.
        app.engine.pr_suppressions.clear();
        app.engine.pr_suppressions.insert("session-2".to_string());
        assert!(
            app.filtered_palette_commands("resume-pull-request-autodetection")
                .is_empty()
        );
    }

    #[test]
    fn attach_pull_request_confirm_closes_the_modal_and_mints_the_keyed_busy() {
        let mut app = test_app(default_bindings());
        app.engine.github_integration_enabled = true;
        app.engine.gh_status = dux_core::model::GhStatus::Available;

        app.execute_command("attach-pull-request".to_string())
            .expect("open the attach modal");
        assert!(
            matches!(app.prompt, PromptState::AttachPullRequestInput { .. }),
            "got {:?}",
            app.prompt
        );

        // An empty confirm is refused in place: error status, modal stays open.
        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Error);
        assert!(
            matches!(app.prompt, PromptState::AttachPullRequestInput { .. }),
            "an empty confirm must keep the modal open"
        );

        // Type a reference and confirm. The dispatch spawns a lookup worker
        // against the fixture repo (no remote, so it fails locally without gh);
        // its event stays in the channel, and every assertion here is on the
        // deterministic pre-drain state.
        for ch in ['#', '1', '2'] {
            app.handle_key(KeyEvent::new(KeyCode::Char(ch), KeyModifiers::NONE))
                .unwrap();
        }
        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();

        assert!(
            matches!(app.prompt, PromptState::None),
            "a non-empty confirm closes the modal"
        );
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Busy);
        assert_eq!(app.engine.pending_pr_attach_ops.len(), 1);
        let op_id = app
            .engine
            .pending_pr_attach_ops
            .keys()
            .next()
            .cloned()
            .expect("one pending op");
        let visible = app.status.most_recent().expect("a visible status");
        assert_eq!(
            visible.key.as_deref(),
            Some(op_id.as_str()),
            "the busy must be keyed by the op so the final can replace it"
        );
    }

    #[test]
    fn detach_pull_request_drops_the_pin_and_the_badge_and_resume_puts_it_back() {
        let mut app = test_app(default_bindings());
        // The override row has a foreign key on the session row, so the
        // fixture session must be persisted before the pin can be.
        let session = app.engine.sessions[0].clone();
        app.engine
            .session_store
            .upsert_session(&session)
            .expect("persist session");
        let stored = pinned_stored_pr("session-1");
        app.engine
            .session_store
            .upsert_pr_override(&stored)
            .expect("persist pin");
        app.engine
            .pr_overrides
            .insert("session-1".to_string(), stored);

        app.execute_command("detach-pull-request".to_string())
            .expect("detach");
        assert!(app.engine.pr_overrides.is_empty(), "the pin must be gone");
        assert!(
            app.engine
                .session_store
                .load_pr_overrides()
                .expect("load overrides")
                .is_empty(),
            "the stored pin row must be gone too"
        );
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Info);
        assert!(
            app.status.message().contains("Detached"),
            "got {:?}",
            app.status.message()
        );

        // The detach is recorded, so autodetection stays off for the agent.
        assert!(app.engine.pr_suppressions.contains("session-1"));

        // And the palette carries the way back out.
        app.execute_command("resume-pull-request-autodetection".to_string())
            .expect("resume");
        assert!(app.engine.pr_suppressions.is_empty());
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Info);
        assert!(
            app.status.message().contains("Resumed"),
            "got {:?}",
            app.status.message()
        );
    }

