    #[test]
    fn change_agent_provider_swaps_in_place_when_stopped() {
        let mut app = test_app(default_bindings());
        let original_session_id = app.engine.sessions[0].id.clone();
        let original_worktree = app.engine.sessions[0]
            .managed_worktree()
            .expect("managed test session")
            .to_string();
        app.engine.sessions[0].provider = ProviderKind::from_str("codex");
        app.engine.sessions[0].status = SessionStatus::Detached;
        app.engine
            .session_store
            .upsert_session(&app.engine.sessions[0])
            .expect("persist session");

        app.rebuild_left_items();
        app.selected_left = app
            .left_items()
            .iter()
            .position(|item| matches!(item, LeftItem::Session(index) if *index == 0))
            .expect("select the seeded session");

        app.open_change_agent_provider_prompt()
            .expect("open provider picker");
        match &mut app.prompt {
            PromptState::ChangeAgentProvider(prompt) => {
                prompt.selected = prompt
                    .options
                    .iter()
                    .position(|option| option.provider.as_str() == "opencode")
                    .expect("opencode option");
            }
            other => panic!("expected change-agent-provider prompt, got {other:?}"),
        }

        app.apply_change_agent_provider()
            .expect("apply provider swap");

        // Exactly one session still exists; its provider was mutated in place.
        assert_eq!(app.engine.sessions.len(), 1);
        assert_eq!(app.engine.sessions[0].id, original_session_id);
        assert_eq!(app.engine.sessions[0].provider.as_str(), "opencode");
        assert_eq!(
            app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
            original_worktree
        );
        assert!(matches!(app.prompt, PromptState::None));

        let persisted = app
            .engine
            .session_store
            .load_sessions()
            .expect("load sessions");
        assert_eq!(persisted.len(), 1);
        assert_eq!(persisted[0].provider.as_str(), "opencode");

        assert!(app.status.text().contains("will use opencode next launch"));
    }

    /// The warning says the user must exit the running agent and relaunch it.
    /// That stays owed until they do it, so it waits for them rather than for
    /// the warning window.
    #[test]
    fn change_agent_provider_warns_and_holds_the_line_when_agent_is_running() {
        let mut app = test_app(default_bindings());
        app.engine.sessions[0].provider = ProviderKind::from_str("codex");
        app.engine.sessions[0].status = SessionStatus::Active;
        let session_id = app.engine.sessions[0].id.clone();

        let worktree = std::path::Path::new(
            app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        let provider = PtyClient::spawn(
            "/bin/sh",
            &["-c".to_string(), "sleep 5".to_string()],
            worktree,
            24,
            80,
            1_000,
        )
        .expect("spawn test agent");
        app.engine.providers.insert(session_id.clone(), provider);

        app.rebuild_left_items();
        app.selected_left = app
            .left_items()
            .iter()
            .position(|item| matches!(item, LeftItem::Session(index) if *index == 0))
            .expect("select the running session");

        app.open_change_agent_provider_prompt()
            .expect("open provider picker");
        match &mut app.prompt {
            PromptState::ChangeAgentProvider(prompt) => {
                prompt.selected = prompt
                    .options
                    .iter()
                    .position(|option| option.provider.as_str() == "opencode")
                    .expect("opencode option");
            }
            other => panic!("expected change-agent-provider prompt, got {other:?}"),
        }

        app.apply_change_agent_provider()
            .expect("apply provider swap");

        // Provider is swapped now; the warning just tells the user the running
        // PTY hasn't caught up yet.
        assert_eq!(app.engine.sessions[0].provider.as_str(), "opencode");
        let persisted = app
            .engine
            .session_store
            .load_sessions()
            .expect("load sessions");
        assert_eq!(persisted[0].provider.as_str(), "opencode");
        assert!(
            app.engine.providers.contains_key(&session_id),
            "the old PTY keeps running until the user exits it"
        );
        assert_eq!(
            app.status.tone(),
            crate::statusline::StatusTone::Warning,
            "status should be a warning, not an error"
        );
        let message = app.status.message().to_string();
        assert!(
            message.contains("still running") && message.contains("opencode"),
            "status should explain the agent still runs the old provider, got: {message}"
        );
        assert!(matches!(app.prompt, PromptState::None));

        let window = std::time::Duration::from_secs(6);
        app.status.set_clear_after(window);
        let _ = app.status.tick(
            std::time::Instant::now() + window * 4,
            dux_core::statusline::BUSY_TIMEOUT,
        );
        assert!(
            app.status.message().contains("still running"),
            "the relaunch is still owed, so the warning waits for the user: {}",
            app.status.message()
        );

        // Clean up so the PTY doesn't outlive the test.
        app.engine.providers.remove(&session_id);
    }

    #[test]
    fn change_agent_provider_preserves_resume_for_previously_started_provider() {
        let mut app = test_app(default_bindings());
        app.engine.sessions[0].provider = ProviderKind::from_str("claude");
        app.engine.sessions[0].status = SessionStatus::Detached;
        app.engine.sessions[0].started_providers = vec!["codex".to_string(), "claude".to_string()];
        app.engine
            .session_store
            .upsert_session(&app.engine.sessions[0])
            .expect("persist session with history");

        app.rebuild_left_items();
        app.selected_left = app
            .left_items()
            .iter()
            .position(|item| matches!(item, LeftItem::Session(index) if *index == 0))
            .expect("select the seeded session");

        app.open_change_agent_provider_prompt()
            .expect("open provider picker");
        match &mut app.prompt {
            PromptState::ChangeAgentProvider(prompt) => {
                let codex_option = prompt
                    .options
                    .iter()
                    .find(|option| option.provider.as_str() == "codex")
                    .expect("codex option present");
                assert!(
                    codex_option.resume_available,
                    "codex was started earlier — picker should advertise resume"
                );
                prompt.selected = prompt
                    .options
                    .iter()
                    .position(|option| option.provider.as_str() == "codex")
                    .expect("codex option");
            }
            other => panic!("expected change-agent-provider prompt, got {other:?}"),
        }

        app.apply_change_agent_provider()
            .expect("swap back to codex");

        assert_eq!(app.engine.sessions[0].provider.as_str(), "codex");
        // should_resume_session uses started_providers + config's resume_args.
        let session = app.engine.sessions[0].clone();
        assert!(
            app.engine.should_resume_session(&session),
            "codex was launched on this worktree earlier, so resume must be active"
        );
        assert!(
            app.status.text().contains("resume its prior session"),
            "status should note resume is happening, got: {}",
            app.status.text()
        );
    }

    #[test]
    fn change_agent_provider_marks_providers_without_resume_support() {
        let mut app = test_app(default_bindings());
        app.engine.sessions[0].provider = ProviderKind::from_str("codex");
        app.engine.sessions[0].status = SessionStatus::Detached;
        // Pretend copilot was launched earlier — it still shouldn't advertise
        // resume because copilot's config has `resume_args: None`.
        app.engine.sessions[0].started_providers = vec!["copilot".to_string()];

        app.rebuild_left_items();
        app.selected_left = app
            .left_items()
            .iter()
            .position(|item| matches!(item, LeftItem::Session(index) if *index == 0))
            .expect("select the seeded session");

        app.open_change_agent_provider_prompt()
            .expect("open picker");
        match &app.prompt {
            PromptState::ChangeAgentProvider(prompt) => {
                let copilot = prompt
                    .options
                    .iter()
                    .find(|option| option.provider.as_str() == "copilot")
                    .expect("copilot option present");
                assert!(
                    !copilot.supports_resume,
                    "copilot is configured without resume_args, so supports_resume must be false"
                );
                assert!(
                    !copilot.resume_available,
                    "even with prior launches, copilot cannot resume"
                );

                let codex = prompt
                    .options
                    .iter()
                    .find(|option| option.provider.as_str() == "codex")
                    .expect("codex option present");
                assert!(
                    codex.supports_resume,
                    "codex supports resume via resume_args"
                );
            }
            other => panic!("expected change-agent-provider prompt, got {other:?}"),
        }
    }

