    fn viewport_contains(client: &crate::pty::PtyClient, needle: &str) -> bool {
        let snap = client.snapshot();
        let mut rows: Vec<String> = vec![String::new(); usize::from(snap.rows)];
        for cell in &snap.cells {
            if let Some(row) = rows.get_mut(usize::from(cell.row)) {
                row.push_str(&cell.symbol);
            }
        }
        rows.iter().any(|r| r.contains(needle))
    }

    /// Minimizing (Ctrl-g) while scrolled back must snap the PTY to the live
    /// edge. Scrolling back moves the display offset, and the terminal library
    /// holds that view still as new lines arrive, so an offset left behind on
    /// exit froze the minimized pane on stale content (the grid kept updating,
    /// but nothing new was VISIBLE until a later scroll walked the offset back
    /// to the bottom). Entering interactive mode already snaps to the live
    /// edge, so exiting must too.
    #[test]
    fn exit_interactive_while_scrolled_back_snaps_to_the_live_edge() {
        let mut app = test_app(default_bindings());
        let client = crate::pty::PtyClient::spawn(
            "sh",
            &["-c".to_string(), "cat".to_string()],
            std::path::Path::new("."),
            10,
            40,
            1000,
        )
        .expect("spawn pty");
        // Fill enough history that scrolling back 20 rows is possible.
        let mut fill = String::new();
        for i in 0..60 {
            fill.push_str(&format!("line {i}\n"));
        }
        client.write_bytes(fill.as_bytes()).expect("write fill");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
        while !viewport_contains(&client, "line 59") {
            assert!(std::time::Instant::now() < deadline, "fill never echoed");
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        app.engine.providers.insert("session-1".to_string(), client);
        app.focus = FocusPane::Center;
        app.center_mode = CenterMode::Agent;
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        // The user wheel-scrolled up to read history: the view stops tracking
        // the live edge.
        let provider = app.engine.providers.get("session-1").expect("provider");
        provider.set_scrollback(20);
        assert_eq!(provider.scrollback_offset(), 20, "scrolled back");

        app.exit_interactive_mode();

        let provider = app.engine.providers.get("session-1").expect("provider");
        assert_eq!(
            provider.scrollback_offset(),
            0,
            "exiting interactive mode must snap the PTY to the live edge"
        );
        // And the view must be tracking the live edge again, which is what
        // `viewport_contains` measures: it reads the offset-relative snapshot,
        // so it only sees the marker if the pane is showing the bottom.
        provider
            .write_bytes(b"marker-after-exit\n")
            .expect("write marker");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
        while !viewport_contains(
            app.engine.providers.get("session-1").expect("provider"),
            "marker-after-exit",
        ) {
            assert!(
                std::time::Instant::now() < deadline,
                "new PTY output never became visible in the minimized pane: \
                 the scrollback offset was left behind on exit"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    #[test]
    fn exit_interactive_from_terminal_overlay_resets_state() {
        let mut app = test_app(default_bindings());

        app.show_companion_terminal()
            .expect("launch companion terminal");

        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Terminal);
        assert_eq!(app.input_target, InputTarget::Terminal);

        // Simulate the fullscreen toggle via the raw input path: feed Ctrl-g
        // (0x07) into the raw input buffer and process sequences.
        app.raw_input_buf = vec![0x07];
        let (sequences, _) = crate::raw_input::split_sequences(&app.raw_input_buf);
        assert_eq!(sequences.len(), 1);
        let matched = app.interactive_patterns.match_sequence(sequences[0]);
        assert_eq!(matched, Some((Action::ToggleFullscreen, false)));

        // Apply the same state change that poll_and_forward_raw_input does.
        let return_to_list =
            matches!(app.input_target, InputTarget::Terminal) && app.terminal_return_to_list;
        app.input_target = InputTarget::None;
        app.fullscreen_overlay = FullscreenOverlay::None;
        app.session_surface = SessionSurface::Agent;
        app.raw_input_buf.clear();
        if return_to_list {
            app.left_section = LeftSection::Terminals;
            app.focus = FocusPane::Left;
        }

        // Launched via `t` → returns to terminals list on the left pane.
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::None);
        assert_eq!(app.session_surface, SessionSurface::Agent);
        assert_eq!(app.input_target, InputTarget::None);
        assert_eq!(app.left_section, LeftSection::Terminals);
        assert_eq!(app.focus, FocusPane::Left);
    }

