    #[test]
    fn resume_fallback_retries_with_fresh_session_on_quick_exit() {
        let mut app = test_app(default_bindings());
        // Override the "codex" provider to use /bin/sh so the fallback spawn
        // works on CI where codex is not installed.
        app.engine.config.providers.commands.insert(
            "codex".to_string(),
            crate::config::ProviderCommandConfig {
                command: "/bin/sh".to_string(),
                ..Default::default()
            },
        );
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::Path::new(
            app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        // Spawn a process that exits immediately without producing output.
        let args = vec!["-c".to_string(), "exit 1".to_string()];
        let client =
            PtyClient::spawn("/bin/sh", &args, worktree, 24, 80, 1_000).expect("spawn quick-exit");
        app.engine.providers.insert(session_id.clone(), client);
        app.engine
            .mark_session_status(&session_id, SessionStatus::Active);
        app.engine
            .resume_fallback_candidates
            .insert(session_id.clone(), std::time::Instant::now());
        app.selected_left = 1;
        app.session_surface = SessionSurface::Agent;

        // Wait for the process to exit.
        std::thread::sleep(std::time::Duration::from_millis(200));
        drain_until(&mut app, |app| {
            app.engine.providers.contains_key(&session_id)
                && !app
                    .engine
                    .is_in_flight(&InFlightKey::AgentLaunch(session_id.clone()))
                && app.status.text().contains("No prior session to resume")
        });

        // The fallback should have spawned a fresh session, so the provider
        // is still present and the session is active (not detached).
        assert!(
            app.engine.providers.contains_key(&session_id),
            "provider should still be present after fallback retry"
        );
        assert_eq!(app.engine.sessions[0].status, SessionStatus::Active);
        // The engine-initiated fallback relaunch is never
        // fullscreen-seeking, so it lands focused-but-minimized.
        assert_eq!(app.input_target, InputTarget::None);
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::None);
        assert_eq!(app.focus, FocusPane::Center);
        assert!(
            !app.engine
                .resume_fallback_candidates
                .contains_key(&session_id),
            "candidate should have been removed after fallback"
        );
        assert!(
            app.status.text().contains("No prior session to resume"),
            "status should inform user about fallback: {:?}",
            app.status.text()
        );
    }

    #[test]
    fn resume_fallback_skipped_when_pty_had_substantial_output() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::Path::new(
            app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        // Spawn a process that produces many lines of output before exiting.
        // This simulates a real agent session that ran and then exited normally.
        let args = vec!["-c".to_string(), "seq 1 30".to_string()];
        let client =
            PtyClient::spawn("/bin/sh", &args, worktree, 24, 80, 1_000).expect("spawn with output");
        app.engine.providers.insert(session_id.clone(), client);
        app.engine
            .mark_session_status(&session_id, SessionStatus::Active);
        app.engine
            .resume_fallback_candidates
            .insert(session_id.clone(), std::time::Instant::now());
        app.selected_left = 1;
        app.session_surface = SessionSurface::Agent;

        // Wait for the process to produce output and exit.
        std::thread::sleep(std::time::Duration::from_millis(200));
        drain_until(&mut app, |app| {
            app.engine.sessions[0].status == SessionStatus::Detached
        });

        // Since the PTY had substantial output (>5 lines), the fallback
        // should NOT have triggered. The session should be detached.
        assert_eq!(app.engine.sessions[0].status, SessionStatus::Detached);
        assert!(
            !app.engine
                .resume_fallback_candidates
                .contains_key(&session_id),
            "candidate should have been removed even when skipped"
        );
    }

    #[test]
    fn resume_fallback_triggers_on_one_liner_output() {
        let mut app = test_app(default_bindings());
        // Override the "codex" provider to use /bin/sh so the fallback spawn
        // works on CI where codex is not installed.
        app.engine.config.providers.commands.insert(
            "codex".to_string(),
            crate::config::ProviderCommandConfig {
                command: "/bin/sh".to_string(),
                ..Default::default()
            },
        );
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::Path::new(
            app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        // Spawn a process that prints a single line (like a failed --continue)
        // and then exits. The fallback should still trigger because the output
        // is minimal (≤5 lines with no scrollback).
        let args = vec![
            "-c".to_string(),
            "echo 'No session found to resume'".to_string(),
        ];
        let client =
            PtyClient::spawn("/bin/sh", &args, worktree, 24, 80, 1_000).expect("spawn one-liner");
        app.engine.providers.insert(session_id.clone(), client);
        app.engine
            .mark_session_status(&session_id, SessionStatus::Active);
        app.engine
            .resume_fallback_candidates
            .insert(session_id.clone(), std::time::Instant::now());
        app.selected_left = 1;
        app.session_surface = SessionSurface::Agent;

        // Wait for the process to produce its one line and exit.
        std::thread::sleep(std::time::Duration::from_millis(200));
        drain_until(&mut app, |app| {
            app.engine.providers.contains_key(&session_id)
                && !app
                    .engine
                    .is_in_flight(&InFlightKey::AgentLaunch(session_id.clone()))
                && app.status.text().contains("No prior session to resume")
        });

        // Despite having output, the fallback should trigger because the
        // output is minimal (one line, no scrollback).
        assert!(
            app.engine.providers.contains_key(&session_id),
            "provider should still be present after fallback retry"
        );
        assert_eq!(app.engine.sessions[0].status, SessionStatus::Active);
        assert!(
            app.status.text().contains("No prior session to resume"),
            "status should inform user about fallback: {:?}",
            app.status.text()
        );
    }

    #[test]
    fn no_fallback_for_non_candidate_sessions() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::Path::new(
            app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        // Spawn a process that exits immediately, but do NOT add it as a candidate.
        let args = vec!["-c".to_string(), "exit 1".to_string()];
        let client =
            PtyClient::spawn("/bin/sh", &args, worktree, 24, 80, 1_000).expect("spawn quick-exit");
        app.engine.providers.insert(session_id.clone(), client);
        app.engine
            .mark_session_status(&session_id, SessionStatus::Active);
        // Deliberately not adding to resume_fallback_candidates.
        app.selected_left = 1;
        app.session_surface = SessionSurface::Agent;

        std::thread::sleep(std::time::Duration::from_millis(200));
        drain_until(&mut app, |app| {
            !app.engine.providers.contains_key(&session_id)
        });

        // Without being a candidate, the session should just go to detached.
        assert!(
            !app.engine.providers.contains_key(&session_id),
            "provider should have been removed"
        );
        assert_eq!(app.engine.sessions[0].status, SessionStatus::Detached);
    }

