    // ---------------------------------------------------------------
    // Bracket paste and input batching tests
    // ---------------------------------------------------------------

    /// Fullscreen raw-path fixture: the same live `cat -v` child as
    /// `typeable_app_with_paste_child`, flipped into fullscreen interactive
    /// mode so bytes travel through `process_raw_input_bytes`.
    fn fullscreen_app_with_paste_child(decsets: &str) -> crate::app::App {
        let mut app = typeable_app_with_paste_child(decsets);
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;
        app
    }

    /// A raw-path (fullscreen) paste to a child that enabled DECSET 2004 is
    /// forwarded wrapped and verbatim: markers intact, LF endings untouched.
    #[test]
    fn raw_path_paste_to_a_2004_child_forwards_the_wrapped_paste_verbatim() {
        let mut app = fullscreen_app_with_paste_child("\\033[?2004h");
        let mut ready = false;
        for _ in 0..400 {
            if app
                .selected_terminal_surface_client()
                .is_some_and(|p| p.has_bracketed_paste())
            {
                ready = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(ready, "the child never enabled bracketed paste");

        let mut input = Vec::new();
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_START);
        input.extend_from_slice(b"hi\nyou");
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_END);
        app.process_raw_input_bytes(&input).unwrap();

        // `cat -v` renders ESC as `^[` and CR as `^M`; the LF stays a real
        // line feed, so the body must arrive with no `^M` in it.
        let rendered = wait_for_paste_echo(&app, "you^[[201~");
        assert!(
            rendered.contains("[200~hi"),
            "the open marker must precede the verbatim body; got {rendered:?}"
        );
        assert!(
            !rendered.contains("hi^M"),
            "a 2004 child's paste keeps its LF endings; got {rendered:?}"
        );
    }

    /// A raw-path paste to a child WITHOUT DECSET 2004 arrives unwrapped
    /// (no literal markers typed at it) with LF endings normalized to CR,
    /// mirroring the windowed `paste_to_center_pty` semantics.
    #[test]
    fn raw_path_paste_to_a_non_2004_child_is_unwrapped_with_cr_endings() {
        let mut app = fullscreen_app_with_paste_child("");

        let mut input = Vec::new();
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_START);
        input.extend_from_slice(b"a\nb");
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_END);
        app.process_raw_input_bytes(&input).unwrap();

        let rendered = wait_for_paste_echo(&app, "a^Mb");
        assert!(
            !rendered.contains("[200~") && !rendered.contains("[201~"),
            "a non-2004 child must never see the literal markers; got {rendered:?}"
        );
    }

    /// A CR-LF pair inside the paste collapses to ONE carriage return, even
    /// when the pair is split across two stdin reads.
    #[test]
    fn raw_path_paste_crlf_split_across_reads_collapses_to_one_cr() {
        let mut app = fullscreen_app_with_paste_child("");

        let mut first = Vec::new();
        first.extend_from_slice(crate::raw_input::BRACKET_PASTE_START);
        first.extend_from_slice(b"x\r");
        app.process_raw_input_bytes(&first).unwrap();

        let mut second = Vec::new();
        second.extend_from_slice(b"\ny");
        second.extend_from_slice(crate::raw_input::BRACKET_PASTE_END);
        app.process_raw_input_bytes(&second).unwrap();

        let rendered = wait_for_paste_echo(&app, "x^My");
        assert!(
            !rendered.contains("x^M^My"),
            "CR-LF must not double into CR-CR; got {rendered:?}"
        );
    }

    #[test]
    fn bracket_paste_skips_intercept_matching() {
        // Ctrl-g (0x07) normally triggers ToggleFullscreen. Inside a
        // bracket paste it should be forwarded, not intercepted.
        // (The `cat` child never enables DECSET 2004, so on this path the
        // markers are stripped and only the body is forwarded; the byte
        // under test is the body.)
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        // Spawn a real PTY so write_bytes has somewhere to go.
        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "cat; sleep 0.5".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );
        // Wait for the shell to produce output so has_output() is true.
        std::thread::sleep(std::time::Duration::from_millis(100));

        // Build input: ESC[200~ + Ctrl-g + ESC[201~
        let mut input = Vec::new();
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_START);
        input.push(0x07); // Ctrl-g — would be ToggleFullscreen outside paste
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_END);

        let result = app.process_raw_input_bytes(&input).unwrap();
        assert!(!result, "should not request exit");

        // The key assertion: we should still be in interactive mode.
        // If the Ctrl-g was intercepted, input_target would be None.
        assert_eq!(
            app.input_target,
            InputTarget::Agent,
            "Ctrl-g inside bracket paste must not exit interactive mode"
        );
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Agent);
    }

    #[test]
    fn raw_focus_sequences_update_focus_state_and_are_not_forwarded() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "cat; sleep 0.5".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );
        std::thread::sleep(std::time::Duration::from_millis(100));

        let grace = std::time::Duration::from_secs(3);

        // Focus-out: the terminal window is unfocused, so viewing must stop.
        app.process_raw_input_bytes(b"\x1b[O").unwrap();
        assert!(
            !app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), grace),
            "a focus-out report must flip the state to unfocused"
        );

        // Focus-in: a genuine unfocused->focused transition. With zero grace
        // (passed to should_stamp_viewed below) stamping resumes immediately.
        app.process_raw_input_bytes(b"\x1b[I").unwrap();
        assert!(
            app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::ZERO),
            "a focus-in report must flip the state back to focused"
        );

        // Neither report may reach the child PTY: nothing was forwarded, so the
        // per-tab pty-input bookkeeping stays empty.
        assert!(
            app.engine.pty_input.is_empty(),
            "focus reports must never be forwarded to the child PTY"
        );
    }

    #[test]
    fn raw_focus_gained_on_fresh_app_confirms_fail_open_with_no_grace() {
        // A fresh App has never seen a focus event, so it fails open (assumes
        // focused). The very first raw focus report being a focus-in simply
        // confirms that assumption; it must not start a grace window, so
        // stamping is immediate under any grace, including a nonzero one.
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "cat; sleep 0.5".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );
        std::thread::sleep(std::time::Duration::from_millis(100));

        app.process_raw_input_bytes(b"\x1b[I").unwrap();
        assert!(
            app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::from_secs(3)),
            "the first-ever focus-in report must not start a grace window"
        );
    }

    #[test]
    fn raw_focus_bytes_inside_bracketed_paste_are_forwarded_verbatim() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "cat; sleep 0.5".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );
        std::thread::sleep(std::time::Duration::from_millis(100));

        // Paste-start + a literal ESC[I + paste-end: the ESC[I is pasted user
        // data, not a host focus report, so it must forward and must NOT touch
        // the focus state.
        let mut input = Vec::new();
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_START);
        input.extend_from_slice(b"\x1b[I");
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_END);
        app.process_raw_input_bytes(&input).unwrap();

        // Focus state untouched: still fail-open (stamps under any grace).
        assert!(
            app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::from_secs(3)),
            "a focus sequence inside a bracketed paste must not change focus state"
        );
        // The paste content reached the PTY.
        assert!(
            !app.engine.pty_input.is_empty(),
            "bracketed-paste content, including literal ESC[I, must forward to the PTY"
        );
    }

    #[test]
    fn focus_event_during_loading_phase_updates_state() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        // Mirror the existing loading-phase tests: bytes suppressed from
        // forwarding are fed through the shared raw_input_parser (the same
        // parser instance the interactive path uses), then scanned.
        let sequences = app.raw_input_parser.feed_sequences(b"\x1b[O");

        app.scan_loading_phase_focus(&sequences);

        assert!(
            !app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::from_secs(3)),
            "a focus-out arriving during loading must still be observed"
        );
        assert!(
            app.engine.pty_input.is_empty(),
            "loading-phase focus scanning forwards nothing"
        );
    }

    #[test]
    fn loading_phase_focus_scan_applies_bare_focus_gained() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.terminal_focus.on_focus_lost();

        // A bare focus-in report (not inside a bracketed paste) must still be
        // observed during the loading phase.
        let sequences = app.raw_input_parser.feed_sequences(b"\x1b[I");
        app.scan_loading_phase_focus(&sequences);

        assert!(
            app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::ZERO),
            "a bare focus-in report during loading must resume stamping"
        );
    }

    #[test]
    fn loading_phase_fragmented_focus_report_completes_pending_esc() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.terminal_focus.on_focus_lost();

        assert!(!app.scan_loading_phase(b"\x1b"));
        assert_eq!(app.raw_input_buf, b"\x1b");
        assert!(!app.scan_loading_phase(b"[I"));

        assert!(app.raw_input_buf.is_empty());
        assert!(
            app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::ZERO)
        );
    }

    #[test]
    fn loading_phase_focus_scan_exempts_bracketed_paste_content() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.terminal_focus.on_focus_lost();

        // A paste whose content contains a literal ESC[I must not be
        // reinterpreted as a real focus report during the loading phase,
        // mirroring the interactive path's bracket-paste exemption.
        let mut input = Vec::new();
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_START);
        input.extend_from_slice(b"\x1b[I");
        input.extend_from_slice(crate::raw_input::BRACKET_PASTE_END);

        let sequences = app.raw_input_parser.feed_sequences(&input);
        app.scan_loading_phase_focus(&sequences);

        assert!(
            !app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::from_secs(3)),
            "a literal ESC[I inside a loading-phase paste must not resume focus stamping"
        );
    }

    #[test]
    fn loading_phase_scan_observes_focus_before_exit_early_return() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;
        app.session_surface = SessionSurface::Agent;
        app.terminal_focus.on_focus_lost();

        // A single read bundles a focus-in report together with the
        // ToggleFullscreen trigger (Ctrl-g). The exit scan returns early on a
        // match; the bundled focus report must still be observed rather than
        // dropped by that early return.
        let mut input = Vec::new();
        input.extend_from_slice(b"\x1b[I");
        input.push(0x07);

        // Mirror poll_and_forward_raw_input's own bookkeeping: it appends
        // newly-read bytes into loading_input_buf (which scan_loading_phase_exit
        // reads from) before calling scan_loading_phase.
        app.loading_input_buf = input.clone();

        let exited = app.scan_loading_phase(&input);

        assert!(
            exited,
            "the ToggleFullscreen trigger in the bundled read must still fire"
        );
        assert!(
            app.terminal_focus
                .should_stamp_viewed(std::time::Instant::now(), std::time::Duration::ZERO),
            "a focus-in report bundled with an exit trigger in the same read must not be dropped"
        );
    }

    #[test]
    fn bracket_paste_state_tracks_across_calls() {
        // If the paste start marker arrives in one read and the end
        // marker in the next, in_bracket_paste must persist.
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;

        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "cat; sleep 0.5".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );
        std::thread::sleep(std::time::Duration::from_millis(100));

        // First chunk: start marker + some text.
        let mut chunk1 = Vec::new();
        chunk1.extend_from_slice(crate::raw_input::BRACKET_PASTE_START);
        chunk1.extend_from_slice(b"abc");
        app.process_raw_input_bytes(&chunk1).unwrap();
        assert!(
            app.in_bracket_paste,
            "should be in bracket paste after start marker"
        );

        // Second chunk: more text + end marker.
        let mut chunk2 = Vec::new();
        chunk2.extend_from_slice(b"def");
        chunk2.extend_from_slice(crate::raw_input::BRACKET_PASTE_END);
        app.process_raw_input_bytes(&chunk2).unwrap();
        assert!(
            !app.in_bracket_paste,
            "should exit bracket paste after end marker"
        );
    }

    #[test]
    fn bracket_paste_state_reset_on_exit_interactive() {
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        app.engine.providers.insert(
            "session-1".to_string(),
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "cat; sleep 0.5".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );
        std::thread::sleep(std::time::Duration::from_millis(100));

        // Enter bracket paste state.
        app.in_bracket_paste = true;

        // Now send ToggleFullscreen (Ctrl-g) outside of paste context.
        // Reset in_bracket_paste first to simulate that the end marker
        // was never received (e.g. malformed paste), but we exit.
        app.in_bracket_paste = false;
        app.process_raw_input_bytes(b"\x07").unwrap();

        assert!(!app.in_bracket_paste, "should be reset after exit");
        assert_eq!(app.input_target, InputTarget::None);
    }

    #[test]
    fn forward_batching_sends_all_bytes() {
        // Verify that multiple plain characters are forwarded to the PTY
        // (they should be batched into a single write, but we can at
        // least verify the bytes arrive by reading them back).
        let mut app = test_app(default_bindings());
        app.input_target = InputTarget::Agent;

        let client = PtyClient::spawn(
            "sh",
            &["-c".to_string(), "cat; sleep 0.5".to_string()],
            std::path::Path::new("."),
            10,
            10,
            100,
        )
        .expect("spawn pty");
        app.engine.providers.insert("session-1".to_string(), client);
        std::thread::sleep(std::time::Duration::from_millis(100));

        // Feed 100 'x' characters — they should all be forwarded.
        let input = vec![b'x'; 100];
        let result = app.process_raw_input_bytes(&input).unwrap();
        assert!(!result);
        // We should still be in interactive mode (nothing intercepted).
        assert_eq!(app.input_target, InputTarget::Agent);
        // The raw_input_buf should be empty (no remainder).
        assert!(app.raw_input_buf.is_empty());
    }

    fn app_with_two_macros() -> App {
        let mut app = test_app(default_bindings());
        app.engine.config.macros.entries.insert(
            "greet".to_string(),
            crate::config::MacroEntry {
                text: "hello".to_string(),
                surface: crate::config::MacroSurface::Agent,
            },
        );
        app.engine.config.macros.entries.insert(
            "farewell".to_string(),
            crate::config::MacroEntry {
                text: "goodbye".to_string(),
                surface: crate::config::MacroSurface::Agent,
            },
        );
        app.open_edit_macros();
        app
    }

    // ══════════════════════════════════════════════════════════════════════
    // Change A: the macro LIST is a Picker, so it must behave like one
    //
    // Its keys were hardcoded (`Esc`, `j`/`k`, `Enter`, `n`, `d`) instead of
    // resolved through the bindings, and it published no click targets at all
    // (`render_edit_macros` claimed `OverlayMouseLayout::None`), so its rows
    // were the only picker rows in dux a mouse could not reach.
    // ══════════════════════════════════════════════════════════════════════

    fn app_with_two_macros_bound(bindings: RuntimeBindings) -> App {
        let mut app = test_app(bindings);
        app.engine.config.macros.entries.insert(
            "greet".to_string(),
            crate::config::MacroEntry {
                text: "hello".to_string(),
                surface: crate::config::MacroSurface::Agent,
            },
        );
        app.engine.config.macros.entries.insert(
            "farewell".to_string(),
            crate::config::MacroEntry {
                text: "goodbye".to_string(),
                surface: crate::config::MacroSurface::Agent,
            },
        );
        app.open_edit_macros();
        app
    }

    fn macro_list_selected(app: &App) -> usize {
        match &app.prompt {
            PromptState::EditMacros { selected, .. } => *selected,
            other => panic!("expected the macro list, got {other:?}"),
        }
    }

    #[test]
    fn macro_list_moves_its_selection_with_the_bound_movement_key() {
        let mut app = app_with_two_macros_bound(bindings_with_overrides(&[
            (Action::MoveDown, &["ctrl-n"]),
            (Action::MoveUp, &["ctrl-e"]),
        ]));
        assert_eq!(macro_list_selected(&app), 0);
        app.handle_key(KeyEvent::new(KeyCode::Char('n'), KeyModifiers::CONTROL))
            .expect("handle rebound move-down");
        assert_eq!(
            macro_list_selected(&app),
            1,
            "the macro list must resolve movement through the bindings, not hardcode j/Down"
        );
        app.handle_key(KeyEvent::new(KeyCode::Char('e'), KeyModifiers::CONTROL))
            .expect("handle rebound move-up");
        assert_eq!(macro_list_selected(&app), 0);
    }

    #[test]
    fn macro_list_closes_and_confirms_through_the_bindings() {
        let mut app = app_with_two_macros_bound(bindings_with_overrides(&[
            (Action::Confirm, &["ctrl-y"]),
            (Action::CloseOverlay, &["ctrl-q"]),
        ]));
        app.handle_key(KeyEvent::new(KeyCode::Char('y'), KeyModifiers::CONTROL))
            .expect("handle rebound confirm");
        assert!(
            matches!(
                app.prompt,
                PromptState::EditMacros {
                    editing: Some(_),
                    ..
                }
            ),
            "the rebound confirm key must open the selected macro for editing"
        );

        let mut app = app_with_two_macros_bound(bindings_with_overrides(&[(
            Action::CloseOverlay,
            &["ctrl-q"],
        )]));
        app.handle_key(KeyEvent::new(KeyCode::Char('q'), KeyModifiers::CONTROL))
            .expect("handle rebound close");
        assert!(
            matches!(app.prompt, PromptState::None),
            "the rebound close key must close the macro list"
        );
    }

    #[test]
    fn macro_list_new_and_delete_are_bindings_not_hardcoded_letters() {
        let mut app =
            app_with_two_macros_bound(bindings_with_overrides(&[(Action::NewMacro, &["ctrl-t"])]));
        app.handle_key(KeyEvent::new(KeyCode::Char('t'), KeyModifiers::CONTROL))
            .expect("handle rebound new-macro");
        assert!(
            matches!(
                app.prompt,
                PromptState::EditMacros {
                    editing: Some(ref state),
                    ..
                } if state.id.is_none()
            ),
            "the rebound new-macro key must open a blank editor"
        );

        let mut app = app_with_two_macros_bound(bindings_with_overrides(&[(
            Action::DeleteMacro,
            &["ctrl-x"],
        )]));
        app.handle_key(KeyEvent::new(KeyCode::Char('x'), KeyModifiers::CONTROL))
            .expect("handle rebound delete-macro");
        assert_eq!(
            pending_delete_state(&app).map(|(name, _)| name),
            Some("greet")
        );
    }

    #[test]
    fn macro_list_rows_are_clickable() {
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;
        let mut app = app_with_two_macros_bound(default_bindings());
        let backend = TestBackend::new(120, 40);
        let mut terminal = Terminal::new(backend).expect("terminal");
        terminal.draw(|frame| app.render(frame)).expect("render");

        let OverlayMouseLayout::EditMacroList { list, .. } = app.overlay_layout.active else {
            panic!(
                "the macro list must publish its rows, got {:?}",
                app.overlay_layout.active
            );
        };
        // Coordinates come from the published rect, never from a string offset.
        let second_row = MouseEvent {
            kind: MouseEventKind::Down(MouseButton::Left),
            column: list.x + 2,
            row: list.y + 1,
            modifiers: KeyModifiers::NONE,
        };
        app.handle_mouse(second_row);
        assert_eq!(
            macro_list_selected(&app),
            1,
            "clicking a macro row must select it"
        );
    }

    fn pending_delete_state(app: &App) -> Option<(&str, bool)> {
        if let PromptState::EditMacros {
            pending_delete: Some(pending),
            ..
        } = &app.prompt
        {
            Some((pending.name.as_str(), pending.focus.is_confirm()))
        } else {
            None
        }
    }

    #[test]
    fn macro_delete_key_stages_confirmation_without_mutating_config() {
        let mut app = app_with_two_macros();

        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");

        assert_eq!(pending_delete_state(&app), Some(("greet", false)));
        assert_eq!(
            app.engine.config.macros.entries.len(),
            2,
            "macro must not be removed from config until confirmed"
        );
        assert!(app.engine.config.macros.entries.contains_key("greet"));
    }

    #[test]
    fn macro_delete_esc_clears_pending_without_deleting() {
        let mut app = app_with_two_macros();
        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");
        assert!(pending_delete_state(&app).is_some());

        app.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
            .expect("handle esc");

        assert!(pending_delete_state(&app).is_none());
        assert!(
            matches!(app.prompt, PromptState::EditMacros { .. }),
            "macro editor should remain open after dismissing the confirm dialog"
        );
        assert_eq!(app.engine.config.macros.entries.len(), 2);
    }

    #[test]
    fn macro_delete_tab_toggles_confirm_button_focus() {
        let mut app = app_with_two_macros();
        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");
        assert_eq!(pending_delete_state(&app), Some(("greet", false)));

        app.handle_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
            .expect("handle tab");
        assert_eq!(pending_delete_state(&app), Some(("greet", true)));

        app.handle_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
            .expect("handle tab");
        assert_eq!(pending_delete_state(&app), Some(("greet", false)));
    }

    #[test]
    fn macro_delete_enter_on_cancel_is_noop() {
        let mut app = app_with_two_macros();
        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");

        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .expect("handle enter");

        assert!(pending_delete_state(&app).is_none());
        assert_eq!(app.engine.config.macros.entries.len(), 2);
        assert!(app.engine.config.macros.entries.contains_key("greet"));
    }

    #[test]
    fn macro_delete_enter_on_delete_removes_and_persists() {
        let mut app = app_with_two_macros();
        let config_path = app.engine.paths.config_path.clone();
        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");
        app.handle_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
            .expect("handle tab");

        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .expect("handle enter");

        assert!(pending_delete_state(&app).is_none());
        assert!(
            !app.engine.config.macros.entries.contains_key("greet"),
            "macro should be removed from in-memory config"
        );
        assert_eq!(app.engine.config.macros.entries.len(), 1);

        if let PromptState::EditMacros { entries, .. } = &app.prompt {
            assert!(
                entries.iter().all(|(n, _, _)| n != "greet"),
                "EditMacros snapshot should reflect the deletion"
            );
        } else {
            panic!("expected EditMacros prompt after resolving delete");
        }

        assert!(
            config_path.exists(),
            "config file should have been written to disk"
        );
        let disk = std::fs::read_to_string(&config_path).expect("read config");
        assert!(
            !disk.contains("greet"),
            "deleted macro should not appear in saved config"
        );
    }

    #[test]
    fn macro_delete_surfaces_save_failure_on_status_line() {
        let mut app = app_with_two_macros();
        // Point the config writer at a nonexistent path so save_eager fails.
        // (Changing paths.config_path alone does not affect save_eager because
        // the queue was already initialised with the original path; we must
        // replace the writer itself.)
        app.engine.config_writer =
            dux_core::config_queue::ConfigWriteQueue::new("/nonexistent/dir/cfg.toml".into());

        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");
        app.handle_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
            .expect("handle tab");
        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .expect("handle enter");

        assert_eq!(
            app.status.tone(),
            crate::statusline::StatusTone::Error,
            "save failure should produce an error-toned status message"
        );
        let msg = app.status.message();
        assert!(
            msg.contains("greet"),
            "status message should name the affected macro, got: {msg}"
        );
        assert!(
            msg.to_lowercase().contains("config"),
            "status message should mention config, got: {msg}"
        );
    }

    #[test]
    fn macro_delete_space_activates_focused_button() {
        let mut app = app_with_two_macros();
        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");

        // Space on Cancel (default focus) should cancel without deleting.
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .expect("handle space");
        assert!(pending_delete_state(&app).is_none());
        assert_eq!(app.engine.config.macros.entries.len(), 2);

        // Now re-open and focus Delete, then Space should remove.
        app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE))
            .expect("handle d");
        app.handle_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
            .expect("handle tab");
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .expect("handle space");

        assert!(pending_delete_state(&app).is_none());
        assert!(!app.engine.config.macros.entries.contains_key("greet"));
    }

    /// Helper: type printable characters one by one into the active prompt.
    fn type_chars(app: &mut App, s: &str) {
        for c in s.chars() {
            app.handle_key(KeyEvent::new(KeyCode::Char(c), KeyModifiers::NONE))
                .expect("type char");
        }
    }

    /// Open the macro editor on the selected macro and put the body under the
    /// cursor, ready to type into.
    ///
    /// The ONE model-specific step the macro tests share, so the tests
    /// themselves read the same before and after the focus rework.
    fn open_macro_editor_on_body(app: &mut App) {
        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .expect("open the editor on the selected macro");
        app.handle_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
            .expect("move focus to the body");
        let engage = app
            .bindings
            .first_key_reaching(Action::EngageCommitInput, |_| true)
            .expect("an engage binding");
        app.handle_key(press(engage)).expect("engage the body");
    }

    /// The text stored in config for a macro, or `None` when it is absent.
    fn macro_text(app: &App, name: &str) -> Option<String> {
        app.engine
            .config
            .macros
            .entries
            .get(name)
            .map(|entry| entry.text.clone())
    }

    #[test]
    fn macro_edit_escape_from_the_body_cancels_and_leaves_config_untouched() {
        // The whole point of the rework: Escape must ABANDON the edit, exactly
        // like every other text surface in dux. It used to SAVE from the body,
        // which left no way to back out of a change.
        let mut app = app_with_two_macros();
        open_macro_editor_on_body(&mut app);
        type_chars(&mut app, "!");

        // First Escape leaves the body's edit mode; the second cancels the edit.
        app.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
            .expect("first esc");
        app.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
            .expect("second esc");

        assert_eq!(
            macro_text(&app, "greet").as_deref(),
            Some("hello"),
            "cancelling must leave the previously saved macro body untouched"
        );
        assert!(
            matches!(app.prompt, PromptState::EditMacros { .. }),
            "cancelling the edit returns to the macro list, it does not close the modal"
        );
    }

    /// The live macro-edit state, or a panic naming what was open instead.
    fn macro_edit(app: &App) -> &MacroEditState {
        match &app.prompt {
            PromptState::EditMacros {
                editing: Some(state),
                ..
            } => state,
            other => panic!("expected an open macro editor, got {other:?}"),
        }
    }

    fn macro_focus(app: &App) -> MacroEditFocus {
        macro_edit(app).focus
    }

    /// Point focus at `focus` without going through the keyboard, so a test can
    /// start from any control.
    fn set_macro_focus(app: &mut App, focus: MacroEditFocus) {
        match &mut app.prompt {
            PromptState::EditMacros {
                editing: Some(state),
                ..
            } => state.focus = focus,
            other => panic!("expected an open macro editor, got {other:?}"),
        }
    }

    /// Open the editor on the selected macro, leaving focus where it lands.
    fn open_macro_editor(app: &mut App) {
        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .expect("open the editor on the selected macro");
    }

    fn key(code: KeyCode) -> KeyEvent {
        KeyEvent::new(code, KeyModifiers::NONE)
    }

    /// A single-code key combination as the key event a user would produce.
    fn press(combo: crokey::KeyCombination) -> KeyEvent {
        let crokey::OneToThree::One(code) = combo.codes else {
            panic!("test fixtures use single-code combinations only");
        };
        KeyEvent::new(code, combo.modifiers)
    }

    /// Every focus stop, in forward order.
    const MACRO_FOCUS_ORDER: [MacroEditFocus; 5] = [
        MacroEditFocus::Name,
        MacroEditFocus::Text,
        MacroEditFocus::Surface,
        MacroEditFocus::Cancel,
        MacroEditFocus::Save,
    ];

    #[test]
    fn macro_edit_save_writes_the_macro_and_cancel_does_not() {
        let mut app = app_with_two_macros();
        open_macro_editor_on_body(&mut app);
        type_chars(&mut app, " there");
        app.handle_key(key(KeyCode::Esc)).expect("leave edit mode");
        set_macro_focus(&mut app, MacroEditFocus::Save);
        app.handle_key(key(KeyCode::Enter)).expect("activate Save");

        assert_eq!(
            macro_text(&app, "greet").as_deref(),
            Some("hello there"),
            "Save must write the edited body to config"
        );

        // And now the same edit, abandoned through Cancel.
        open_macro_editor_on_body(&mut app);
        type_chars(&mut app, " again");
        app.handle_key(key(KeyCode::Esc)).expect("leave edit mode");
        set_macro_focus(&mut app, MacroEditFocus::Cancel);
        app.handle_key(key(KeyCode::Enter))
            .expect("activate Cancel");

        assert_eq!(
            macro_text(&app, "greet").as_deref(),
            Some("hello there"),
            "Cancel must not write anything"
        );
        assert!(
            !macro_editing_is_open(&app),
            "Cancel returns to the macro list"
        );
    }

    #[test]
    fn macro_edit_confirm_engages_the_unengaged_body_and_saves_from_elsewhere() {
        let mut app = app_with_two_macros();
        open_macro_editor(&mut app);
        set_macro_focus(&mut app, MacroEditFocus::Text);

        app.handle_key(key(KeyCode::Enter)).expect("confirm");

        assert_eq!(
            app.input_target,
            InputTarget::MacroText,
            "the confirm key must ENGAGE the body, not save from it"
        );
        assert!(
            macro_editing_is_open(&app),
            "engaging leaves the editor open"
        );

        // From the single-line name field the confirm key still submits: Enter
        // is unambiguous there, nothing competes for it.
        app.handle_key(key(KeyCode::Esc)).expect("leave edit mode");
        set_macro_focus(&mut app, MacroEditFocus::Name);
        app.handle_key(key(KeyCode::Enter)).expect("confirm");
        assert!(
            !macro_editing_is_open(&app),
            "the confirm key still submits from a single-line field"
        );
    }

    #[test]
    fn macro_edit_movement_keys_work_while_focus_sits_on_the_unengaged_body() {
        // The body owns no keys until it is engaged, so a movement key parked on
        // it must still move focus rather than being swallowed as content.
        for movement in [KeyCode::Left, KeyCode::Right, KeyCode::Char('h')] {
            let mut app = app_with_two_macros();
            open_macro_editor(&mut app);
            set_macro_focus(&mut app, MacroEditFocus::Text);
            let before = macro_edit(&app).text_input.text.clone();

            app.handle_key(key(movement)).expect("movement key");

            assert_ne!(
                macro_focus(&app),
                MacroEditFocus::Text,
                "{movement:?} must move focus off the unengaged body"
            );
            assert_eq!(
                macro_edit(&app).text_input.text,
                before,
                "{movement:?} must not change the body"
            );
        }
    }

    fn macro_editing_is_open(app: &App) -> bool {
        matches!(
            &app.prompt,
            PromptState::EditMacros {
                editing: Some(_),
                ..
            }
        )
    }

    #[test]
    fn macro_edit_movement_keys_cycle_focus_both_ways_and_change_no_value() {
        let mut app = app_with_two_macros();
        open_macro_editor(&mut app);

        let before = macro_edit(&app).clone();
        assert_eq!(macro_focus(&app), MacroEditFocus::Name);

        // Forwards through every stop and back to the start.
        for expected in MACRO_FOCUS_ORDER
            .iter()
            .skip(1)
            .chain([&MacroEditFocus::Name])
        {
            app.handle_key(key(KeyCode::Tab)).expect("focus forward");
            assert_eq!(macro_focus(&app), *expected, "forward focus order");
        }

        // Backwards through every stop and back to the start.
        // Reversing the visual order from `Name` is exactly the order back.
        for expected in MACRO_FOCUS_ORDER.iter().rev() {
            app.handle_key(key(KeyCode::BackTab)).expect("focus back");
            assert_eq!(macro_focus(&app), *expected, "reverse focus order");
        }

        let after = macro_edit(&app);
        assert_eq!(after.name_input.text, before.name_input.text, "name intact");
        assert_eq!(after.text_input.text, before.text_input.text, "body intact");
        assert_eq!(after.surface, before.surface, "surface intact");
        assert_eq!(
            app.input_target,
            InputTarget::None,
            "movement never engages the body"
        );
    }

    #[test]
    fn macro_edit_space_acts_on_the_focused_control() {
        let mut app = app_with_two_macros();

        // A text field takes the space as a character.
        open_macro_editor(&mut app);
        app.handle_key(key(KeyCode::Char(' '))).expect("space");
        assert_eq!(macro_edit(&app).name_input.text, "greet ");

        // The UNENGAGED body is not a typing surface, so it takes no space.
        set_macro_focus(&mut app, MacroEditFocus::Text);
        app.handle_key(key(KeyCode::Char(' '))).expect("space");
        assert_eq!(
            macro_edit(&app).text_input.text,
            "hello",
            "an unengaged body swallows nothing"
        );
        // Engaged, it takes the space as content like any other character.
        app.handle_key(key(KeyCode::Enter))
            .expect("engage the body");
        app.handle_key(key(KeyCode::Char(' '))).expect("space");
        assert_eq!(macro_edit(&app).text_input.text, "hello ");
        app.handle_key(key(KeyCode::Esc)).expect("leave edit mode");

        // The selector advances.
        set_macro_focus(&mut app, MacroEditFocus::Surface);
        let before = macro_edit(&app).surface;
        app.handle_key(key(KeyCode::Char(' '))).expect("space");
        assert_eq!(macro_edit(&app).surface, before.next());

        // The buttons activate. Cancel first, so nothing is written.
        set_macro_focus(&mut app, MacroEditFocus::Cancel);
        app.handle_key(key(KeyCode::Char(' '))).expect("space");
        assert!(!macro_editing_is_open(&app), "Space cancelled");
        assert_eq!(macro_text(&app, "greet").as_deref(), Some("hello"));

        open_macro_editor(&mut app);
        set_macro_focus(&mut app, MacroEditFocus::Text);
        app.handle_key(key(KeyCode::Enter))
            .expect("engage the body");
        app.handle_key(key(KeyCode::Char(' '))).expect("space");
        set_macro_focus(&mut app, MacroEditFocus::Save);
        app.handle_key(key(KeyCode::Char(' '))).expect("space");
        assert!(!macro_editing_is_open(&app), "Space saved");
        assert_eq!(macro_text(&app, "greet").as_deref(), Some("hello "));
    }

    #[test]
    fn macro_edit_surface_selector_is_reachable_from_every_focus_position() {
        for start in MACRO_FOCUS_ORDER {
            let mut app = app_with_two_macros();
            open_macro_editor(&mut app);
            set_macro_focus(&mut app, start);
            let before = macro_edit(&app).surface;

            // Walk forward until the selector has focus. Five stops means the
            // walk always terminates in at most four presses.
            for _ in 0..MACRO_FOCUS_ORDER.len() {
                if macro_focus(&app) == MacroEditFocus::Surface {
                    break;
                }
                app.handle_key(key(KeyCode::Tab)).expect("focus forward");
            }
            assert_eq!(
                macro_focus(&app),
                MacroEditFocus::Surface,
                "the selector must be reachable from {start:?}"
            );

            app.handle_key(key(KeyCode::Char(' '))).expect("space");
            assert_eq!(
                macro_edit(&app).surface,
                before.next(),
                "the selector must be changeable from {start:?}"
            );
        }
    }

    #[test]
    fn macro_edit_engaged_body_takes_enter_as_a_newline_and_escape_only_exits_edit_mode() {
        let mut app = app_with_two_macros();
        open_macro_editor_on_body(&mut app);
        assert_eq!(
            app.input_target,
            InputTarget::MacroText,
            "reaching the body engages it for typing"
        );

        type_chars(&mut app, "one");
        app.handle_key(key(KeyCode::Enter)).expect("newline");
        type_chars(&mut app, "two");
        assert_eq!(
            macro_edit(&app).text_input.text,
            "helloone\ntwo",
            "Enter is content in the engaged body, not a confirm"
        );

        app.handle_key(key(KeyCode::Esc)).expect("exit edit mode");

        assert_eq!(
            app.input_target,
            InputTarget::None,
            "Escape leaves edit mode"
        );
        assert!(
            macro_editing_is_open(&app),
            "Escape from edit mode leaves the modal open"
        );
        assert_eq!(
            macro_edit(&app).text_input.text,
            "helloone\ntwo",
            "leaving edit mode keeps the text"
        );
        assert_eq!(
            macro_focus(&app),
            MacroEditFocus::Text,
            "leaving edit mode keeps focus on the body"
        );
    }

    /// Render a real frame so the macro editor publishes its true hit rects.
    fn render_macro_editor(app: &mut App) -> super::super::OverlayMouseLayout {
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;

        let mut terminal = Terminal::new(TestBackend::new(120, 40)).expect("terminal");
        terminal
            .draw(|frame| app.render(frame))
            .expect("render frame");
        app.overlay_layout.active
    }

    fn macro_editor_rects(app: &mut App) -> (Rect, Rect, [Rect; 3], Rect, Rect) {
        match render_macro_editor(app) {
            OverlayMouseLayout::EditMacros {
                name_input,
                text_input,
                surface_options,
                cancel_button,
                save_button,
            } => (
                name_input,
                text_input,
                surface_options,
                cancel_button,
                save_button,
            ),
            other => panic!("expected the macro editor layout, got {other:?}"),
        }
    }

    fn click_at(app: &mut App, rect: Rect) {
        let (x, y) = (rect.x + rect.width / 2, rect.y + rect.height / 2);
        app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), x, y));
        app.handle_mouse(mouse(MouseEventKind::Up(MouseButton::Left), x, y));
    }

    #[test]
    fn macro_edit_clicking_a_control_focuses_or_activates_it() {
        let mut app = app_with_two_macros();
        open_macro_editor(&mut app);

        let (name, text, surfaces, cancel, save) = macro_editor_rects(&mut app);

        // Clicking the body focuses it; clicking it again engages it.
        click_at(&mut app, text);
        assert_eq!(macro_focus(&app), MacroEditFocus::Text);
        assert_eq!(
            app.input_target,
            InputTarget::None,
            "one click only focuses"
        );
        click_at(&mut app, text);
        assert_eq!(
            app.input_target,
            InputTarget::MacroText,
            "double click engages"
        );

        // Clicking the name field focuses it back (and leaves edit mode).
        click_at(&mut app, name);
        assert_eq!(macro_focus(&app), MacroEditFocus::Name);
        assert_eq!(app.input_target, InputTarget::None);

        // Clicking a selector option selects exactly that option.
        click_at(&mut app, surfaces[2]);
        assert_eq!(macro_edit(&app).surface, crate::config::MacroSurface::Both);
        assert_eq!(macro_focus(&app), MacroEditFocus::Surface);

        // Clicking Save writes it.
        let (_, _, _, _, save_now) = macro_editor_rects(&mut app);
        assert_eq!(save_now, save, "layout is stable across redraws");
        click_at(&mut app, save_now);
        assert!(!macro_editing_is_open(&app), "Save closed the editor");
        assert_eq!(
            app.engine.config.macros.entries["greet"].surface,
            crate::config::MacroSurface::Both,
            "Save wrote the clicked surface"
        );

        // Clicking Cancel abandons.
        open_macro_editor(&mut app);
        set_macro_focus(&mut app, MacroEditFocus::Text);
        app.handle_key(key(KeyCode::Char('X'))).expect("type");
        let (_, _, _, cancel_now, _) = macro_editor_rects(&mut app);
        assert_eq!(cancel_now, cancel, "layout is stable across redraws");
        click_at(&mut app, cancel_now);
        assert!(!macro_editing_is_open(&app), "Cancel closed the editor");
        assert_eq!(
            macro_text(&app, "greet").as_deref(),
            Some("hello"),
            "Cancel wrote nothing"
        );
    }

    /// Drive the macro editor the way a user does: open a new macro, type the
    /// name, move focus to the body, engage it, type, leave edit mode, confirm.
    fn add_macro_through_the_editor(app: &mut App, name: &str, text: &str) {
        app.handle_key(key(KeyCode::Char('n')))
            .expect("open new macro editor");
        type_chars(app, name);
        app.handle_key(key(KeyCode::Tab))
            .expect("move focus to the body");
        let engage = app
            .bindings
            .first_key_reaching(Action::EngageCommitInput, |_| true)
            .expect("an engage binding");
        app.handle_key(press(engage)).expect("engage the body");
        type_chars(app, text);
        app.handle_key(key(KeyCode::Esc)).expect("leave edit mode");
        // The confirm key ENGAGES the unengaged body rather than saving from it,
        // so the save has to come from the Save button.
        for _ in 0..MACRO_FOCUS_ORDER.len() {
            if macro_focus(app) == MacroEditFocus::Save {
                break;
            }
            app.handle_key(key(KeyCode::Tab)).expect("focus forward");
        }
        app.handle_key(key(KeyCode::Enter)).expect("save");
    }

    #[test]
    fn macro_add_two_both_survive_flush_to_disk() {
        // Regression: when the config snapshot passed to save_eager is built from
        // the CURRENT in-memory macros (not a pre-edit clone), adding A then B
        // must result in BOTH A and B on disk after a flush.
        let mut app = test_app(default_bindings());
        let config_path = app.engine.paths.config_path.clone();
        app.open_edit_macros();

        // Add macro A --------------------------------------------------
        add_macro_through_the_editor(&mut app, "alpha", "Hello A");
        assert!(
            app.engine.config.macros.entries.contains_key("alpha"),
            "macro A must be in config after save"
        );

        // Add macro B --------------------------------------------------
        add_macro_through_the_editor(&mut app, "bravo", "Hello B");
        assert!(
            app.engine.config.macros.entries.contains_key("bravo"),
            "macro B must be in config after save"
        );

        // Flush and check both macros are on disk ----------------------
        app.engine.config_writer.flush();
        let disk = std::fs::read_to_string(&config_path).expect("read config after flush");
        assert!(
            disk.contains("alpha"),
            "macro A (alpha) must appear on disk after flush, got:\n{disk}"
        );
        assert!(
            disk.contains("bravo"),
            "macro B (bravo) must appear on disk after flush, got:\n{disk}"
        );
    }

    #[test]
    fn macro_bar_enter_sends_text_without_bracket_paste_wrapping() {
        // Spawn a PTY running `cat -v` in raw mode. `-v` renders control
        // bytes as printable caret notation (`^[` for ESC), and raw mode
        // disables line discipline so bytes are visible immediately.
        // If the macro handler wraps the text in bracket-paste markers
        // (ESC[200~ ... ESC[201~), the terminal snapshot will contain
        // literal `^[[200` and `^[[201` strings. If the text is sent as-is,
        // only the macro text will appear.
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let client = PtyClient::spawn(
            "sh",
            &["-c".to_string(), "stty raw -echo; exec cat -v".to_string()],
            std::path::Path::new("."),
            5,
            80,
            100,
        )
        .expect("spawn pty");
        app.engine.providers.insert(session_id, client);
        app.input_target = InputTarget::Agent;
        app.session_surface = crate::model::SessionSurface::Agent;

        // Give the shell a moment to enter raw mode and exec cat.
        std::thread::sleep(std::time::Duration::from_millis(250));

        app.engine.config.macros.entries.insert(
            "greet".to_string(),
            crate::config::MacroEntry {
                text: "hello-macro".to_string(),
                surface: crate::config::MacroSurface::Agent,
            },
        );

        app.macro_bar = Some(MacroBarState {
            input: TextInput::new(),
            selected: 0,
            previous_input_target: InputTarget::Agent,
        });

        app.handle_macro_bar_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .expect("handle enter");

        assert!(app.macro_bar.is_none(), "macro bar closes after send");
        assert_eq!(app.status.message(), "Sent macro \"greet\".");

        // Wait for cat to echo the bytes back into the embedded terminal.
        std::thread::sleep(std::time::Duration::from_millis(300));

        let provider = app.engine.providers.values().next().expect("provider");
        let snapshot = provider.snapshot();
        let rendered: String = snapshot
            .cells
            .iter()
            .map(|cell| cell.symbol.as_str())
            .collect();
        assert!(
            rendered.contains("hello-macro"),
            "terminal snapshot should contain raw macro text; got: {rendered:?}"
        );
        assert!(
            !rendered.contains("[200") && !rendered.contains("[201"),
            "macro text must not be wrapped in bracket-paste markers; got: {rendered:?}"
        );
    }

    #[test]
    fn macro_bar_enter_translates_newlines_to_alt_enter() {
        // Spawn a PTY running `cat -v` in raw mode. Control bytes render
        // as caret notation: ESC → `^[`, CR → `^M`. If newlines are sent
        // raw, `cat` would receive a literal LF which (even in raw mode)
        // would not become `^[^M` in the snapshot. If the translation
        // works, the `^[` and `^M` markers will appear between the two
        // halves of the macro text.
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let client = PtyClient::spawn(
            "sh",
            &["-c".to_string(), "stty raw -echo; exec cat -v".to_string()],
            std::path::Path::new("."),
            5,
            80,
            100,
        )
        .expect("spawn pty");
        app.engine.providers.insert(session_id, client);
        app.input_target = InputTarget::Agent;
        app.session_surface = crate::model::SessionSurface::Agent;

        std::thread::sleep(std::time::Duration::from_millis(250));

        app.engine.config.macros.entries.insert(
            "multi".to_string(),
            crate::config::MacroEntry {
                text: "first\nsecond".to_string(),
                surface: crate::config::MacroSurface::Agent,
            },
        );

        app.macro_bar = Some(MacroBarState {
            input: TextInput::new(),
            selected: 0,
            previous_input_target: InputTarget::Agent,
        });

        app.handle_macro_bar_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .expect("handle enter");

        assert_eq!(app.status.message(), "Sent macro \"multi\".");

        std::thread::sleep(std::time::Duration::from_millis(300));

        let provider = app.engine.providers.values().next().expect("provider");
        let snapshot = provider.snapshot();
        let rendered: String = snapshot
            .cells
            .iter()
            .map(|cell| cell.symbol.as_str())
            .collect();

        assert!(
            rendered.contains("first") && rendered.contains("second"),
            "both halves of the macro text should be visible; got: {rendered:?}"
        );
        assert!(
            rendered.contains("^[") && rendered.contains("^M"),
            "newline should have been translated to ESC+CR (`^[^M`); got: {rendered:?}"
        );
    }

