    /// A modal's single-line field takes the paste while IT has focus, and
    /// drops it while focus sits on the checkbox (typing a field that draws
    /// no caret would be invisible).
    #[test]
    fn paste_into_a_modal_field_follows_focus() {
        let mut app = test_app(default_bindings());
        app.prompt = PromptState::RenameSession {
            session_id: "session-1".to_string(),
            input: TextInput::new(),
            rename_branch: false,
            focus: RenameSessionFocus::Input,
            branch_named: true,
        };
        app.handle_paste("new name");
        if let PromptState::RenameSession { input, .. } = &app.prompt {
            assert_eq!(input.text, "new name");
        } else {
            panic!("prompt must stay open");
        }

        if let PromptState::RenameSession { focus, .. } = &mut app.prompt {
            *focus = RenameSessionFocus::RenameBranchCheckbox;
        }
        app.handle_paste(" more");
        if let PromptState::RenameSession { input, .. } = &app.prompt {
            assert_eq!(
                input.text, "new name",
                "a paste with focus on the checkbox is dropped"
            );
        }
    }

    /// A modal full-text field takes a paste only while ENGAGED; unengaged it
    /// owns no keys at all, pastes included.
    #[test]
    fn paste_into_a_configure_modal_requires_engagement() {
        let mut app = test_app(default_bindings());
        app.prompt = PromptState::ConfigureStartupCommand {
            project_id: "project-1".to_string(),
            project_name: "demo".to_string(),
            input: TextInput::new().with_multiline(4),
            focus: crate::app::ConfigureFieldFocus::Input,
        };

        app.handle_paste("npm install\nnpm run dev");
        if let PromptState::ConfigureStartupCommand { input, .. } = &app.prompt {
            assert!(
                input.text.is_empty(),
                "an unengaged full-text field takes no paste"
            );
        }

        app.input_target = InputTarget::StartupCommand;
        app.handle_paste("npm install\nnpm run dev");
        if let PromptState::ConfigureStartupCommand { input, .. } = &app.prompt {
            assert_eq!(
                input.text, "npm install\nnpm run dev",
                "the engaged field takes the paste verbatim"
            );
        }
    }

    /// With no typing surface focused the paste is dropped: nothing reaches
    /// a PTY and no binding fires.
    #[test]
    fn paste_with_nothing_focused_is_dropped() {
        let mut app = typeable_app_with_paste_child("");
        app.focus = FocusPane::Left;
        assert!(!app.center_typeable());

        app.handle_paste("hello");

        std::thread::sleep(std::time::Duration::from_millis(300));
        let rendered = paste_child_grid(&app);
        assert!(
            !rendered.contains("hello"),
            "a paste with nothing focused must not reach the PTY; got {rendered:?}"
        );
        assert!(app.commit_input.text.is_empty());
    }

    /// A dormant center pane has no PTY to send to, so the Center-scope chord
    /// reports that instead of opening a bar whose send would go nowhere.
    #[test]
    fn minimized_macro_bar_needs_a_live_surface() {
        let mut app = test_app(default_bindings());
        app.focus = FocusPane::Center;
        app.center_mode = CenterMode::Agent;
        // No provider inserted: the focused tab is dormant.
        app.engine.config.macros.entries.insert(
            "greet".to_string(),
            crate::config::MacroEntry {
                text: "hello-macro".to_string(),
                surface: crate::config::MacroSurface::Agent,
            },
        );

        app.handle_key(KeyEvent::new(KeyCode::Char('\\'), KeyModifiers::CONTROL))
            .expect("handle ctrl-backslash");

        assert!(
            app.macro_bar.is_none(),
            "no macro bar over a dormant pane: there is nothing to send to"
        );
    }

    #[test]
    fn change_default_provider_updates_config_and_refreshes_projects() {
        let mut app = test_app(default_bindings());
        app.engine.config.defaults.provider = "codex".to_string();

        // project-2 pins itself to "gemini" and must not be touched.
        let pinned = Project {
            id: "project-2".to_string(),
            name: "pinned".to_string(),
            path: app.engine.paths.root.join("pinned").display().to_string(),
            explicit_default_provider: Some(ProviderKind::from_str("gemini")),
            default_provider: ProviderKind::from_str("gemini"),
            leading_branch: Some("main".to_string()),
            auto_reopen_agents: None,
            startup_command: None,
            env: Default::default(),
            current_branch: "main".to_string(),
            branch_status: ProjectBranchStatus::Unknown,
            path_missing: false,
            created_at: None,
        };
        app.engine
            .session_store
            .upsert_project(&ProjectConfig {
                id: pinned.id.clone(),
                path: pinned.path.clone(),
                name: Some(pinned.name.clone()),
                default_provider: Some("gemini".to_string()),
                leading_branch: Some("main".to_string()),
                auto_reopen_agents: None,
                startup_command: None,
                env: pinned.env.clone(),
            })
            .expect("seed pinned project");
        app.engine.projects.push(pinned);

        let original_session_provider = app.engine.sessions[0].provider.clone();

        app.open_change_default_provider_prompt()
            .expect("open default provider picker");
        match &mut app.prompt {
            PromptState::ChangeDefaultProvider(prompt) => {
                prompt.selected = prompt
                    .options
                    .iter()
                    .position(|option| option.provider.as_str() == "claude")
                    .expect("claude option present");
            }
            other => panic!("expected change-default-provider prompt, got {other:?}"),
        }

        app.apply_change_default_provider()
            .expect("apply default provider");

        // Config was updated in memory and on disk.
        assert_eq!(app.engine.config.defaults.provider, "claude");
        let persisted = crate::config::ensure_config(&app.engine.paths).expect("reload config");
        assert_eq!(persisted.defaults.provider, "claude");

        // Inherited project picks up the new default.
        let inherited = app
            .engine
            .projects
            .iter()
            .find(|project| project.id == "project-1")
            .expect("inherited project present");
        assert_eq!(inherited.default_provider.as_str(), "claude");

        // Pinned project keeps its explicit override.
        let pinned = app
            .engine
            .projects
            .iter()
            .find(|project| project.id == "project-2")
            .expect("pinned project present");
        assert_eq!(pinned.default_provider.as_str(), "gemini");

        // Existing sessions are untouched — provider is frozen at creation.
        assert_eq!(app.engine.sessions[0].provider, original_session_provider);

        assert!(matches!(app.prompt, PromptState::None));
        assert!(
            app.status
                .text()
                .contains("Global default provider changed to claude")
        );
    }

