    #[test]
    fn agent_pane_title_keeps_running_provider_after_swap_while_running() {
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;

        let mut app = test_app(default_bindings());
        app.engine.projects[0].default_provider = ProviderKind::from_str("codex");
        app.engine.sessions[0].provider = ProviderKind::from_str("codex");
        app.engine.sessions[0].status = SessionStatus::Active;
        let session_id = app.engine.sessions[0].id.clone();

        // Spawn a real PTY so the session looks live.
        let worktree = std::path::Path::new(
            app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        let pty = PtyClient::spawn(
            "/bin/sh",
            &["-c".to_string(), "sleep 5".to_string()],
            worktree,
            24,
            80,
            1_000,
        )
        .expect("spawn test agent");
        app.engine.providers.insert(session_id.clone(), pty);

        app.rebuild_left_items();
        app.selected_left = app
            .left_items()
            .iter()
            .position(|item| matches!(item, LeftItem::Session(index) if *index == 0))
            .expect("select the running session");

        // Swap provider while the agent is still running.
        app.open_change_agent_provider_prompt()
            .expect("open picker");
        match &mut app.prompt {
            PromptState::ChangeAgentProvider(prompt) => {
                prompt.selected = prompt
                    .options
                    .iter()
                    .position(|option| option.provider.as_str() == "opencode")
                    .expect("opencode option");
            }
            other => panic!("expected picker, got {other:?}"),
        }
        app.apply_change_agent_provider().expect("apply swap");

        // session.provider is now opencode, but the PTY is still running codex;
        // running_provider_for should reflect that.
        assert_eq!(app.engine.sessions[0].provider.as_str(), "opencode");
        assert_eq!(
            app.engine
                .running_provider_for(&app.engine.sessions[0])
                .as_str(),
            "codex"
        );

        let backend = TestBackend::new(200, 30);
        let mut terminal = Terminal::new(backend).expect("terminal");
        terminal
            .draw(|frame| app.render(frame))
            .expect("render frame");
        let rendered: String = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect();
        assert!(
            rendered.contains("Codex agent"),
            "pane title should still say Codex (running) after the swap, got: {rendered}"
        );
        assert!(
            !rendered.contains("Opencode agent"),
            "pane title should NOT claim Opencode is running yet, got: {rendered}"
        );

        // The flat sidebar row no longer carries a provider suffix (it matches the
        // web row: name + PR on line one, project + state on line two). The
        // running provider still surfaces in the center pane title, asserted
        // above; the swap is otherwise reflected in the agent tab strip.

        // Tearing down the PTY clears the pin — the next launch will be opencode.
        app.engine.providers.remove(&session_id);
        app.engine.running_provider_pins.remove(&session_id);
        assert_eq!(
            app.engine
                .running_provider_for(&app.engine.sessions[0])
                .as_str(),
            "opencode"
        );

        // With the PTY gone, `running_provider_for` reports opencode (the pinned
        // running provider is cleared); the flat row shows no provider suffix, so
        // there is no sidebar arrow to collapse.
    }

    fn spawn_test_provider(worktree: &std::path::Path) -> PtyClient {
        PtyClient::spawn(
            "/bin/sh",
            &["-c".to_string(), "sleep 5".to_string()],
            worktree,
            24,
            80,
            1_000,
        )
        .expect("spawn test provider")
    }

    fn insert_support_tab(app: &mut App, session_id: &str, tab_id: &str) {
        app.engine.agent_tabs.insert(
            tab_id.to_string(),
            dux_core::model::AgentTab {
                id: tab_id.to_string(),
                session_id: session_id.to_string(),
                provider: dux_core::model::ProviderKind::new("codex"),
                sort_order: 1,
                created_at: chrono::Utc::now(),
            },
        );
    }

    #[test]
    fn confirm_close_support_tab_closes_and_refocuses_main() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::PathBuf::from(
            &app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        let tab_id = "tab-1".to_string();
        insert_support_tab(&mut app, &session_id, &tab_id);
        app.engine
            .providers
            .insert(tab_id.clone(), spawn_test_provider(&worktree));
        app.set_focused_tab(&session_id, &tab_id);

        app.prompt = PromptState::ConfirmCloseTab {
            session_id: session_id.clone(),
            tab_id: tab_id.clone(),
            provider_label: "Codex".to_string(),
            is_main: false,
            focus: ConfirmFocus::Confirm,
        };
        // Space activates the focused (Close) button.
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .expect("handle close");

        assert!(
            !app.engine.agent_tabs.contains_key(&tab_id),
            "closing an extra tab must delete its row"
        );
        assert_eq!(
            app.focused_tab_id(&session_id),
            session_id,
            "falls back to session-slot when no live sibling remains"
        );
    }

    #[test]
    fn closing_focused_tab_refocuses_live_sibling_not_dormant_main() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::PathBuf::from(
            &app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        // The session-slot tab is dormant (no provider). Two extra tabs, both live.
        insert_support_tab(&mut app, &session_id, "tab-1");
        app.engine
            .providers
            .insert("tab-1".to_string(), spawn_test_provider(&worktree));
        insert_support_tab(&mut app, &session_id, "tab-2");
        app.engine
            .providers
            .insert("tab-2".to_string(), spawn_test_provider(&worktree));
        app.set_focused_tab(&session_id, "tab-1");
        app.focus = FocusPane::Center;

        app.prompt = PromptState::ConfirmCloseTab {
            session_id: session_id.clone(),
            tab_id: "tab-1".to_string(),
            provider_label: "Codex".to_string(),
            is_main: false,
            focus: ConfirmFocus::Confirm,
        };
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .expect("handle close");

        assert!(!app.engine.agent_tabs.contains_key("tab-1"));
        assert_eq!(
            app.focused_tab_id(&session_id),
            "tab-2",
            "focus should land on the live sibling, not the dormant session-slot tab"
        );
    }

    #[test]
    fn closing_main_tab_refocuses_live_sibling_not_dormant_main() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::PathBuf::from(
            &app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        // The session-slot tab is live; one extra tab is also live. Closing
        // the session-slot (main) tab should refocus the live extra tab, not
        // leave focus stuck on the now-dormant session-slot id.
        let tab_id = "tab-1".to_string();
        insert_support_tab(&mut app, &session_id, &tab_id);
        app.engine
            .providers
            .insert(session_id.clone(), spawn_test_provider(&worktree));
        app.engine
            .providers
            .insert(tab_id.clone(), spawn_test_provider(&worktree));
        app.set_focused_tab(&session_id, &session_id);
        app.focus = FocusPane::Center;

        app.prompt = PromptState::ConfirmCloseTab {
            session_id: session_id.clone(),
            tab_id: session_id.clone(),
            provider_label: "Codex".to_string(),
            is_main: true,
            focus: ConfirmFocus::Confirm,
        };
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .expect("handle close");

        assert_eq!(
            app.focused_tab_id(&session_id),
            tab_id,
            "focus should land on the live sibling, not the dormant session-slot tab"
        );
    }

    #[test]
    fn ctrl_g_after_closing_tab_enters_live_sibling_without_relaunch() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::PathBuf::from(
            &app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        insert_support_tab(&mut app, &session_id, "tab-1");
        app.engine
            .providers
            .insert("tab-1".to_string(), spawn_test_provider(&worktree));
        insert_support_tab(&mut app, &session_id, "tab-2");
        app.engine
            .providers
            .insert("tab-2".to_string(), spawn_test_provider(&worktree));
        app.set_focused_tab(&session_id, "tab-1");
        app.focus = FocusPane::Center;
        app.center_mode = CenterMode::Agent;

        app.prompt = PromptState::ConfirmCloseTab {
            session_id: session_id.clone(),
            tab_id: "tab-1".to_string(),
            provider_label: "Codex".to_string(),
            is_main: false,
            focus: ConfirmFocus::Confirm,
        };
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .expect("handle close");

        let in_flight_before = app
            .engine
            .is_in_flight(&dux_core::engine::InFlightKey::AgentLaunch("tab-2".into()));
        assert!(!in_flight_before, "tab-2 already has a live provider");

        // Ctrl-g in the non-interactive Center pane should enter interactive
        // mode on the live sibling, not relaunch it.
        app.handle_key(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::CONTROL))
            .unwrap();

        assert_eq!(app.input_target, InputTarget::Agent);
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Agent);
        assert!(
            !app.engine
                .is_in_flight(&dux_core::engine::InFlightKey::AgentLaunch("tab-2".into())),
            "no new launch should have been dispatched for the live sibling"
        );
    }

    #[test]
    fn confirm_close_main_tab_detaches_without_deleting() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::PathBuf::from(
            &app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        // An extra tab exists; detaching the session-slot tab must NOT touch it.
        let tab_id = "tab-1".to_string();
        insert_support_tab(&mut app, &session_id, &tab_id);
        app.engine
            .providers
            .insert(session_id.clone(), spawn_test_provider(&worktree));

        app.prompt = PromptState::ConfirmCloseTab {
            session_id: session_id.clone(),
            tab_id: session_id.clone(),
            provider_label: "Codex".to_string(),
            is_main: true,
            focus: ConfirmFocus::Confirm,
        };
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .expect("handle detach");

        assert!(
            !app.engine.providers.contains_key(&session_id),
            "detaching the session-slot tab stops its provider"
        );
        assert!(
            app.engine.agent_tabs.contains_key(&tab_id),
            "detaching the session-slot tab must not delete extra tab rows"
        );
    }

    #[test]
    fn kill_running_lists_live_support_tab_and_keeps_its_row() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        let worktree = std::path::PathBuf::from(
            &app.engine.sessions[0]
                .managed_worktree()
                .expect("managed test session"),
        );
        let tab_id = "tab-1".to_string();
        insert_support_tab(&mut app, &session_id, &tab_id);
        app.engine
            .providers
            .insert(tab_id.clone(), spawn_test_provider(&worktree));

        let snapshot = app.running_runtime_snapshot();
        assert!(
            snapshot
                .iter()
                .any(|r| r.id == RuntimeTargetId::Tab(tab_id.clone())),
            "a live extra tab should be a killable runtime"
        );

        let (agents, _terminals) =
            app.kill_runtime_targets(&[RuntimeTargetId::Tab(tab_id.clone())]);
        assert_eq!(agents, 1, "killing the extra tab counts as an agent kill");
        assert!(
            !app.engine.providers.contains_key(&tab_id),
            "killing an extra tab stops its process"
        );
        assert!(
            app.engine.agent_tabs.contains_key(&tab_id),
            "killing an extra tab keeps its row (it becomes dormant)"
        );
    }

    fn name_new_agent_prompt_with_focus(app: &App, focus: NameNewAgentFocus) -> PromptState {
        PromptState::NameNewAgent {
            request: CreateAgentRequest::NewProject {
                project: app.engine.projects[0].clone(),
                custom_name: None,
                use_existing_branch: false,
                pull_before_create: false,
                copy_uncommitted_changes: false,
            },
            input: TextInput::with_text("agent".to_string()),
            randomize_name: false,
            randomized_name: None,
            copy_changes: false,
            focus,
        }
    }

    #[test]
    fn name_new_agent_printable_does_not_edit_field_while_checkbox_focused() {
        // A focused checkbox draws no caret, so a keystroke there must not
        // silently append to the (unfocused) name field.
        for focus in [
            NameNewAgentFocus::RandomizedNameCheckbox,
            NameNewAgentFocus::CopyChangesCheckbox,
        ] {
            let mut app = test_app(default_bindings());
            app.prompt = name_new_agent_prompt_with_focus(&app, focus);

            app.handle_key(KeyEvent::new(KeyCode::Char('y'), KeyModifiers::NONE))
                .unwrap();

            match &app.prompt {
                PromptState::NameNewAgent {
                    input,
                    focus: current,
                    ..
                } => {
                    assert_eq!(input.text, "agent", "printable must not edit the field");
                    assert_eq!(*current, focus, "printable must not move focus");
                }
                other => panic!("expected NameNewAgent, got {other:?}"),
            }
        }
    }

    #[test]
    fn name_new_agent_printable_types_while_input_focused() {
        let mut app = test_app(default_bindings());
        app.prompt = name_new_agent_prompt_with_focus(&app, NameNewAgentFocus::Input);

        app.handle_key(KeyEvent::new(KeyCode::Char('y'), KeyModifiers::NONE))
            .unwrap();

        match &app.prompt {
            PromptState::NameNewAgent { input, .. } => assert_eq!(input.text, "agenty"),
            other => panic!("expected NameNewAgent, got {other:?}"),
        }
    }

    #[test]
    fn name_new_agent_space_toggles_focused_checkbox_and_types_in_the_field() {
        let mut app = test_app(default_bindings());
        app.prompt = name_new_agent_prompt_with_focus(&app, NameNewAgentFocus::CopyChangesCheckbox);

        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .unwrap();

        match &app.prompt {
            PromptState::NameNewAgent {
                input,
                copy_changes,
                ..
            } => {
                assert!(*copy_changes, "Space should toggle the focused checkbox");
                assert_eq!(input.text, "agent", "Space must not reach the field");
            }
            other => panic!("expected NameNewAgent, got {other:?}"),
        }

        app.prompt = name_new_agent_prompt_with_focus(&app, NameNewAgentFocus::Input);
        app.handle_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE))
            .unwrap();

        match &app.prompt {
            PromptState::NameNewAgent { input, .. } => {
                assert_eq!(
                    input.text, "agent ",
                    "Space should type when the field owns focus"
                );
            }
            other => panic!("expected NameNewAgent, got {other:?}"),
        }
    }

    #[test]
    fn name_new_agent_movement_keys_navigate_while_a_checkbox_has_focus() {
        // With both checkboxes present the walk is
        // Input → Randomized → Copy → Input, and its mirror backwards. None of
        // these keys may edit the field or change a checkbox value.
        let cases = [
            (
                KeyCode::Char('l'),
                NameNewAgentFocus::RandomizedNameCheckbox,
                NameNewAgentFocus::CopyChangesCheckbox,
            ),
            (
                KeyCode::Right,
                NameNewAgentFocus::RandomizedNameCheckbox,
                NameNewAgentFocus::CopyChangesCheckbox,
            ),
            (
                KeyCode::Char('h'),
                NameNewAgentFocus::CopyChangesCheckbox,
                NameNewAgentFocus::RandomizedNameCheckbox,
            ),
            (
                KeyCode::Left,
                NameNewAgentFocus::CopyChangesCheckbox,
                NameNewAgentFocus::RandomizedNameCheckbox,
            ),
        ];

        for (code, from, expected) in cases {
            let mut app = test_app(default_bindings());
            app.prompt = name_new_agent_prompt_with_focus(&app, from);

            app.handle_key(KeyEvent::new(code, KeyModifiers::NONE))
                .unwrap();

            match &app.prompt {
                PromptState::NameNewAgent {
                    input,
                    focus,
                    randomize_name,
                    copy_changes,
                    ..
                } => {
                    assert_eq!(*focus, expected, "{code:?} from {from:?} should navigate");
                    assert!(!*randomize_name, "{code:?} must not change a value");
                    assert!(!*copy_changes, "{code:?} must not change a value");
                    assert_eq!(input.text, "agent", "{code:?} must not edit the field");
                }
                other => panic!("expected NameNewAgent, got {other:?}"),
            }
        }
    }

